window.LAW_DATA = {"id": "okoubat", "title": "قانون العقوبات", "title_en": "PENAL CODE", "cat": "جنائي", "icon": "⚔️", "desc": "القانون رقم 58 لسنة 1937 — الجرائم والعقوبات المقررة لها بكافة أنواعها.", "article_count": 502, "articles": [{"number": "1", "chapter": "", "text": "تسرى أحكام هذا القانون على كل من يرتكب فى القطر المصرى جريمة من الجرائم المنصوص عليها فيه."}, {"number": "2", "chapter": "", "text": "تسرى أحكام هذا القانون أيضا على الأشخاص الآتى ذكرهم : أولاً : كل من ارتكب فى خارج القطر فعلا يجعله فاعلا أو شريكا فى جريمة وقعت كلها أو بعضها فى القطر المصرى . ثانياً : كل من ارتكب فى خارج القطر جريمة من الجرائم الآتية: أ - جناية مخلة بأمن الحكومة مما نص عليه فى البابين الأول والثانى من الكتاب الثانى من هذا القانون . ب - جناية تزوير مما نص عليه فى المادة 206 من هذا القانون . ج - جناية تقليد أو تزييف أو تزوير عملة ورقية أو معدنية مما نص عليه فى المادة 202 أو جناية إدخال تلك العملة الورقية أو المعدنية المقلدة أو المزيفة أو المزورة إلى مصر أو إخراجها منها أو ترويجها أو حيازتها بقصد الترويج أو التعامل بها مما نص عليه فى المادة 203 بشرط أن تكون العملة متداولة قانونا فى مصر. مستبدلة بالقانون 68 لسنة 1956"}, {"number": "3", "chapter": "", "text": "كل مصرى ارتكب وهو فى خارج القطر فعلا يعتبر جناية أو جنحة فى هذا القانون يعاقب بمقتضى أحكامه إذا عاد إلى القطر وكان الفعل معاقبا عليه بمقتضى قانون البلد الذى ارتكبه فيه ."}, {"number": "4", "chapter": "", "text": "لا تقام الدعوى العمومية على مرتكب جريمة أو فعل فى الخارج إلا من النيابة العمومية . ولا تجوز إقامتها على من يثبت أن المحاكم الأجنبية برأته مما أسند إليه أو أنها حكمت عليه نهائيا واستوفى عقوبته."}, {"number": "5", "chapter": "", "text": "يعاقب على الجرائم بمقتضى القانون المعمول به وقت ارتكابها . ومع هذا إذا صدر بعد وقوع الفعل وقبل الحكم فيه نهائيا قانون أصلح للمتهم فهو الذى يتبع دون غيره . وإذا صدر قانون بعد حكم نهائى يجعل الفعل الذى حكم على المجرم من أجله غير معاقب عليه يوقف تنفيذ الحكم وتنتهى آثاره الجنائية . غير أنه فى حالة قيام إجراءات الدعوى أو صدور حكم بالإدانة فيها ، وكان ذلك عن فعل وقع مخالفا لقانون ينهى عن ارتكابه فى فترة محددة فإن انتهاء هذه الفترة لا يحول دون السير فى الدعوى أو تنفيذ العقوبات المحكوم بها."}, {"number": "6", "chapter": "", "text": "لا يمس الحكم بالعقوبات المنصوص عليها فى القانون ما يكون واجبا للخصوم من الرد والتعويض."}, {"number": "7", "chapter": "", "text": "لا تخل أحكام هذا القانون فى أى حال من الأحوال بالحقوق الشخصية المقررة فى الشريعة الغراء."}, {"number": "8", "chapter": "", "text": "تراعى أحكام الكتاب الأول من هذا القانون فى الجرائم المنصوص عليها فى القوانين واللوائح الخصوصية إلا إذا وجد فيها نص يخالف ذلك. البـاب الثانـى أنـواع الجـرائـم"}, {"number": "9", "chapter": "", "text": "الجرائم ثلاثة أنواع : الأول : الجنايـات . الثانى : الجنـح . الثالث : المخالفات ."}, {"number": "10", "chapter": "", "text": "الجنايات هى الجرائم المعاقب عليها بالعقوبات الآتية : الإعدام . السجن المؤبد . السجن المشدد . السجن . استبدلت عبارة \" السجن المؤبد \" بعبارة \" الاشغال المؤبدة \" وعبارة \" السجن المشدد \" بعبارة \" الاشغال المؤقتة \" وذلك بالقانون 95 لسنة 2003 الجريدة الرسمية العدد 25 تابع."}, {"number": "11", "chapter": "", "text": "الجنح هى الجرائم المعاقب عليها بالعقوبات الآتية: الحبس . الغرامة التى يزيد أقصى مقدار لها على مائة جنيه . مستبدلة بالقانون 169 لسنة 1981 ."}, {"number": "12", "chapter": "", "text": "المخالفات هى الجرائم المعاقب عليها بالغرامة التى لا يزيد أقصى مقدار لها على مائة جنيه . مستبدلة بالقانون 169 لسنة 1981 . البـاب الثالـث العقوبـات القسـم الأول العقوبات الأصليـة"}, {"number": "13", "chapter": "", "text": "كل محكوم عليه بالإعدام يشنق ."}, {"number": "14", "chapter": "", "text": "السجن المؤبد والسجن المشدد هما وضع المحكوم عليه في أحد السجون المخصصة لذلك قانونا ، وتشغيله داخلها في الأعمال التي تعينها الحكومة ، وذلك مدة حياته إذا كانت العقوبة مؤبدة ، أو لمدة المحكوم بها إذا كنت مشددة . ولا يجوز أن تنقص مدة عقوبة السجن المشدد عن ثلاث سنين ولا أن تزيد على خمس عشرة سنة إلا في الأحوال الخاصة المنصوص عليها قانونا. معدلة بالقانون 95 لسنة 2003"}, {"number": "15", "chapter": "", "text": "يقضى من يحكم عليه بعقوبة السجن المشدد من الرجال اللذين جاوزوا الستين من عمرهم ومن النساء مطلقا مدة عقوبته فى أحد السجون العمومية."}, {"number": "16", "chapter": "", "text": "عقوبة السجن هى وضع المحكوم عليه فى أحد السجون العمومية وتشغيله داخل السجن أو خارجه فى الأعمال التى تعينها الحكومة المدة المحكوم بها عليه ، ولا يجوز أن تنقص تلك المدة عن ثلاث سنين ولا أن تزيد على خمس عشرة سنة إلا فى الأحوال الخصوصية المنصوص عليها قانونا ."}, {"number": "17", "chapter": "", "text": "يجوز فى مواد الجنايات إذا اقتضت أحوال الجريمة المقامة من أجلها الدعوى العمومية رأفة القضاة تبديل العقوبة على الوجه الآتى : عقوبة الإعدام بعقوبة السجن المؤبد أو السجن المشدد . عقوبة السجن المؤبد بعقوبة السجن المشدد أو السجن. عقوبة السجن المشدد بعقوبة السجن أو الحبس الذى لا يجوز أن ينقص عن ستة شهور . عقوبة السجن بعقوبة الحبس الذى لا يجوز أن ينقص عن ثلاثة شهور. معدلة بالقانون 95 لسنة 2003 ."}, {"number": "18", "chapter": "", "text": "عقوبة الحبس هى وضع المحكوم عليه فى أحد السجون المركزية أو العمومية المدة المحكوم بها عليه ولا يجوز أن تنقص هذه المدة عن أربع وعشرين ساعة ولا أن تزيد على ثلاث سنين إلا فى الأحوال الخصوصية المنصوص عليها قانونا. لكل محكوم عليه بالحبس البسيط لمدة لا تتجاوز ستة أشهر أن يطلب بدلاً من تنفيذ عقوبة الحبس عليه تشغيله خارج السجن طبقاً للقيود المقررة بقانون الإجراءات الجنائية إلا إذا نص الحكم على حرمانه من هذا الخيار."}, {"number": "معدلة بالقانون رقم", "chapter": "", "text": "49 لسنة 2014"}, {"number": "19", "chapter": "", "text": "عقوبة الحبس نوعان : الحبس البسيط . الحبس مع الشغل . والمحكوم عليهم بالحبس مع الشغل يشتغلون داخل السجون أو خارجها فى الأعمال التى تعينها الحكومة ."}, {"number": "20", "chapter": "", "text": "يجب على القاضى أن يحكم بالحبس مع الشغل كلما كانت مدة العقوبة المحكوم بها سنة فأكثر ، وكذلك فى الأحوال الأخرى المعينة قانوناً . وفى كل الأحوال الأخرى يجوز الحكم بالحبس البسيط أو مع الشغل."}, {"number": "21", "chapter": "", "text": "تبتدئ مدة العقوبات المقيدة للحرية من يوم أن يحبس المحكوم عليه بناء على الحكم الواجب التنفيذ مع مراعاة إنقاصها بمقدار مدة الحبس الاحتياطى."}, {"number": "22", "chapter": "", "text": "العقوبة بالغرامة هى إلزام المحكوم عليه بأن يدفع إلى خزينة الحكومة المبلغ المقدر فى الحكم . ولا يجوز أن تقل الغرامة عن مائة قرش ولا أن يزيد حدها الأقصى فى الجنح على خمسمائة جنيه وذلك مع عدم الإخلال بالحدود التى يبينها القانون لكل جريمة ."}, {"number": "23", "chapter": "", "text": "إذا حبس شخص احتياطيا ولم يحكم عليه إلا بغرامة وجب أن ينقص منها عند التنفيذ خمسة جنيهات عن كل يوم من أيام الحبس المذكور . وإذا حكم عليه بالحبس وبالغرامة معا ، وكانت المدة التى قضاها فى الحبس الاحتياطى تزيد عن مدة الحبس المحكوم به وجب أن ينقص من الغرامة المبلغ المذكور عن كل يوم من أيام الزيادة المذكورة. القسـم الثانـى العقوبات التبعية"}, {"number": "24", "chapter": "", "text": "العقوبات التبعية هى : أولاً : الحرمان من الحقوق والمزايا المنصوص عليها فى المادة 25 ثانياً : العزل من الوظائف الأميرية . ثالثاً : وضع المحكوم عيه تحت مراقبة البوليس . رابعاً : المصادرة ."}, {"number": "25", "chapter": "", "text": "كل حكم بعقوبة جناية يستلزم حتما حرمان المحكوم عليه من الحقوق والمزايا الآتية : أولاً : القبول فى أية خدمة فى الحكومة مباشرة أو بصفة متعهد أو ملتزم أيا كانت أهمية الخدمة . ثانياً : التحلى برتبة أو نيشان . ثالثاً : الشهادة أمام المحاكم مدة العقوبة إلا على سبيل الاستدلال . رابعاً : إدارة أشغاله الخاصة بأمواله وأملاكه مدة اعتقاله ويعين قيما لهذه الإدارة تقره المحكمة ، فإذا لم يعينه ، عينته المحكمة المدنية التابع لها محل إقامته فى غرفة مشورتها بناء على طلب النيابة العمومية أو ذى مصلحة فى ذلك ويجوز للمحكمة أن تلزم القيم الذى تنصبه بتقديم كفالة . ويكون القيم الذى تقره المحكمة أو تنصبه تابعا لها فى جميع ما يتعلق بقوامته . ولا يجوز للمحكوم عليه أن يتصرف فى أمواله إلا بناء على إذن من المحكمة المدنية المذكورة ، وكل التزام يتعهد به مع عدم مراعاة ما تقدم يكون ملغى من ذاته وترد أموال المحكوم عليه إليه بعد انقضاء مدة عقوبته أو الإفراج عنه ويقدم له القيم حسابا عن إدارته . خامساً : بقاؤه من يوم الحكم عليه نهائيا عضوا فى أحد المجالس الحسبية أو مجالس المديريات أو المجالس البلدية أو المحلية أو أى لجنة عمومية . سادساً : صلاحيته أبدا لأن يكون عضوا فى إحدى الهيئات المبينة بالفقرة الخامسة أو يكون خبيرا أو شاهدا فى العقود إذا حكم علية نهائيا بعقوبة السجن المشدد . معدلة بالقانون 95 لسنة 2003 ."}, {"number": "26", "chapter": "", "text": "العزل من وظيفة أميرية هو الحرمان من الوظيفة نفسها ومن المرتبات المقررة لها . وسواء كان المحكوم عليه بالعزل عاملا فى وظيفته وقت صدور الحكم عليه أو غير عامل فيها لا يجوز تعيينه فى وظيفة أميرية ولا نيله أى مرتب مدة يقدرها الحكم وهذه المدة لا يجوز أن تكون أكثر من ستة سنين ولا أقل من سنة واحدة."}, {"number": "27", "chapter": "", "text": "كل موظف ارتكب جناية مما نص عليه فى الباب الثالث والرابع والسادس والسادس عشر من الكتاب الثانى من هذا القانون عومل بالرأفة فحكم عليه بالحبس يحكم عليه أيضا بالعزل مدة لا تنقص عن ضعف مدة الحبس المحكوم بها عليه."}, {"number": "28", "chapter": "", "text": "كل من يحكم عليه بالسجن المؤبد أو المشدد أو السجن لجناية مخلة بأمن الحكومة أو تزييف نقود أو سرقة أو قتل فى الأحوال المبينة فى الفقرة الثانية من المادة 234 من هذا القانون أو لجناية من المنصوص عليها فى المواد 356 ، 368 ، يجب وضعه بعد انقضاء مدة عقوبته تحت مراقبة البوليس مدة مساوية لمدة عقوبته بدون أن تزيد مدة المراقبة على خمس سنين . ومع ذلك يجوز للقاضى أن يخفض مدة المراقبة أو أن يقضى بعدمها جملة معدلة بالقانون 95 لسنة 2003 ."}, {"number": "29", "chapter": "", "text": "يترتب على مراقبة البوليس إلزام المحكوم عليه بجميع الأحكام المقررة فى القوانين المختصة بتلك المراقبة ، ومخالفة أحكام هذه القوانين تستوجب الحكم على مرتكبها بالحبس مدة لا تزيد على سنة واحدة ."}, {"number": "30", "chapter": "", "text": "يجوز للقاضى إذا حكم بعقوبة لجناية أو جنحة أن يحكم بمصادرة الأشياء المضبوطة التى تحصلت من الجريمة وكذلك الأسلحة والآلات المضبوطة التى استعملت أو التى من شأنها أن تستعمل فيها ، وهذا كله بدون إخلال بحقوق الغير الحسن النية . وإذا كانت الأشياء المذكورة من التى يعد صنعها أو استعمالها أو حيازتها أو بيعها أو عرضها للبيع جريمة فى ذاته وجب الحكم بالمصادرة فى جميع الأحوال ولو لم تكن تلك الأشياء ملكا للمتهم."}, {"number": "31", "chapter": "", "text": "يجوز فيما عدا الأحوال السابقة الحكم بعقوبات العزل من الوظيفة الأميرية ومراقبة البوليس والمصادرة ، وذلك فى الأحوال المنصوص عليها قانوناً . القسـم الثالـث تعـدد العقوبـات"}, {"number": "32", "chapter": "", "text": "إذا كون الفعل الواحد جرائم متعددة وجب اعتبار الجريمة التى عقوبتها أشد والحكم بعقوبتها دون غيرها. وإذا وقعت عدة جرائم لغرض واحد وكانت مرتبطة ببعضها بحيث لا تقبل التجزئة وجب اعتبارها كلها جريمة واحدة والحكم بالعقوبة المقررة لأشد تلك الجرائم ."}, {"number": "33", "chapter": "", "text": "تتعدد العقوبات المقيدة للحرية إلا ما استثنى بنص المادتين 35 و 36 ."}, {"number": "34", "chapter": "", "text": "إذا تنوعت العقوبات المتعددة وجب تنفيذها على الترتيب الآتي: أولا - السجن المؤبد . ثانيا - السجن المشدد . ثالثا - السجن . رابعا - الحبس مع الشغل . خامسا - الحبس البسيط . معدلة بالقانون 95 لسنة 2003 الجريدة الرسمية العدد 25 تابع فى 19 / 6 / 2003"}, {"number": "35", "chapter": "", "text": "تجب عقوبة السجن المؤبد أو المشدد بمقدار مدتها كل عقوبة مقيدة للحرية محكوم بها لجريمة وقعت قبل الحكم بالسجن المؤبد أو المشدد المذكورة ."}, {"number": "36", "chapter": "", "text": "إذا ارتكب شخص جرائم متعددة قبل الحكم عليه من أجل واحدة منها وجب أن لا تزيد مدة السجن المشدد على عشرين سنة ولو فى حالة تعدد العقوبات وأن لا تزيد مدة السجن أو مدة السجن والحبس على عشرين سنة وأن لا تزيد مدة الحبس وحده على ست سنين ."}, {"number": "37", "chapter": "", "text": "تتعدد العقوبات بالغرامة دائما ."}, {"number": "38", "chapter": "", "text": "تتعدد عقوبات مراقبة البوليس ، ولكن لا يجوز أن تزيد مدتها كلها على خمس سنين ."}, {"number": "39", "chapter": "الباب الرابـع", "text": "يعد فاعلا للجريمة : أولاً : من يرتكبها وحده أو مع غيره . ثانياً : من يدخل فى ارتكابها إذا كانت تتكون من جملة أعمال فيأتى عمدا عملا من الأعمال المكونة لها . ومع ذلك إذا وجدت أحوال خاصة بأحد الفاعلين تقتضى تغيير وصف الجريمة أو العقوبة بالنسبة له فلا يتعدى أثرها إلى غيره منهم وكذلك الحال إذا تغير الوصف باعتبار قصد مرتكب الجريمة أو كيفية علمه بها ."}, {"number": "40", "chapter": "الباب الرابـع", "text": "يعد شريكا فى الجريمة : أولاً : كل من حرض على ارتكاب الفعل المكون للجريمة إذا كان هذا الفعل قد وقع بناء على هذا التحريض . ثانياً : من اتفق مع غيره على ارتكاب الجريمة فوقعت بناء على هذا الاتفاق . ثالثاً : من أعطى الفاعل أو الفاعلين سلاحا أو آلات أو أى شئ آخر مما استعمل فى ارتكاب الجريمة مع علمه بها أو ساعدهم بأى طريقة أخرى فى الأعمال المجهزة أو المسهلة أو المتممة لارتكابها ."}, {"number": "41", "chapter": "الباب الرابـع", "text": "من اشترك فى جريمة فعليه عقوبتها إلا ما استثنى قانونا بنص خاص ومع هذا : أولا : لا تأثير على الشريك من الأحوال الخاصة بالفاعل التى تقتضى تغيير وصف الجريمة إذا كان الشريك غير عالم بتلك الأحوال . ثانيا : إذا تغير وصف الجريمة نظرا إلى قصد الفاعل منها أو كيفية علمه بها يعاقب الشريك بالعقوبة التى يستحقها لو كان قصد الفاعل من الجريمة أو علمه بها كقصد الشريك منها أو علمه بها."}, {"number": "42", "chapter": "الباب الرابـع", "text": "إذا كان فاعل الجريمة غير معاقب لسبب من أسباب الإباحة أو لعدم وجود القصد الجنائى أو لأحوال أخرى خاصة به وجبت مع ذلك معاقبة الشريك بالعقوبة المنصوص عليها قانونا."}, {"number": "43", "chapter": "الباب الرابـع", "text": "من اشترك فى جريمة فعليه عقوبتها ولو كانت غير التى تعمد ارتكابها متى كانت الجريمة التى وقعت بالفعل نتيجة محتملة للتحريض أو الاتفاق أو المساعدة التى حصلت ."}, {"number": "44", "chapter": "الباب الرابـع", "text": "إذا حكم على جملة متهمين بحكم واحد لجريمة واحدة فاعلين كانوا أو شركاء فالغرامات يحكم بها على كل منهم على انفراد ، خلافا للغرامات النسبية فإنهم يكونون متضامنين فى الإلزام بها ما لم ينص فى الحكم على خلاف ذلك ."}, {"number": "44 مكرر", "chapter": "الباب الرابـع", "text": "كل من أخفى أشياء مسروقة أو متحصلة من جناية أو جنحة مع علمه بذلك يعاقب بالحبس مع الشغل مدة لا تزيد على سنتين . وإذا كان الجانى يعلم أن الأشياء التى يخفيها متحصلة من جريمة عقوبتها أشد حكم عليه بالعقوبة المقررة لهذه الجريمة. البـاب الخامـس الشـروع"}, {"number": "45", "chapter": "الباب الرابـع", "text": "الشروع هو البدء فى تنفيذ فعل بقصد ارتكاب جناية أو جنحة إذا أوقف أو خاب أثره لأسباب لا دخل لإرادة الفاعل فيها . ولا يعتبر شروعا فى الجناية أو الجنحة مجرد العزم على إرتكابها ولا الأعمال التحضيرية لذلك ."}, {"number": "46", "chapter": "الباب الرابـع", "text": "يعاقب على الشروع فى الجناية بالعقوبات الآتية إلا إذا نص قانونا على خلاف ذلك : - بالسجن المؤبد إذا كانت عقوبة الجناية الإعدام . - بالسجن المشدد إذا كانت عقوبة الجناية السجن المؤبد . - بالسجن المشدد مدة لا تزيد على نصف الحد الأقصى المقرر قانونا أو السجن إذا كانت عقوبة الجناية بالسجن المشدد . - بالسجن مدة لا تزيد على نصف الحد الأقصى المقرر قانونا أو الحبس إذا كانت عقوبة الجناية السجن. ( [1] ) معدلة بالقانون 95 لسنة 2003."}, {"number": "47", "chapter": "الباب الرابـع", "text": "تعين قانونا الجنح التى يعاقب على الشروع فيها وكذلك عقوبة هذا الشروع . البـاب السـادس الاتفـاق الجنائى"}, {"number": "48", "chapter": "الباب الرابـع", "text": "يوجد اتفاق جنائى كلما اتحد شخصان فأكثر على ارتكاب جناية أو جنحة ما أو على الأعمال المجهزة أو المسهلة لارتكابها ، ويعتبر الاتفاق جنائيا سواء أكان الغرض منه جائزا أم لا إذا كان ارتكاب الجنايات أو الجنح من الوسائل التى لوحظت فى الوصول إليه . وكل من اشترك فى اتفاق جنائى سواء كان الغرض منه ارتكاب الجنايات أو اتخاذها وسيلة للوصول إلى الغرض المقصود منه يعاقب لمجرد اشتراكه بالسجن. فإذا كان الغرض من الاتفاق ارتكاب الجنح أو اتخاذها وسيلة للوصول إلى الغرض المقصود منه يعاقب المشترك فيه بالحبس . وكل من حرض على اتفاق جنائى من هذا القبيل أو تداخل فى إدارة حركته يعاقب بالسجن المشدد فى الحالة الأولى المنصوص عنها فى الفقرة السابقة وبالسجن فى الحالة الثانية. ومع ذلك إذا لم يكن الغرض من الاتفاق إلا ارتكاب جناية أو جنحة معينة عقوبتها أخف مما نصت عليه الفقرات السابقة فلا توقع عقوبة أشد مما نص عليه القانون لتلك الجناية أو الجنحة. ويعفى من العقوبات المقررة فى هذه المادة كل من بادر من الجناة بإخبار الحكومة بوجود اتفاق جنائى ، وبمن اشتركوا فيه قبل وقوع أية جناية أو جنحة ، وقبل بحث وتفتيش الحكومة عن أولئك الجناة . فإذا حصل الإخبار بعد البحث والتفتيش تعين أن يوصل الإخبار فعلا إلى ضبط الجناة الآخرين."}, {"number": "49", "chapter": "الباب السابع", "text": "يعتبر عائدا : أولاً : من حكم عليه بعقوبة جناية وثبت ارتكابه بعد ذلك جناية أو جنحة . ثانياً : من حكم عليه بالحبس مدة سنة أو أكثر وثبت أنه ارتكب جنحة قبل مضى خمس سنين من تاريخ انقضاء هذه العقوبة أو من تاريخ سقوطها بمضى المدة . ثالثاً : من حكم عليه لجناية أو جنحة بالحبس مدة أقل من سنة واحدة أو بالغرامة وثبت أنه ارتكب جنحة مماثلة للجريمة الأولى قبل مضى خمس سنين من تاريخ الحكم المذكور . وتعتبر السرقة والنصب وخيانة الأمانة جنحا متماثلة فى العود. وكذلك يعتبر العيب والإهانة والسب والقذف جرائم متماثلة ."}, {"number": "50", "chapter": "الباب السابع", "text": "يجوز للقاضى فى حالة العود المنصوص عنه فى المادة السابقة أن يحكم بأكثر من الحد الأقصى المقرر للجريمة قانونا بشرط عدم تجاوز ضعف هذا الحد . ومع هذا لا يجوز فى أى حال من الأحوال أن تزيد مدة السجن المشدد أو السجن على عشرين سنة. ( [1] ) معدلة بالقانون 95 لسنة 2003"}, {"number": "51", "chapter": "الباب السابع", "text": "إذا سبق الحكم على العائد بعقوبتين مقيدتين للحرية كلتاهما لمدة سنة على الأقل أو بثلاث عقوبات مقيدة للحرية إحداها على الأقل لمدة سنة أو أكثر وذلك لسرقة أو إخفاء أشياء مسروقة أو نصب أو خيانة أو تزوير أو شروع فى هذه الجرائم ثم ثبت ارتكابه لجنحة سرقة أو إخفاء أشياء مسروقة أو نصب أو خيانة أمانة أو تزوير أو شروع معاقب عليه فى هذه الجرائم بعد الحكم عليه بآخر تلك العقوبات ، فللقاضى أن يحكم عليه بالسجن المشدد من سنتين إلى خمس بدلا من تطبيق أحكام المادة السابقة."}, {"number": "52", "chapter": "الباب السابع", "text": "إذا توافر العود طبقا لأحكام المادة السابقة جاز للمحكمة بدلا من توقيع العقوبة المبينة فى تلك المادة أن تقرر اعتبار العائد مجرما اعتاد الإجرام متى تبين لها من ظروف الجريمة وبواعثها ، ومن أحوال المتهم وماضيه أن هناك احتمالا جديا لإقدامه على اقتراف جريمة جديدة وفى هذه الحالة تحكم المحكمة بإيداعه إحدى مؤسسات العمل التى يصدر بإنشائها وتنظيمها وكيفية معاملة من يودعون بها قرار من رئيس الجمهورية وذلك إلى أن يأمر وزير العدل بالإفراج عنه بناء على اقتراح إدارة المؤسسة وموافقة النيابة العامة . ولا يجوز أن تزيد مدة الإيداع فى المؤسسة على ست سنوات."}, {"number": "53", "chapter": "الباب السابع", "text": "إذا سبق الحكم على العائد بالسجن المؤبد عملا بالمادة 51 من هذا القانون أو باعتباره مجرما اعتاد الإجرام ، ثم ارتكب فى خلال سنتين من تاريخ الإفراج عنه جريمة من الجرائم المنصوص عليها فى تلك المادة حكمت المحكمة بإيداعه إحدى مؤسسات العمل المشار إليها فى المادة السابقة إلى أن يأمر وزير العدل بالإفراج عنه بناء على اقتراح إدارة المؤسسة وموافقة النيابة العامة . ولا يجوز أن تزيد مدة الإيداع فى هذه الحالة على عشر سنوات ."}, {"number": "54", "chapter": "الباب السابع", "text": "للقاضى أن يحكم بمقتضى نص المادة 51 على العائد الذى سبق الحكم عليه لارتكابه جريمة من المنصوص عليها فى المواد 355 و356 و367 و368 بعقوبتين مقيدتين للحرية كلتاهما لمدة سنة على الأقل أو بثلاث عقوبات مقيدة للحرية إحداها على الأقل لمدة سنة أو أكثر ، ثم ثبت ارتكابه جريمة من المنصوص عليها فى المادتين 355 و367 بعد آخر حكم عليه بالعقوبات السالفة ."}, {"number": "55", "chapter": "الباب الثامن", "text": "يجوز للمحكمة عند الحكم فى جناية أو جنحة بالغرامة أو بالحبس مدة لا تزيد على سنة أن تأمر فى نفس الحكم بإيقاف تنفيذ العقوبة إذا رأت من أخلاق المحكوم عليه أو ماضية أو سنه أو الظروف التى ارتكبت فيها الجريمة ما يبعث على الاعتقاد بأنه لن يعود إلى مخالفة القانون . ويجب أن تبين فى الحكم أسباب إيقاف التنفيذ . ويجوز أن يجعل الإيقاف شاملا لأية عقوبة تبعية ولجميع الآثار الجنائية المترتبة على الحكم ."}, {"number": "56", "chapter": "الباب الثامن", "text": "يصدر الأمر بإيقاف تنفيذ العقوبة لمدة ثلاث سنوات تبدأ من اليوم الذى يصبح فيه الحكم نهائيا . ويجوز إلغاؤه : 1 - إذا صدر ضد المحكوم عليه فى خلال هذه المدة حكم بالحبس أكثر من شهر على فعل ارتكبه قبل الأمر بالإيقاف أو بعده . 2 - إذا ظهر خلال هذه المدة أن المحكوم عليه صدر ضده قبل الإيقاف حكم كالمنصوص عليه فى الفقرة السابقة ولم تكن المحكمة قد علمت به ."}, {"number": "57", "chapter": "الباب الثامن", "text": "يصدر الحكم بالإلغاء من المحكمة التى أمرت بإيقاف التنفيذ بناء على طلب النيابة العمومية بعد تكليف المحكوم عليه بالحضور . وإذا كانت العقوبة التى بنى عليها الإلغاء قد حكم بها بعد إيقاف التنفيذ جاز أيضا أن يصدر الحكم بالإلغاء من المحكمة التى قضت بهذه العقوبة سواء من تلقاء نفسها أو بناء على طلب النيابة العمومية ."}, {"number": "58", "chapter": "الباب الثامن", "text": "يترتب على الإلغاء تنفيذ العقوبة المحكوم بها وجميع العقوبات التبعية الجنائية التى تكون قد أوقفت ."}, {"number": "59", "chapter": "الباب الثامن", "text": "إذا انقضت مدة الإيقاف ولم يكن صدر فى خلالها حكم بإلغائه فلا يمكن تنفيذ العقوبة المحكوم بها ، ويعتبر الحكم بها كأن لم يكن ."}, {"number": "60", "chapter": "الباب التاسع", "text": "لا تسرى أحكام قانون العقوبات على كل فعل ارتكب بنية سليمة عملا بحق مقرر بمقتضى الشريعة ."}, {"number": "61", "chapter": "الباب التاسع", "text": "لا عقاب على من ارتكب جريمة ألجأته إلى ارتكابها ضرورة وقاية نفسه أو غيره من خطر جسيم على النفس على وشك الوقوع به أو بغيره ولم يكن لإرادته دخل فى حلوله ولا فى قدرته منعه بطريقة أخرى ."}, {"number": "62", "chapter": "الباب التاسع", "text": "لا يسأل جنائياً الشخص الذى يعانى وقت ارتكاب الجريمة من اضطراب نفسى أو عقلى أفقده الإدراك أو الاختيار ، أو الذى يعانى من غيبوبة ناشئة عن عقاقير مخدرة أياً كان نوعها إذا أخذها قهراً عنه أو على غير علم منه بها. ويظل مسئولاً جنائياً الشخص الذى يعانى وقت ارتكاب الجريمة من اضطراب نفسى أو عقلى أدى إلى إنقاص إدراكه أو اختياره ، وتأخذ المحكمة فى اعتبارها هذا الظرف عند تحديد مدة العقوبة . ( [1] ) مستبدلة بالقانون رقم 71 لسنة 2009."}, {"number": "63", "chapter": "الباب التاسع", "text": "لا جريمة إذا وقع الفعل من موظف أميرى فى الأحوال الآتية : أولا : إذا ارتكب الفعل تنفيذا لأمر صادر إليه من رئيس وجبت عليه إطاعته أو اعتقد أنها واجبة عليه . ثانيا : إذا حسنت نيته وارتكب فعلا تنفيذا لما أمرت به القوانين أو ما اعتقد أن إجراءه من اختصاصه . وعلى كل حال يجب على الموظف أن يثبت أنه لم يرتكب الفعل إلا بعد التثبت والتحرى ، وأنه كان يعتقد مشروعيته وأن اعتقاده كان مبنيا على أسباب معقولة ."}, {"number": "74", "chapter": "الباب الحادى عشر", "text": "العفو عن العقوبة المحكوم بها يقتضى إسقاطها كلها أو بعضها ، أو إبدالها بعقوبة أخف منها مقررة قانونا . ولا تسقط العقوبات التبعية ولا الآثار الجنائية الأخرى المترتبة على الحكم بالإدانة ما لم ينص فى أمر العفو على خلاف ذلك."}, {"number": "75", "chapter": "الباب الحادى عشر", "text": "إذا صدر العفو بإبدال العقوبة بأخف منها تبدل عقوبة الإعدام بعقوبة السجن المؤبد . وإذا عفى عن محكوم عليه بالسجن المؤبد أو بدلت عقوبته وجب وضعه حتما تحت مراقبة البوليس مدة خمس سنين. والعفو عن العقوبة أو إبدالها إن كانت من العقوبات المقررة للجنايات لا يشمل الحرمان من الحقوق والمزايا المنصوص عنها فى الفقرات الأولى والثانية والخامسة والسادسة من المادة الخامسة والعشرين من هذا القانون. وهذا كله ما لم ينص فى العفو على خلاف ذلك . ( [1] ) معدلة بالقانون 95 لسنة 2003."}, {"number": "76", "chapter": "الباب الحادى عشر", "text": "العفو الشامل يمنع أو يوقف السير فى إجراءات الدعوى أو يمحو حكم الإدانة . ولا يمس حقوق الغير إلا إذا نص القانون الصادر بالعفو على خلاف ذلك ."}, {"number": "77", "chapter": "الباب الأول", "text": "يعاقب بالإعدام كل من ارتكب عمدا فعلا يؤدى إلى المساس باستقلال البلاد أو وحدتها أو سلامة أراضيها ."}, {"number": "77", "chapter": "الباب الأول", "text": "أ): يعاقب بالإعدام كل مصرى التحق بأى وجه بالقوات المسلحة لدولة فى حالة حرب مع مصر ."}, {"number": "77", "chapter": "الباب الأول", "text": "ب): يعاقب بالإعدام كل من سعى لدى دولة أجنبية أو تخابر معها أو مع أحد ممن يعملون لمصلحتها للقيام بأعمال عدائية ضد مصر ."}, {"number": "77", "chapter": "الباب الأول", "text": "ج): يعاقب بالإعدام كل من سعى لدى دولة أجنبية معادية أو تخابر معها أو مع أحد ممن يعملون لمصلحتها لمعاونتها فى عملياتها الحربية أو للإضرار بالعمليات الحربية للدولة المصرية ."}, {"number": "77", "chapter": "الباب الأول", "text": "د): يعاقب بالسجن إذا ارتكبت الجريمة فى زمن سلم وبالسجن المشدد إذا ارتكبت فى زمن الحرب : 1 - كل من سعى لدى دولة أجنبية أو أحد ممن يعملون لمصلحتها أو تخابر معها أو معه وكان من شأن ذلك الإضرار بمركز مصر الحربى أو السياسى أو الدبلوماسى أو الاقتصادى . 2 - كل من أتلف عمدا أو أخفى أو اختلس أو زور أوراقا أو وثائق وهو يعلم أنها تتعلق بأمن الدولة أو بأية مصلحة قومية أخرى . فإذا وقعت الجريمة بقصد الإضرار بمركز البلاد الحربى أو السياسى أو الدبلوماسى أو الاقتصادى أو بقصد الإضرار بمصلحة قومية لها كانت العقوبة السجن المشدد فى زمن السلم والسجن المؤبد فى زمن الحرب . ولا يجوز تطبيق المادة 17 من هذا القانون بأى حال على جريمة من هذه الجرائم إذا وقعت من موظف عام أو شخص ذى صفة نيابية أو مكلف بخدمة عامة ."}, {"number": "77", "chapter": "الباب الأول", "text": "هـ): يعاقب بالسجن المؤبد كل شخص كلف بالمفاوضة مع حكومة أجنبية فى شأن من شئون الدولة فتعمد إجراءها ضد مصلحتها ."}, {"number": "77", "chapter": "الباب الأول", "text": "و): يعاقب بالسجن كل من قام بغير إذن من الحكومة بجمع الجند أو قام بعمل عدائى آخر ضد دولة أجنبية من شأنه تعريض الدولة المصرية لخطر الحرب أو قطع العلاقات السياسية. فإذا ترتب على الفعل وقوع الحرب أو قطع العلاقات السياسية تكون العقوبة السجن المشدد ."}, {"number": "78", "chapter": "الباب الأول", "text": "كل من طلب لنفسه أو لغيره أو قبل أو أخذ ولو بالواسطة من دولة أجنبية أو ممن يعملون لمصلحتها أم من شخص طبيعى أو اعتبارى أو من منظمة محلية أو أجنبية أ, أية جهة أخرى لا تتبع دولة أجنبية ولا تعمل لصالحها ، أموالاً سائلة أو منقولة أو عتاداً أو آلات أو أسلحة أو ذخائر أو ما فى حكمها أو أشياء أخرى أو وعد بشئ من ذلك بقصد ارتكاب عمل ضار بمصلحة قومية أو المساس باستقلال البلاد أو وحدتها أو سلامة أراضيها أو القيام بأعمال عدائية ضد مصر أو الإخلال بالأمن والسلم العام يعاقب بالسجن المؤبد وبغرامة لا تقل عن خمسمائة ألف جنيه ولا تزيد على ما أعطى أو وعد به وتكون العقوبة الإعدام أو السجن المؤبد وغرامة لا تقل عن خمسمائة ألف جنيه إذا كان الجانى موظفاً عاماً أو مكلفاً بخدمة عامة أو ذا صفة نيابية عامة أو إذا ارتكب الجريمة فى زمن الحرب أو تنفيذاً لغرض إرهابى . ويعاقب بنفس العقوبة كل من أعطى أو عرض أو وعد بشىء مما ذكر بقصد ارتكاب عمل ضار من الأعمال المبينة بالفقرة السابقة. ويعاقب بنفس العقوبة أيضا كل من توسط فى ارتكاب جريمة من الجرائم السابقة . وإذا كان الطلب أو القبول أو العرض أو الوعد أو التوسط كتابة ورقياً أو الكترونياً فإن الجريمة تتم بمجرد تصدير الكتاب أو البيان. ( [1] ) مضافة بالقانون رقم 112 لسنة 1957 ثم استبدلت المادة بالقانون رقم 128 لسنة 2014."}, {"number": "78", "chapter": "الباب الأول", "text": "أ): يعاقب بالإعدام كل من تدخل لمصلحة العدو فى تدبير لزعزعة إخلاص القوات المسلحة أو إضعاف روحها أو روح الشعب المعنوية أو قوة المقاومة عنده."}, {"number": "78", "chapter": "الباب الأول", "text": "ب): يعاقب بالإعدام كل من حرض الجند فى زمن الحرب على الانخراط فى خدمة أية دولة أجنبية أو سهل لهم ذلك وكل من تدخل عمدا بأية كيفية فى جمع الجند أو رجال أو أموال أو مؤن أو عتاد أو تدبير شئ من ذلك لمصلحة دولة فى حالة حرب مع مصر ."}, {"number": "78", "chapter": "الباب الأول", "text": "ج): يعاقب بالإعدام كل من سهل دخول العدو فى البلاد أو سلمه مدنا أو حصونا أو منشآت أو مواقع أو موانى أو مخازن أو ترسانات أو سفنا أو طائرات أو وسائل مواصلات أو أسلحة أو ذخائر أو مهمات حربية أو مؤنا أو أغذية أو غير ذلك مما أعد للدفاع أو مما يستعمل فى ذلك أو خدمه بأن نقل إليه أخبارا أو كان له مرشدا ."}, {"number": "78", "chapter": "الباب الأول", "text": "د): يعاقب بالسجن المؤبد أو السجن المشدد كل من أعان عمدا العدو بأية وسيلة أخرى غير ما ذكر فى المواد السابقة. ويعاقب بالسجن كل من أدى لقوات العدو خدمة ما للحصول على منفعة أو فائدة أو وعد بها لنفسه أو لشخص عينه لذلك سواء كان ذلك بطريق مباشر أو غير مباشر وسواء أكانت المنفعة أو الفائدة مادية أم غير مادية ."}, {"number": "78", "chapter": "الباب الأول", "text": "هـ): يعاقب بالسجن المؤبد كل من أتلف أو عيب أو عطل عمدا أسلحة أو سفنا أو طائرات أو مهمات منشات أو وسائل مواصلات أو مرافق عامة أو ذخائر أو مؤنا أو أدوية أو غير ذلك مما أعد للدفاع عن البلاد أو مما يستعمل فى ذلك ويعاقب بالعقوبة ذاتها كل من أساء عمدا صنعها أو إصلاحها وكل من أتى عمدا عملا من شأنه أن يجعلها غير صالحة ولو مؤقتا للانتفاع بها فيما أعدت له أو أن ينشأ عنها حادث . وتكون العقوبة الإعدام إذا وقعت الجريمة فى زمن حرب ."}, {"number": "78", "chapter": "الباب الأول", "text": "و): إذا وقع أحد الأفعال المشار إليها فى الفقرة الأولى من المادة السابقة بسبب إهمال أو تقصير تكون العقوبة السجن . فإذا وقعت الجريمة فى زمن حرب تكون العقوبة السجن المشدد ، وتكون العقوبة السجن المؤبد إذا ترتب عليها تعطيل العمليات العسكرية ."}, {"number": "79", "chapter": "الباب الأول", "text": "كل من قام فى زمن حرب بنفسه أو بواسطة غيره مباشرة أو عن طريق بلد آخر بتصدير بضائع أو منتجات أو غير ذلك من المواد من مصر إلى بلد معاد أو باستيراد شئ من ذلك منه يعاقب بالسجن المشدد وبغرامة تعادل خمسة أمثال قيمة الأشياء المصدرة أو المستوردة على ألا تقل الغرامة عن ألف جنيه . ويحكم بمصادرة الأشياء محل الجريمة فإن لم تضبط يحكم على الجانى بغرامة إضافية تعادل قيمة هذه الأشياء ."}, {"number": "79", "chapter": "الباب الأول", "text": "أ): يعاقب بالسجن وبغرامة لا تقل عن ألف جنيه ولا تتجاوز عشرة آلاف جنيه كل من باشر فى زمن الحرب أعمالا تجارية أخرى بالذات أو بالواسطة مع رعايا بلد معاد أو مع وكلاء هذا البلد أو مندوبيه أو ممثليه أيا كانت إقامتهم أو مع هيئة أو فرد يقيم فيها . ويحكم بمصادرة الأشياء محل الجريمة فإن لم تضبط يحكم على الجانى بغرامة إضافية تعادل قيمة هذه الأشياء ."}, {"number": "80", "chapter": "الباب الأول", "text": "يعاقب بالإعدام كل من سلم لدولة أجنبية أو لأحد ممن يعملون لمصلحتها أو أفشى إليها أو إليه بأية صورة وعلى أى وجه وبأية وسيلة سرا من أسرار الدفاع عن البلاد أو توصل بأية طريقة إلى الحصول على سر من هذه الأسرار بقصد تسليمه أو إفشائه لدولة أجنبية أو لأحد ممن يعملون لمصلحتها وكذلك كل من أتلف لمصلحة دولة أجنبية شيئا يعتبر سرا من أسرار الدفاع أو جعله غير صالح لأن ينتفع به."}, {"number": "80 مكرر", "chapter": "الباب الأول", "text": "المادة ملغاة بالقانون 112 لسنة 1957"}, {"number": "80", "chapter": "الباب الأول", "text": "أ): يعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على خمس سنوات وبغرامة لا تقل عن 100 جنيه ولا تجاوز 500 جنيه : 1 - كل من حصل بأى وسيلة غير مشروعة على سر من أسرار الدفاع عن البلاد ولم يقصد تسليمه أو إفشاءه لدولة أجنبية أو لأحد ممن يعملون لمصلحتها . 2 - كل من أذاع بأية طريقة سرا من أسرار الدفاع عن البلاد. 3 - كل من نظم أو استعمل أية وسيلة من وسائل التراسل بقصد الحصول على سر من أسرار الدفاع عن البلاد أو تسليمه أو إذاعته . وتكون العقوبة السجن إذا وقعت الجريمة فى زمن الحرب ."}, {"number": "80", "chapter": "الباب الأول", "text": "ب): يعاقب بالسجن كل موظف عام أو شخص ذى صفة نيابية عامة أو مكلف بخدمة عامة أفشى سرا من أسرار الدفاع عن البلاد وتكون العقوبة السجن المشدد إذا وقعت الجريمة فى زمن الحرب ."}, {"number": "80", "chapter": "الباب الأول", "text": "ج): يعاقب بالسجن كل من أذاع عمدا فى زمن الحرب أخبارا أو بيانات أو إشاعات كاذبة أو مغرضة أو عمد إلى دعاية مثيرة وكان من شأن ذلك كله إلحاق الضرر بالاستعدادات الحربية للدفاع عن البلاد أو بالعمليات الحربية للقوات المسلحة أو إثارة الفزع بين الناس أو إضعاف الجلد فى الأمة. وتكون العقوبة السجن المشدد إذا ارتكبت الجريمة نتيجة التخابر مع دولة أجنبية . وتكون العقوبة السجن المؤبد إذا ارتكبت الجريمة نتيجة التخابر مع دولة معادية ."}, {"number": "80", "chapter": "الباب الأول", "text": "د): يعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تزيد على خمس سنوات وبغرامة لا تقل عن 100 جنيه ولا تجاوز 500 جنيه أو بإحدى هاتين العقوبتين كل مصرى أذاع عمدا فى الخارج أخبارا أو بيانات أو اشاعات كاذبة حول الأوضاع الداخلية للبلاد وكان من شأن ذلك أضعاف الثقة المالية بالدولة أو هيبتها واعتبارها أو باشر بأية طريقة كانت نشاطا من شأنه الإضرار بالمصالح القومية للبلاد. وتكون العقوبة السجن إذا وقعت الجريمة فى زمن حرب . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "80", "chapter": "الباب الأول", "text": "هـ): يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تتجاوز 500 جنيه أو بإحدى هاتين العقوبتين : 1 - كل من طار فوق الأراضى المصرية بغير ترخيص من السلطات المختصة. 2 - كل من قام بأخذ صور أو رسوم أو خرائط لمواضع أو أماكن على خلاف الحظر الصادر من السلطات المختصة . 3 - كل من دخل حصنا أو أحد منشآت الدفاع أو معسكرا أو مكانا خيمت أو استقرت فيه قوات مسلحة أو سفينة حربية أو تجارية أو طائرة أو سيارة حربية أو ترسانة أو أى محل حربى أو محلا أو مصنعا يباشر فيه عمل لمصلحة الدفاع عن البلاد ، ويكون الجمهور ممنوعا من دخوله . 4 - كل من أقام أو وجد فى المواضع والأماكن التى حظرت السلطات العسكرية الإقامة أو التواجد فيها . فإذا وقعت الجريمة فى زمن الحرب أو باستعمال وسيلة من وسائل الخداع أو الغش أو التخفى أو إخفاء الشخصية أو الجنسية أو المهنة أو الصفة كانت العقوبة الحبس مدة لا تقل عن ستة أشهر ولا تزيد على خمس سنوات أو غرامة لا تقل عن 100 جنيه ولا تتجاوز 500 جنيه أو بإحدى هاتين العقوبتين وفى حالة اجتماع هذين الظرفين تكون العقوبة السجن . ويعاقب بالعقوبات نفسها على الشروع فى ارتكاب هذه الجرائم."}, {"number": "80", "chapter": "الباب الأول", "text": "و): يعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تزيد عن خمس سنوات وبغرامة لا تقل عن 100 جنيه ولا تجاوز 500 جنيه أو بإحدى هاتين العقوبتين كل من سلم لدولة أجنبية أو لأحد ممن يعملون لمصلحتها بأية صورة وعلى أى وجه وبأية وسيلة أخبارا أو معلومات أو أشياء أو مكاتبات أو وثائق أو خرائط أو رسوما أو صورا أو غير ذلك مما يكون خاصا بالمصالح الحكومية أو الهيئات العامة أو المؤسسات ذات النفع العام وصدر أمر من الجهة المختصة بحظر نشره أو إذاعته ."}, {"number": "81", "chapter": "الباب الأول", "text": "يعاقب بالسجن كل من أخل عمدا فى زمن الحرب بتنفيذ كل أو بعض الالتزامات التى يفرضها عليه عقد توريد أو أشغال ارتبط به مع الحكومة لحاجات القوات المسلحة أو لوقاية المدنيين أو تموينهم أو ارتكب أى غش فى تنفيذ هذا العقد ويسرى هذا الحكم على المتعاقدين من الباطن والوكلاء والبائعين إذا كان الإخلال بتنفيذ الالتزام راجعا إلى فعلهم . وإذا وقعت الجريمة بقصد الإضرار بالدفاع عن البلاد أو بعمليات القوات المسلحة فتكون العقوبة الإعدام . ويحكم على الجانى فى جميع الأحوال بغرامة مساوية لقيمة ما أحدثه من أضرار بأموال الحكومة أو مصالحها على ألا تقل عما دخل ذمته نتيجة الإخلال أو الغش."}, {"number": "81", "chapter": "الباب الأول", "text": "أ) : إذا وقع الإخلال فى تنفيذ كل أو بعض الالتزامات المشار إليها فى المادة السابقة بسبب إهمال أو تقصير فتكون العقوبة الحبس وغرامة لا تجاوز ثلاثة آلاف جنيه أو إحدى هاتين العقوبتين ."}, {"number": "82", "chapter": "الباب الأول", "text": "يعاقب باعتباره شريكا فى الجرائم المنصوص عليها فى هذا الباب: 1 - كل من كان عالما بنيات الجانى وقدم إليه إعانة أو وسيلة للتعيش أو للسكنى أو مأوى أو مكانا للاجتماع أو غير ذلك من التسهيلات وكذلك كل من حمل رسائله أو سهل له البحث عن موضوع الجريمة أو إخفائه أو نقله أو إبلاغه. 2 - كل من أخفى أشياء استعملت أو أعدت للاستعمال فى ارتكاب الجريمة أو تحصلت منها وهو عالم بذلك . 3 - كل من أتلف أو اختلس أو أخفى أو غير عمدا مستندا من شأنه تسهيل كشف الجريمة وأدلتها أو عقاب مرتكبيها. ويجوز للمحكمة فى هذه الأحوال أن تعفى من العقوبة أقارب الجانى وأصهاره إلى الدرجة الرابعة إذا لم يكونوا معاقبين بنص آخر فى القانون ."}, {"number": "82", "chapter": "الباب الأول", "text": "أ) : كل من حرض على ارتكاب جريمة من الجرائم المنصوص عليها فى المواد 77 و 77 (أ) و 77 (ب) و77 (ج) و77 (د) و77 (هـ) و 78 و 78 (أ) و 78 (ب) و 78 (ج) و 78 (د) و78(هـ) و80 من هذا القانون ولم يترتب على تحريضه أثر يعاقب بالسجن المشدد أو بالسجن."}, {"number": "82", "chapter": "الباب الأول", "text": "ب) : يعاقب بالسجن المؤبد أو السجن المشدد كل من اشترك فى اتفاق جنائى سواء كان الغرض منه ارتكاب الجرائم المنصوص عليها فى المواد 77 و77 (أ) و77 (ب) و77 (ج) و77 (د) و 77 (هـ) و 78 و 78 (أ) و 78 (ب) و 78 (ج) و 78 (د) و 78 (هـ) و 80 أو اتخاذها وسيلة للوصول إلى الغرض المقصود منه . ويعاقب بالإعدام أو السجن المؤبد كل من حرض على الاتفاق أو كان له شأن فى إدارة حركته ، ومع ذلك إذا كان الغرض من الاتفاق ارتكاب جريمة واحدة معينة أو اتخاذها وسيلة إلى الغرض المقصود يحكم بالعقوبة المقررة لهذه الجريمة. ويعاقب بالحبس كل من دعا آخر إلى الانضمام إلى اتفاق من هذا القبيل ولم تقبل دعوته ."}, {"number": "82", "chapter": "الباب الأول", "text": "ج) : يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تجاوز 500 جنيه أو بإحدى هاتين العقوبتين كل من سهل بإهماله أو بتقصيره ارتكاب إحدى الجرائم المنصوص عليها فى المواد 77 ، 77 (أ) ، 77 (ب) ، 77 (ج) ، 77 (د) ، 77 (هـ) ، 78 ، 78 (أ) ، 78 (ب) ، 78 (ج) ، 78 (د) 78 (هـ) ، 80 . فإذا وقع ذلك فى زمن الحرب أو من موظف عام أو شخص ذى صفة نيابية عامة أو مكلف بخدمة عامة ضوعفت العقوبة."}, {"number": "82 مكرر", "chapter": "الباب الأول", "text": "يعاقب بالسجن المؤبد كل من حفر أو أعد أو جهز أو استعمل طريقاً أو ممراً أو نفقاً تحت الأرض في المناطق الحدودية للبلاد بقصد الاتصال بجهة أو دولة أجنبية أو أحد رعاياها أو المقيمين بها أو إدخال أو إخراج أشخاص أو بضائع أو سلع أو معدات أو آلات أو أي شيء آخر مقوماً بمال أو غير مقوم. ويعاقب بذات العقوبة كل من ثبت علمه بوجود أو استعمال طرق أو ممر او نفق تحت الارض فى المناطق الحدودية للبلاد بالوصف والشروط الواردة بالفقرة السابقة ، أو ثبت علمه بوجود مشروع لارتكاب أى من تلك الأفعال ولم يبلغ السلطات المختصة بذلك قبل اكتشافه . وتقضي المحكمة فضلاً عن العقوبة المنصوص عليها في الفقرة الأولى بمصادرة المبانى والمنشآت محل الجريمة والأدوات والأشياء المستخدمة في ارتكابها. ( [1] ) المادة مضافة بالقانون رقم 57 لسنة 2014 ثم استبدلت بالقانون رقم 21 لسنة 2015."}, {"number": "83", "chapter": "الباب الأول", "text": "فى الجنايات المنصوص عليها فى هذا الباب يجوز للمحكمة فى غير الأحوال المنصوص عليها فى المواد 78 و 79 و 79 (أ) من هذا القانون أن تحكم فضلا عن العقوبات المقررة لها بغرامة لا تجاوز عشرة آلاف جنيه."}, {"number": "83", "chapter": "الباب الأول", "text": "أ): تكون العقوبة الإعدام على أية جريمة مما نص عليه فى الباب الثانى من هذا الكتاب إذا وقعت بقصد المساس باستقلال البلاد أو وحدتها أو سلامة أراضيها أو إذا وقعت فى زمن الحرب بقصد إعانة العدو أو الإضرار بالعمليات الحربية للقوات المسلحة ، وكان من شأنها تحقيق الغرض المذكور . وتكون العقوبة الإعدام أيضا على أية جناية أو جنحة منصوص عليها فى هذا الباب متى كان قصد الجانى منها إعانة العدو أو الإضرار بالعمليات الحربية للقوات المسلحة ، وكان من شأنها تحقيق الغرض المذكور ."}, {"number": "84", "chapter": "الباب الأول", "text": "يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من علم بارتكاب جريمة من الجرائم المنصوص عليها فى هذا الباب ولم يسارع إلى إبلاغه إلى السلطات المختصة. وتضاعف العقوبة إذا وقعت الجريمة فى زمن الحرب . ويجوز للمحكمة أن تعفى من العقوبة زوج الجانى وأصوله وفروعه."}, {"number": "84", "chapter": "الباب الأول", "text": "أ): يعفى من العقوبات المقررة للجرائم المشار إليها فى هذا الباب كل من بادر من الجناة بإبلاغ السلطات الإدارية أو القضائية قبل البدء فى تنفيذ الجريمة وقبل البدء فى التحقيق. ويجوز للمحكمة الإعفاء من العقوبة إذا حصل البلاغ بعد تمام الجريمة وقبل البدء فى التحقيق ، ويجوز لها ذلك إذا مكن الجانى فى التحقيق السلطات من القبض على مرتكبى الجريمة الآخرين أو على مرتكبى جريمة أخرى مماثلة لها فى النوع والخطورة ."}, {"number": "85", "chapter": "الباب الأول", "text": "يعتبر سرا من أسرار الدفاع : 1 - المعلومات الحربية والسياسية والدبلوماسية والاقتصادية والصناعية التى بحكم طبيعتها لا يعلمها إلا الأشخاص الذين لهم صفة فى ذلك ، ويجب مراعاة لمصلحة الدفاع عن البلاد أن تبقى سرا على من عدا هؤلاء الأشخاص . 2 - الأشياء والمكاتبات والمحررات والوثائق والرسوم والخرائط والتصميمات والصور وغيرها من الأشياء التى يجب لمصلحة الدفاع عن البلاد ألا يعلم بها إلا من يناط بهم حفظها أو استعمالها والتى يجب أن تبقى سرا على من عداهم خشية أن تؤدى إلى إفشاء معلومات مما أشير إليه فى الفقرة السابقة . 3 - الأخبار والمعلومات المتعلقة بالقوات المسلحة وتشكيلاتها وتحركاتها وعتادها وتموينها وأفرادها ، وبصفة عامة كل ما له مساس بالشئون العسكرية والاستراتيجية ولم يكن قد صدر إذن كتابى من القيادة العامة للقوات المسلحة بنشره أو إذاعته . 4 - الأخبار والمعلومات المتعلقة بالتدابير والإجراءات التى تتخذ لكشف الجرائم المنصوص عليها فى هذا الباب أو تحقيقها أو محاكمة مرتكبيها ومع ذلك فيجوز للمحكمة التى تتولى المحاكمة أن تأذن بإذاعة ما تراه من مجرياتها ."}, {"number": "85", "chapter": "الباب الأول", "text": "أ): فى تطبيق أحكام هذا الباب : أ - يقصد بعبارة (البلاد) الأراضى التى للدولة المصرية عليها سيادة أو سلطان . ب - يعتبر موظفا عاما أو ذا صفة نيابية عامة أو مكلفا بخدمة عامة ولو لم يحصل على الأوراق أو الوثائق أو الأسرار أثناء تأدية وظيفته أو خدمته أو بسببها وكذلك من زالت عنه الصفة قبل ارتكابها سواء كان قد حصل على الأوراق أو الوثائق أو الأسرار أثناء قيام الصفة أو بعد انتهائها . جـ - تعتبر حالة قطع العلاقات السياسية فى حكم حالة الحرب وتعتبر من زمن الحرب الفترة التى يحدق فيها خطر الحرب متى انتهت بوقوعها فعلا . د - تعتبر فى حكم الدول الجماعات السياسية التى لم تعترف لها مصر بصفة الدولة وكانت تعامل معاملة المحاربين. ويجوز بقرار من رئيس الجمهورية أن تبسط أحكام هذا الباب كلها أو بعضها على الأفعال المنصوص عليها فيه حين ترتكب ضد دولة شريكة أو حليفة أو صديقة ."}, {"number": "86", "chapter": "القسم الأول", "text": "يقصد بالإرهاب فى تطبيق أحكام هذا القانون كل استخدام للقوة أو العنف أو التهديد أو الترويع ، يلجأ إليه الجانى تنفيذا لمشروع إجرامى فردى أو جماعى ، بهدف الإخلال بالنظام العام أو تعريض سلامة المجتمع وأمنه للخطر ، إذا كان من شأن ذلك إيذاء الأشخاص أو إلقاء الرعب بينهم أو تعريض حياتهم أو حرياتهم أو أمنهم للخطر ، أو إلحاق الضرر بالبيئة ، أو بالاتصالات أو المواصلات أو بالأموال أو بالمبانى أو بالأملاك العامة أو الخاصة أو احتلالها أو الاستيلاء عليها أو منع أو عرقلة ممارسة السلطات العامة أو دور العبادة أو معاهد العلم لأعمالها ، أو تعطيل تطبيق الدستور أو القوانين أو اللوائح."}, {"number": "86 مكرر", "chapter": "القسم الأول", "text": "يعاقب بالسجن كل من أنشأ أو أسس أو نظم أو أدار على خلاف أحكام القانون ، جمعية أو هيئة أو منظمة أو جماعة أو عصابة ، يكون الغرض منها الدعوة بأية وسيلة إلى تعطيل أحكام الدستور أو القوانين أو منع إحدى مؤسسات الدولة أو إحدى السلطات العامة من ممارسة أعمالها، أو الاعتداء على الحرية الشخصية للمواطن أو غيرها من الحريات والحقوق العامة التى كفلها الدستور والقانون ، أو الإضرار بالوحدة الوطنية أو السلام الاجتماعى، ويعاقب بالسجن المشدد كل من تولى زعامة، أو قيادة ما فيها، أو أمدها بمعونات مادية أو مالية مع علمه بالغرض الذى تدعو إليه . ويعاقب بالسجن مدة لا تزيد على خمس سنوات كل من انضم إلى إحدى الجمعيات أو الهيئات أو المنظمات أو الجماعات ، أو العصابات المنصوص عليها فى الفقرة السابقة ، أو شارك فيها بأية صورة ، مع علمه بأغراضها. ويعاقب بالعقوبة المنصوص عليها بالفقرة السابقة كل من روج بالقول أو الكتابة أو بأية طريقة أخرى للأغراض المذكورة فى الفقرة الأولى ، وكذلك كل من حاز بالذات أو بالواسطة أو أحرز محررات أو مطبوعات أو تسجيلات ، أيا كان نوعها ، تتضمن ترويجا لشىء مما تقدم ، إذا كانت معدة للتوزيع أو لإطلاع الغير عليها . وكل من حاز أو أحرز أية وسيلة من وسائل الطبع أو التسجيل أو العلانية ، استعملت أو أعدت للاستعمال ولو بصفة وقتية لطبع أو تسجيل أو إذاعة شىء مما ذكر . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006"}, {"number": "86 مكرر", "chapter": "القسم الأول", "text": "أ): تكون عقوبة الجريمة المنصوص عليها فى الفقرة الأولى من المادة السابقة الإعدام أو السجن المؤبد إذا كان الإرهاب من الوسائل التى تستخدم فى تحقيق أو تنفيذ الأغراض التى تدعو إليها الجمعية أو الهيئة أو المنظمة أو الجماعة أو العصابة المذكورة فى هذه الفقرة . ويعاقب بذات العقوبة كل من أمدها بأسلحة ، أو ذخائر ، أو مفرقعات ، أو مهمات ، أو آلات أو أموال أو معلومات مع علمه بما تدعو إليه وبوسائلها فى تحقيق أو تنفيذ ذلك . وتكون عقوبة الجريمة المنصوص عليها فى الفقرة الثانية من المادة السابقة ، السجن المشدد ، إذا كان الإرهاب من الوسائل التى تستخدم فى تحقيق ، أو تنفيذ الأغراض التى تدعو إليها الجمعية أو الهيئة أو المنظمة أو الجماعة أو العصابة المذكورة فى هذه الفقرة أو إذا كان الجانى من أفراد القوات المسلحة ، أو الشرطة . وتكون عقوبة الجريمة المنصوص عليها فى الفقرة الثالثة من المادة السابقة السجن مدة لا تزيد على عشرة سنوات إذا كانت الجمعية ، أو الهيئة أو المنظمة أو الجماعة أو العصابة المذكورة فى المادة السابقة تستخدم الإرهاب لتحقيق الأغراض التى تدعو إليها ، أو كان الترويج أو التحبيذ داخل دور العبادة أو الأماكن الخاصة بالقوات المسلحة ، أو الشرطة ، أو بين أفرادهما ."}, {"number": "86 مكرر", "chapter": "القسم الأول", "text": "ب) : يعاقب بالسجن المؤبد كل عضو بإحدى الجمعيات أو الهيئات أو المنظمات أو الجماعات أو العصابات المذكورة فى المادة 86 مكرر ، استعمل الإرهاب لإجبار شخص على الانضمام إلى أى منها ، أو منعه من الانفصال عنها . وتكون العقوبة الإعدام إذا ترتب على فعل الجانى موت المجنى عليه."}, {"number": "86 مكرر", "chapter": "القسم الأول", "text": "ج) : يعاقب بالسجن المؤبد كل من سعى لدى دولة أجنبية ، أو لدى جمعية أو هيئة أو منظمة أو جماعة أو عصابة يكون مقرها خارج البلاد ، أو بأحد ممن يعملون لمصلحة أى منها ، وكذلك كل من تخابر معها أو معه ، للقيام بأى عمل من أعمال الإرهاب داخل مصر ، أو ضد ممتلكاتها، أو مؤسساتها ، أو موظفيها ، أو ممثليها الدبلوماسيين ، أو مواطنيها أثناء عملهم ، أو وجودهم بالخارج، أو الاشتراك فى ارتكاب شىء مما ذكر . وتكون العقوبة الإعدام إذا وقعت الجريمة موضوع السعى أو التخابر أو شرع فى ارتكابها ."}, {"number": "86 مكرر", "chapter": "القسم الأول", "text": "د) : يعاقب بالسجن المشدد كل مصرى تعاون أو التحق بغير إذن كتابى من الجهة الحكومية المختصة بالقوات المسلحة لدولة أجنبية ، أو تعاون أو التحق بأى جمعية أو هيئة أو منظمة أو جماعة إرهابية أيا كانت تسميتها ، يكون مقرها خارج البلاد ، وتتخذ من الإرهاب أو التدريب العسكرى وسائل لتحقيق أغراضها ، حتى ولو كانت أعمالها غير موجهة إلى مصر. وتكون العقوبة السجن المؤبد إذا تلقى الجانى تدريبات عسكرية فيها ، أو شارك فى عملياتها غير الموجهة إلى مصر."}, {"number": "87", "chapter": "القسم الأول", "text": "يعاقب بالسجن المؤبد أو المشدد كل من حاول بالقوة قلب أو تغيير دستور الدولة أو نظامها الجمهورى أو شكل الحكومة . فإذا وقعت الجريمة من عصابة مسلحة يعاقب بالإعدام من ألّف العصابة وكذلك من تولى زعامتها أو تولى فيها قيادة ما. ( [1] ) معدلة بالقانون 95 لسنة 2003."}, {"number": "88", "chapter": "القسم الأول", "text": "يعاقب بالسجن المشدد كل من اختطف وسيلة ومن وسائل النقل الجوى أو البرى ، أو المائى ، معرضا سلامة من بها للخطر . وتكون العقوبة السجن المؤبد إذا استخدم الجانى الإرهاب ، أو نشأ عن الفعل المذكور جروح من المنصوص عليها فى المادتين 240 ، 241 من هذا القانون لأى شخص كان داخل الوسيلة أو خارجها ، أو إذا قاوم الجانى بالقوة أو العنف السلطات العامة أثناء تأدية وظيفتها فى استعادة الوسيلة من سيطرته ، وتكون العقوبة الإعدام ، إذا نشأ عن الفعل موت شخص داخل الوسيلة أو خارجها ."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "يعاقب بالسجن المشدد كل من قبض على أى شخص ، فى غير الأحوال المصرح بها فى القوانين واللوائح، أو احتجزه أو حبسه كرهينة ، وذلك بغية التأثير على السلطات العامة فى أدائها لأعمالها أو الحصول منها على منفعة أو ميزة من أى نوع . ويعاقب بذات العقوبة ، كل من مكن أو شرع فى تمكين مقبوض عليه فى الجرائم المنصوص عليها فى هذا القسم من الهرب . وتكون العقوبة السجن المؤبد إذا استخدم الجانى القوة أو العنف أو التهديد أو الإرهاب أو اتصف بصفة كاذبة ، أو تزيا بدون وجه حق ، بزى موظفى الحكومة ، أو أبرز أمرا مزورا مدعيا صدوره عنها ، أو إذا نشأ عن الفعل جروح من المنصوص عليها فى المادتين 240 ، 241 من هذا القانون ، أو إذا قاوم السلطات العامة أثناء تأدية وظيفتها فى إخلاء سبيل الرهينة أو المقبوض عليه . وتكون العقوبة الإعدام إذا نـجم عن الفعل موت شخص ."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "أ) : مع عدم الإخلال بأية عقوبة أشد يعاقب بالسجن المشدد كل من تعدى على أحد القائمين على تنفيذ أحكام هذا القسم ، وكان ذلك بسبب هذا التنفيذ ، أو قاومه بالقوة أو العنف أو بالتهديد باستعمالها معه أثناء تأدية وظيفته أو بسببها. وتكون العقوبة السجن المؤبد إذا نشأ عن التعدى أو المقاومة عاهة مستديمة أو كان الجانى يحمل سلاحا أو قام بخطف أو احتجاز أى من القائمين على تنفيذ أحكام هذا القسم هو أو زوجه أو أحد من أصوله أو فروعه . وتكون العقوبة الإعدام إذا نـجم عن التعدى أو المقاومة موت المجنى عليه."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "ب): تسرى أحكام المواد 82 ، 83 ، 95 ، 96 ، 97 ، 98 ، 98 (هـ) من هذا القانون ، على الجرائم المنصوص عليها فى هذا القسم . ويراعى عند الحكم بالمصادرة عدم الإخلال بحقوق الغير حسنى النية . وتخصص الأشياء المحكوم قضائيا بمصادرتها للجهة التى قامت بالضبط متى رأى الوزير المختص أنها لازمة لمباشرة نشاطها فى مكافحة الإرهاب."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "ج): لا يجوز تطبيق أحكام المادة 17 من هذا القانون عند الحكم بالإدانة فى جريمة من الجرائم المنصوص عليها فى هذا القسم عدا الأحوال التى يقرر فيها القانون عقوبة الإعدام أو السجن المؤبد ، فيجوز النزول بعقوبة الإعدام إلى السجن المؤبد والنزول بعقوبة السجن المؤبد إلى السجن المشدد التى لا تقل عن عشر سنوات ."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "د) : يجوز فى الأحوال المنصوص عليها فى هذا القسم ، فضلا عن الحكم بالعقوبة المقررة الحكم بتدبير أو أكثر من التدابير الآتية : 1 - حظر الإقامة فى مكان معين أو فى منطقة محددة . 2 - الإلزام بالإقامة فى مكان معين . 3 - حظر التردد على أماكن أو محال معينة . وفى جميع الأحوال لا يجوز أن تزيد مدة التدبير على خمس سنوات . ويعاقب كل من يخالف التدبير المحكوم به بالحبس مدة لا تقل عن ستة أشهر ."}, {"number": "88 مكرر", "chapter": "القسم الأول", "text": "هـ) : يعفى من العقوبات المقررة للجرائم المشار إليها فى هذا القسم كل من بادر من الجناة بإبلاغ السلطات الإدارية أو القضائية قبل البدء فى تنفيذ الجريمة وقبل البدء فى التحقيق ، ويجوز للمحكمة الإعفاء من العقوبة إذا حصل البلاغ بعد تمام الجريمة وقبل البدء فى التحقيق . ويجوز لها ذلك إذا مكن الجانى فى التحقيق السلطات من القبض على مرتكبى الجريمة الآخرين ، أو على مرتكبى جريمة أخرى مماثلة لها فى النوع والخطورة ."}, {"number": "89", "chapter": "القسم الأول", "text": "يعاقب بالإعدام كل من ألّف عصابة هاجمت طائفة من السكان أو قاومت بالسلاح رجال السلطة العامة فى تنفيذ القوانين، وكذلك كل من تولى زعامة عصابة من هذا القبيل ، أو تولى فيها قيادة ما . أما من انضم إلى تلك العصابة ولم يشترك فى تأليفها ولم يتقلد فيها قيادة ما فيعاقب بالسجن المؤبد أو المشدد."}, {"number": "89 مكرر", "chapter": "القسم الثانى", "text": "كل من خرب عمدا بأى طريقة إحدى وسائل الإنتاج أو أموالا ثابتة أو منقولة لإحدى الجهات المنصوص عليها فى المادة 119 بقصد الإضرار بالاقتصاد القومى يعاقب بالسجن المؤبد أو المشدد. وتكون العقوبة السجن المؤبد إذا ترتب على الجريمة إلحاق ضرر جسيم بمركز البلاد الاقتصادى أو بمصلحة قومية لها أو إذا ارتكبت الجريمة فى زمن الحرب . ويحكم على الجانى فى جميع الأحوال بدفع قيمة الأشياء التى خربها ، ويجوز أن يعفى من العقوبة كل من بادر من الشركاء فى الجريمة من غير المحرضين على ارتكابها بإبلاغ السلطات القضائية أو الإدارية بالجريمة بعد تمامها وقبل صدور الحكم النهائى فيها . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003 ."}, {"number": "90", "chapter": "القسم الثانى", "text": "يعاقب بالسجن مدة لا تزيد على خمس سنين كل من خرب عمدا مبانى أو أملاكا عامة أو مخصصة لمصالح حكومية أو للمرافق العامة أو للمؤسسات العامة أو الجمعيات المعتبرة قانونا ذات نفع عام. ويضاعف الحد الأقصى إذا ارتكبت الجريمة تنفيذا لغرض إرهابى. وتكون العقوبة السجن المؤبد أو المشدد إذا وقعت الجريمة فى زمن هياج أو فتنة أو بقصد إحداث الرعب بين الناس أو إشاعة الفوضى . وتكون العقوبة الإعدام إذا نـجم عن الجريمة موت شخص كان موجودا فى تلك الأماكن . ويحكم على الجانى فى جميع الأحوال بدفع قيمة الأشياء التى خربها . ( [1] ) معدلة بالقانون رقم 112 لسنة 1957 ثم عدلت بالقانون رقم 120 لسنة 1962 ثم عدلت بالقانون رقم 97 لسنة 1992."}, {"number": "90 مكرر", "chapter": "القسم الثانى", "text": "يعاقب بالسجن المؤبد أو المشدد كل من حاول بالقوة احتلال شىء من المبانى العامة أو المخصصة لمصالح حكومية أو لمرافق عامة أو لمؤسسات ذات نفع عام . فإذا وقعت الجريمة من عصابة مسلحة يعاقب بالإعدام من ألّف العصابة وكذلك من تولى زعامتها أو تولى فيها قيادة ما . ( [1] ) مضافة بالقانون 112 لسنة 1957 وعدلت بالقانون 95 لسنة 2003"}, {"number": "91", "chapter": "القسم الثانى", "text": "يعاقب بالإعدام كل من تولى لغرض إجرامى قيادة فرقة أو قسم من الجيش أو قسم من الأسطول أو سفينة حربية أو طائرة حربية أو نقطة عسكرية أو ميناء أو مدينة بغير تكليف من الحكومة أو بغير سبب مشروع ، ويعاقب كذلك بالإعدام كل من استمر رغم الأمر الصادر له من الحكومة فى قيادة عسكرية أيا كانت وكل رئيس قوة استبقى عساكره تحت السلاح أو مجتمعة بعد صدور أمر الحكومة بتسريحها ."}, {"number": "92", "chapter": "القسم الثانى", "text": "يعاقب بالسجن المشدد كل شخص له حق الأمر فى أفراد القوات المسلحة أو البوليس طلب إليهم أو كلفهم العمل على تعطيل أوامر الحكومة إذا كان ذلك لغرض إجرامى . فإذا ترتب على الجريمة تعطيل تنفيذ أوامر الحكومة كانت العقوبة الإعدام أو السجن المؤبد أما من دونه من رؤساء العساكر أو قوادهم الذين أطاعوا فيعاقبون بالسجن المشدد . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003 ."}, {"number": "93", "chapter": "القسم الثانى", "text": "يعاقب بالإعدام كل من قلد نفسه رئاسة عصابة حاملة للسلاح أو تولى فيها قيادة ما وكان ذلك بقصد اغتصاب أو نهب الأراضى أو الأموال المملوكة للحكومة أو لجماعة من الناس أو مقاومة القوة العسكرية المكلفة بمطاردة مرتكبى هذه الجنايات ويعاقب من عدا هؤلاء من أفراد العصابة بالسجن المشدد ."}, {"number": "94", "chapter": "القسم الثانى", "text": "يعاقب بالسجن المشدد كل من أدار حركة العصبة المذكورة فى المادة السابقة أو نظمها أو أعطاها أو جلب إليها أسلحة أو مهمات أو آلات تستعين بها على فعل الجناية وهو يعلم ذلك أو بعث إليها بمؤونات أو دخل فى مخابرات إجرامية بأية كيفية مع رؤساء تلك العصبة أو مديريها ، وكذلك كل من قدم لها مساكن أو محلات يأوون إليها أو يجتمعون فيها وهو يعلم غايتهم وصفتهم ."}, {"number": "95", "chapter": "القسم الثانى", "text": "كل من حرض على ارتكاب جريمة من الجرائم المنصوص عليها فى المواد 87 ، 89 ، 90 ، 90 مكرر ، 91 ، 92 ، 93 ، 94 من هذا القانون يعاقب بالسجن المشدد أو بالسجن إذا لم يترتب على هذا التحريض أثر . ( [1] ) مستبدلة بالقانون 112 لسنة 1957 وعدلت بالقانون 95 لسنة 2003"}, {"number": "96", "chapter": "القسم الثانى", "text": "يعاقب بالعقوبات المتقدم ذكرها كل من اشترك فى اتفاق جنائى سواء كان الغرض منه ارتكاب الجرائم المنصوص عليها فى المواد 87 ، 89 ، 90 ، 90 مكرر ، 91 ، 92 ، 93 ، 94 من هذا القانون أو اتخاذها وسيلة للوصول إلى الغرض المقصود منه ، ويعاقب بالسجن المؤبد من حرض على هذا الاتفاق أو كان له شأن فى إدارة حركته . ويعاقب بالسجن المشدد أو بالسجن كل من شجع على ارتكاب إحدى الجرائم المنصوص عليها فى المواد 87 ، 89 ، 90 ، 90 مكرر ، 91 ، 92 ، 93 ، 94 من هذا القانون بمعاونة مادية أو مالية دون أن تكون لديه نية الاشتراك مباشرة فى ارتكاب تلك الجرائم ."}, {"number": "97", "chapter": "القسم الثانى", "text": "كل من دعا آخر إلى الانضمام إلى اتفاق يكون الغرض منه ارتكاب جريمة من الجرائم المنصوص عليها فى المواد 87 ، 89 ، 90 ، 90 مكرر ، 91، 92 ، 93 ، 94 من هذا القانون يعاقب بالحبس إذا لم تقبل دعوته ."}, {"number": "98", "chapter": "القسم الثانى", "text": "يعاقب بالحبس كل من علم بوجود مشروع لارتكاب جريمة من الجرائم المنصوص عليها فى المواد 87 ، 89 ، 90 ، 90 مكرر ، 91 ، 92 ، 93 ، 94 من هذا القانون ولم يبلغه إلى السلطات المختصة . ولا يجرى حكم هذه المادة على زوج أى شخص له يد فى ذلك المشروع ولا على أصوله وفروعه."}, {"number": "98", "chapter": "القسم الثانى", "text": "أ): يعاقب بالسجن المشدد مدة لا تزيد على عشر سنين وبغرامة لا تقل عن مائة جنيه ، ولا تتجاوز ألف جنيه كل من أنشأ أو أسس أو نظم أو أدار جمعيات أو هيئات أو منظمات ترمى إلى سيطرة طبقة اجتماعية على غيرها من الطبقات أو إلى القضاء على طبقة اجتماعية أو إلى قلب نظم الدولة الأساسية الاجتماعية أو الاقتصادية أو إلى هدم أى نظام من النظم الأساسية للهيئة الاجتماعية ، أو إلى تحبيذ شىء مما تقدم أو الترويج له متى كان استعمال القوة أو الإرهاب أو أية وسيلة أخرى غير مشروعة ملحوظا فى ذلك . ويعاقب بنفس العقوبات كل أجنبى يقيم فى مصر وكل مصرى ولو كان مقيما فى الخارج إذا أنشأ أو أسس أو نظم أو أدار فرعا فى الخارج لإحدى الجمعيات أو الهيئات أو المنظمات المذكورة ، وكذلك كل من أنشأ أو أسس أو نظم أو أدار فى مصر فروعا لمثل إحدى هذه الجمعيات أو الهيئات أو المنظمات ولو كان مقرها فى الخارج . ويعاقب بالسجن وبغرامة لا تقل عن خمسين جنيها ولا تزيد على مائتى جنيه كل من انضم إلى إحدى الجمعيات أو الهيئات أو المنظمات أو الفروع المذكورة فى الفقرتين السابقتين أو اشترك فيها بأية صورة . ويعاقب بالسجن مدة لا تزيد على خمس سنين كل من اتصل بالذات أو بالواسطة بالجمعيات أو الهيئات أو المنظمات أو الفروع المتقدم ذكرها لأغراض غير مشروعة أو شجع غيره على ذلك أو سهله له ."}, {"number": "98", "chapter": "القسم الثانى", "text": "أ) مكرر : يعاقب بالسجن وبغرامة لا تقل عن مائة جنيه ولا تتجاوز ألف جنيه كل من أنشأ أو نظم أو أدار جمعية أو هيئة أو منظمة أو جماعة يكون الغرض منها الدعوة بأية وسيلة إلى مناهضة المبادئ الأساسية التى يقوم عليها نظام الحكم الاشتراكى فى الدولة أو الحض على كراهيتها أو الازدراء بها أو الدعوة ضد تحالف قوى الشعب العاملة ، أو التحريض على مقاومة السلطات العامة أو ترويج أو تحبيذ شىء من ذلك . وتكون العقوبة السجن المشدد وغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه ، إذا كان استعمال القوة أو العنف أو الإرهاب ملحوظا فى ذلك . ويعاقب بالسجن مدة لا تزيد على خمس سنوات وغرامة لا تقل عن خمسين جنيها ولا تجاوز خمسمائة جنيه كل من انضم إلى إحدى هذه الجمعيات أو الهيئات أو المنظمات أو الجماعات مع علمه بالغرض الذى تدعو إليه أو اشترك فيها بأية صورة . وكذلك كل من حاز بالذات أو بالوساطة أو أحرز محررات أو مطبوعات تتضمن ترويجا وتحبيذا لشىء مما تقدم إذا كانت معدة للتوزيع أو لإطلاع الغير عليها وكل من حاز أو أحرز أية وسيلة من وسائل الطبع أو التسجيل أو العلانية مخصصة ولو بصفة وقتية لطبع أو تسجيل أو إذاعة شىء مما ذكر . ( [1] ) مضافة بالقانون 34 لسنة 1970 وعدلت بالقانون 95 لسنة 2003. ( [1] ) الفقرة الرابعة ملغاة بالقانون رقم 147 لسنة 2006."}, {"number": "98", "chapter": "القسم الثانى", "text": "ب) : يعاقب بالحبس مدة لا تتجاوز خمس سنوات وبغرامة لا تقل عن خمسين جنيها ولا تزيد على خمسمائة جنيه كل من روج فى الجمهورية المصرية بأية طريقة من الطرق لتغيير مبادئ الدستور الأساسية أو النظم الأساسية للهيئة الاجتماعية أو لتسويد طبقة اجتماعية على غيرها من الطبقات أو القضاء على طبقة اجتماعية أو لقلب نظم الدولة الأساسية الاجتماعية أو الاقتصادية أو لهدم أى نظام من النظم الأساسية للهيئة الاجتماعية متى كان استعمال القوة أو الإرهاب أو أية وسيلة أخرى غير مشروعة ملحوظا فى ذلك. ويعاقب بنفس العقوبات كل من حبذ بأية طريقة من الطرق الأفعال المذكورة ."}, {"number": "98", "chapter": "القسم الثانى", "text": "ب) مكرر : يعاقب بالحبس مدة لا تزيد عن خمس سنين وبغرامة لا تقل عن خمسين جنيها ولا تتجاوز خمسمائة جنيه كل من حاز بالذات أو الواسطة أو أحرز محررات أو مطبوعات تتضمن ترويجا لشىء مما نص عليه فى المادتين 98 (ب) و174 إذا كانت معدة للتوزيع أو لإطلاع الغير عليها ، وكل من حاز أية وسيلة من وسائل الطبع أو التسجيل أو العلانية مخصصة ولو بصفة وقتية لطبع أو تسجيل أو إذاعة نداءات أو أناشيد أو دعاية خاصة بمذهب أو جمعية أو هيئة أو منظمة ترمى إلى غرض من الأغراض المنصوص عليها فى المادتين المذكورتين . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "98", "chapter": "القسم الثانى", "text": "ج) : كل من أنشأ أو أسس أو نظم أو أدار فى الجمهورية المصرية من غير ترخيص من الحكومة جمعيات أو هيئات أو أنظمة من أى نوع كان ذات صفة دولية أو فروعا لها يعاقب بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تجاوز خمسمائة جنيه . ويضاعف الحد الأقصى للعقوبة إذا كان الترخيص بناء على بيانات كاذبة . ويعاقب بالحبس مدة لا تزيد على ثلاثة أشهر أو بغرامة لا تزيد على ثلاثـمائة جنيه كل من انضم إلى الجمعيات أو الهيئات أو الأنظمة المذكورة . وكذلك كل مصرى مقيم فى الجمهورية المصرية انضم أو اشترك بأية صورة من غير ترخيص من الحكومة إلى تشكيلات مما ذكر يكون مقرها فى الخارج ."}, {"number": "98", "chapter": "القسم الثانى", "text": "د) : يعاقب بالسجن مدة لا تزيد على خمس سنوات وبغرامة لا تقل عن مائة جنيه ولا تجاوز ألف جنيه كل من تسلم أو قبل مباشرة أو بالوساطة بأية طريقة أموالا أو منافع من أى نوع كانت من شخص أو هيئة فى خارج الجمهورية أو فى داخلها متى كان ذلك فى سبيل ارتكاب جريمة من الجرائم المنصوص عليها فى المواد 98 (أ) ، 98 (أ) مكرر ، 98 (ب) ، 98 (ج) ، 174 من هذا القانون . ويعاقب بالعقوبات ذاتها كل من شجع بطريق المساعدة المالية أو المادية على ارتكاب جريمة من الجرائم المنصوص عليها فى المواد المشار إليها فى الفقرة السابقة دون أن يكون قاصدا الاشتراك مباشرة فى ارتكابها ."}, {"number": "98", "chapter": "القسم الثانى", "text": "هـ) : تقضى المحكمة فى الأحوال المبينة فى المواد 98 (أ) و98 (أ) مكررا و98 (ج) بحل الجمعيات أو الهيئات أو المنظمات أو الجماعات أو الفروع المذكورة وإغلاق أمكنتها ومصادرة الأموال والأمتعة والأدوات والأوراق وغيرها مما يكون قد استعمل فى ارتكاب الجريمة أو أعد لاستعماله فيها أو يكون موجودا فى الأمكنة المخصصة لاجتماع أعضاء هذه الجمعيات أو الهيئات أو المنظمات أو الجماعات أو الفروع ، كما تقضى بمصادرة كل مال يكون متحصلا من الجريمة أو يكون فى الظاهر داخلا ضمن أملاك المحكوم عليه إذا كانت هناك قرائن تؤدى إلى أن هذا المال هو فى الواقع مورد مخصص للصرف منه على الجمعيات أو الهيئات أو المنظمات أو الجماعات أو الفروع المذكورة ."}, {"number": "98", "chapter": "القسم الثانى", "text": "و) : يعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تجاوز خمس سنوات أو بغرامة لا تقل عن خمسمائة جنيه ، ولا تجاوز ألف جنيه كل من استغل الدِين فى الترويج بالقول أو بالكتابة أو بأية وسيلة أخرى لأفكار متطرفة بقصد إثارة الفتنة أو تحقير أو ازدراء أحد الأديان السماوية أو الطوائف المنتمية إليها أو الإضرار بالوحدة الوطنية . ( [1] ) المادة معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "99", "chapter": "القسم الثانى", "text": "يعاقب بالسجن المؤبد أو المشدد كل من لجأ إلى العنف أو التهديد أو أية وسيلة أخرى غير مشروعة لحمل رئيس الجمهورية على أداء عمل من خصائصه قانونا أو على الامتناع عنه وتكون العقوبة السجن المشدد أو السجن إذا وقع الفعل على وزير أو على نائب وزير أو أحد أعضاء مجلس الشعب. ( [1] ) معدلة بالقانون رقم 95 لسنة 2003 ."}, {"number": "100", "chapter": "القسم الثانى", "text": "لا يحكم بعقوبة ما بسبب ارتكاب الفتنة على كل من كان فى زمرة العصابات المنصوص عليها فى أحكام هذا الباب ولم يكن له فيها رئاسة ولا وظيفة وانفصل عنها عند أول تنبيه عليه من السلطات المدنية أو العسكرية أو بعد التنبيه إذا لم يكن قبض عليه إلا بعيدا عن أماكن الاجتماع الثورى بلا مقاومة ولم يكن حاملاً سلاحاً . ففى هاتين الحالتين لا يعاقب إلا على ما يكون قد ارتكبه شخصيا من الجنايات الخاصة ."}, {"number": "101", "chapter": "القسم الثانى", "text": "يعفى من العقوبات المقررة للبغاة كل من بادر منهم بإخبار الحكومة عمن أجرى ذلك الاغتصاب أو أغرى عليه وشاركه فيه قبل حصول الجناية المقصود فعلها وقبل بحث وتفتيش الحكومة عن هؤلاء البغاة . وكذلك يعفى من تلك العقوبات كل من دل الحكومة على الوسائل الموصلة للقبض عليهم بعد بدئها فى البحث والتفتيش."}, {"number": "102", "chapter": "القسم الثانى", "text": "كل من جهر بالصياح أو الغناء لإثارة الفتن يعاقب بالحبس مدة لا تزيد على سنة أو بغرامة لا تزيد على مائتى جنيه."}, {"number": "102 مكرر", "chapter": "القسم الثانى", "text": "يعاقب بالحبس وبغرامة لا تقل عن خمسين جنيها ولا تجاوز مائتى جنيه كل من أذاع عمدا أخبارا أو بيانات أو إشاعات كاذبة إذا كان من شأن ذلك تكدير الأمن العام أو إلقاء الرعب بين الناس أو إلحاق الضرر بالمصلحة العامة . وتكون العقوبة السجن وغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه إذا وقعت الجريمة فى زمن الحرب. ويعاقب بالعقوبات المنصوص عليها فى الفقرة الأولى كل من حاز بالذات أو بالواسطة أو أحرز محررات أو مطبوعات تتضمن شيئا مما نص عليه فى الفقرة المذكورة إذا كانت معدة للتوزيع أو لإطلاع الغير عليها ، وكل من حاز أو أحرز أية وسيلة من وسائل الطبع أو التسجيل أو العلانية مخصصة ولو بصفة وقتية لطبع أو تسجيل أو إذاعة شىء مما ذكر . ( [1] ) المادة معدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "أ) : يعاقب بالسجن المؤبد كل من أحرز أو حاز أو استورد أو صنع مفرقعات أو مواد متفجرة أو ما في حكمها قبل الحصول على ترخيص بذلك، وتكون العقوبة الإعدام إذا وقعت الجريمة تنفيذا لغرض إرهابي. ويعاقب بالسجن المؤبد أو المشدد كل من أحرز أو حاز أو استورد أو صنع بغير مسوغ أجهزة أو آلات أو أدوات تستخدم في صنع المفرقعات أو المواد المتفجرة أو ما في حكمها أو في تفجيرها. ويعتبر في حكم المفرقعات أو المواد المتفجرة كل مادة تدخل في تركيبها، ويصدر بتحديدها قرار من وزير الداخلية. ويعاقب بالسجن كل من علم بارتكاب أي من الجرائم المشار إليها في الفقرتين الأولى والثانية من هذه المادة، ولم يبلغ السلطات المختصة قبل اكتشافها. وتقضى المحكمة فضلا عن العقوبة المنصوص عليها في الفقرتين الأولى والثانية من هذه المادة بمصادرة محل الجريمة، والأراضي والمباني والمنشآت المستخدمة في الجريمة، ووسائل النقل المستخدمة في نقلها، وكذلك الأدوات والأشياء المستخدمة في ارتكابها، وذلك كله دون إخلال بحقوق الغير حسن النية. ( [1] ) المادة مستبدلة بالقانون رقم 21 لسنة 2018."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "ب): يعاقب بالإعدام كل من استعمل مفرقعات بنية ارتكاب الجريمة المنصوص عليها فى المادة 87 أو بغرض ارتكاب قتل سياسى أو تخريب المبانى والمنشآت المعدة للمصالح العامة أو للمؤسسات ذات النفع العام أو للاجتماعات العامة أو غيرها من المبانى أو الأماكن المعدة لارتياد الجمهور."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "ج): يعاقب بالسجن المؤبد كل من استعمل أو شرع فى استعمال المفرقعات استعمالا من شأنه تعريض حياة الناس للخطر . فإذا أحدث الانفجار موت شخص أو أكثر كان العقاب الإعدام."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "د): يعاقب بالسجن المشدد من استعمل أو شرع فى استعمال المفرقعات استعمالا من شأنه تعريض أموال الغير للخطر . فإذا أحدث الانفجار ضررا بتلك الأموال كان العقاب السجن المؤبد ."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "هـ): استثناء من أحكام المادة 17 لا يجوز فى تطبيق المواد السابقة النزول عن العقوبة التالية مباشرة للعقوبة المقررة للجريمة ."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "و): يعاقب بالحبس على مخالفة شروط الترخيص المشار إليها فى المادة 102 (أ)."}, {"number": "102", "chapter": "الباب الثانى مكرر", "text": "ز): ملغاة ( [1] ) المادة ملغاة بالقانون رقم 21 لسنة 2018. البـاب الثالـث الرشـوة"}, {"number": "103", "chapter": "الباب الثانى مكرر", "text": "كل موظف عمومى طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية لأداء عمل من أعمال وظيفته يعد مرتشيا ويعاقب بالسجن المؤبد وبغرامة لا تقل عن ألف جنيه ولا تزيد على ما أعطى أو وعد به ."}, {"number": "103 مكرر", "chapter": "الباب الثانى مكرر", "text": "يعتبر مرتشيا ويعاقب بنفس العقوبة المنصوص عليها فى المادة السابقة كل موظف عمومى طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية لأداء عمل يعتقد خطأ أو يزعم أنه من أعمال وظيفته أو للامتناع عنه ."}, {"number": "104", "chapter": "الباب الثانى مكرر", "text": "كل موظف عمومى طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية للامتناع عن عمل من أعمال وظيفته أو للإخلال بواجباتها أو لمكافأته على ما وقع منه من ذلك يعاقب بالسجن المؤبد وضعف الغرامة المذكورة فى المادة 103 من هذا القانون ."}, {"number": "104 مكرر", "chapter": "الباب الثانى مكرر", "text": "كل موظف عمومى طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية لأداء عمل من أعمال وظيفته أو يعتقد خطأ أو يزعم أنه من أعمال وظيفته أو للامتناع عنه أو للإخلال بواجبات الوظيفة يعاقب بعقوبة الرشوة المنصوص عليها فى المواد الثلاث السابقة حسب الأحوال حتى ولو كان يقصد عدم القيام بذلك العمل أو عدم الامتناع أو عدم الإخلال بواجبات الوظيفة ."}, {"number": "105", "chapter": "الباب الثانى مكرر", "text": "كل موظف عمومى قبل من شخص أدى له عملا من أعمال وظيفته أو امتنع عن أداء عمل من أعمالها أو أخل بواجباتها هدية أو عطية بعد تمام ذلك العمل أو الامتناع عنه أو الإخلال بواجبات وظيفته بقصد المكافأة على ذلك وبغير اتفاق سابق يعاقب بالسجن وبغرامة لا تقل عن مائة جنيه ولا تزيد عن خمسمائة جنيه ."}, {"number": "105 مكرر", "chapter": "الباب الثانى مكرر", "text": "كل موظف عمومى قام بعمل من أعمال وظيفته أو امتنع عن عمل من أعمال وظيفته أو أخل بواجباتها نتيجة لرجاء أو توصية أو وساطة يعاقب بالسجن وبغرامة لا تقل عن مائتى جنيه ولا تزيد على خمسمائة جنيه."}, {"number": "106", "chapter": "الباب الثانى مكرر", "text": "كل مستخدم طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية بغير علم مخدومه ورضائه لأداء عمل من الأعمال المكلف بها أو للامتناع عنه يعتبر مرتشيا ويعاقب بالحبس مدة لا تزيد على سنتين وبغرامة لا تقل عن مائتى جنيه ولا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين."}, {"number": "106 مكرر", "chapter": "الباب الثانى مكرر", "text": "كل من طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية لاستعمال نفوذ حقيقى أو مزعوم للحصول أو لمحاولة الحصول من أية سلطة عامة على أعمال أو أوامر أو أحكام أو قرارات أو نياشين أو التزام أو ترخيص أو اتفاق توريد أو مقاولة أو على وظيفة أو خدمة أو أية مزية من أى نوع يعد فى حكم المرتشى ويعاقب بالعقوبة المنصوص عليها فى المادة 104 من هذا القانون إن كان موظفا عموميا وبالحبس وبغرامة لا تقل عن مائتى جنيه ولا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين فقط فى الأحوال الأخرى . ويعتبر فى حكم السلطة العامة كل جهة خاضعة لإشرافها ."}, {"number": "106 مكرر", "chapter": "الباب الثانى مكرر", "text": "أ) : كل عضو بمجلس إدارة إحدى الشركات المساهمة أو إحدى الجمعيات التعاونية أو النقابات المنشأة طبقا للقواعد المقررة قانونا أو بإحدى المؤسسات أو الجمعيات المعتبرة قانونا ذات نفع عام ، وكذلك كل مدير أو مستخدم فى إحداها طلب لنفسه أو لغيره أو قبل أو أخذ وعدا أو عطية لأداء عمل أو للامتناع عن عمل من أعمال وظيفته أو يعتقد خطأ أو يزعم أنه من أعمال وظيفته أو للإخلال بواجباتها يعد مرتشيا ويعاقب بالسجن مدة لا تزيد على سبع سنين وغرامة لا تقل عن خمسمائة جنيه ولا تزيد على ما أعطى أو وعد به ولو كان الجانى يقصد عدم القيام بالعمل أو عدم الامتناع عنه أو عدم الإخلال بواجبات وظيفته. ويعاقب الجانى بالعقوبات ذاتها إذا كان الطلب أو القبول أو الأخذ لاحقا لأداء العمل أو للامتناع عنه أو للإخلال بواجبات الوظيفة وكان يقصد المكافأة على ذلك وبغير اتفاق سابق ."}, {"number": "106 مكرر", "chapter": "الباب الثانى مكرر", "text": "ب) : كل موظف عمومى أجنبى أو موظف مؤسسة دولية عمومية طلب لنفسه أو لغيره، أو قبل، أو أخذ وعدأً أو عطية، لأداء عمل من أعماله الدولية أو الامتناع عنها أو للإخلال بواجباتها يعد مرتشياً ويٌعاقب بالسجن المؤبد وبغرامة لا تقل عن ألف جنيه ولا تزيد على ضعف ما أعطى أو وُعد به. كما يٌعاقب بالسجن وبغرامة لا تقل عن خمسمائة جنيه، ولا تزيد على ألف جنيه من عرض رشوة على موظف عمومى أجنبى أو موظف مؤسسة دولية عمومية ولم تقبل منه. ( [1] ) المادة مضافة بالقانون رقم 5 لسنة 2018."}, {"number": "107", "chapter": "الباب الثانى مكرر", "text": "يكون من قبيل الوعد أو العطية كل فائدة يحصل عليها المرتشى أو الشخص الذى عينه لذلك أو علم به ووافق عليه أيا كان اسمها أو نوعها وسواء أكانت هذه الفائدة مادية أم غير مادية ."}, {"number": "107 مكرر", "chapter": "الباب الثانى مكرر", "text": "يعاقب الراشى والوسيط بالعقوبة المقررة للمرتشى ومع ذلك يعفى الراشى أو الوسيط من العقوبة إذا أخبر السلطات بالجريمة أو اعترف بها ."}, {"number": "108", "chapter": "الباب الثانى مكرر", "text": "إذا كان الغرض من الرشوة ارتكاب فعل يعاقب عليه القانون بعقوبة أشد من العقوبة المقررة للرشوة فيعاقب الراشى والمرتشى والوسيط بالعقوبة المقررة لذلك الفعل مع الغرامة المقررة للرشوة ويعفى الراشى أو الوسيط من العقوبة إذا أخبر السلطات بالجريمة طبقا لنص الفقرة الأخيرة من المادة 48 من هذا القانون ."}, {"number": "108 مكرر", "chapter": "الباب الثانى مكرر", "text": "كل شخص عين لأخذ العطية أو الفائدة أو علم بها ووافق عليه المرتشى أو أخذ أو قبل شيئا من ذلك مع علمه بسببه يعاقب بالحبس مدة لا تقل عن سنة وبغرامة مساوية لقيمة ما أعطى أو وعد به وذلك إذا لم يكن قد توسط فى الرشوة."}, {"number": "109", "chapter": "الباب الثانى مكرر", "text": "ملغاه . ( [1] ) ملغاة بالقانون رقم 120 لسنة 1962."}, {"number": "109 مكرر", "chapter": "الباب الثانى مكرر", "text": "من عرض رشوة ولم تقبل منه يعاقب بالسجن وبغرامة لا تقل عن خمسمائة جنيه ولا تزيد على ألف جنيه وذلك إذا كان العرض حاصلا لموظف عام ، فإذا كان العرض حاصلا لغير موظف عام تكون العقوبة الحبس لمدة لا تزيد على سنتين أو غرامة لا تجاوز مائتى جنيه ."}, {"number": "109 مكرر", "chapter": "الباب الثانى مكرر", "text": "ثانياً) : مع عدم الإخلال بأية عقوبة أشد يقضى بها قانون العقوبات أو أى قانون آخر يعاقب بالحبس وبغرامة لا تقل عن مائتى جنيه ولا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من عرض أو قبل الوساطة فى رشوة ولم يتعد عمله العرض أو القبول . فإذا وقع ذلك من موظف عمومى فيعاقب الجانى بالعقوبة المنصوص عليها فى المادة 104 . وإذا كان ذلك بقصد الوساطة لدى موظف عمومى يعاقب بالعقوبة المنصوص عليها فى المادة 105 مكررا ."}, {"number": "110", "chapter": "الباب الثانى مكرر", "text": "يحكم فى جميع الأحوال بمصادرة ما يدفعه الراشى أو الوسيط على سبيل الرشوة طبقا للمواد السابقة ."}, {"number": "111", "chapter": "الباب الثانى مكرر", "text": "يعد فى حكم الموظفين فى تطبيق نصوص هذا الفصل : 1 - المستخدمون فى المصالح التابعة للحكومة أو الموضوعة تحت رقابتها . 2 - أعضاء المجالس النيابية العامة أو المحلية سواء أكانوا منتخبين أو معينين . 3 - المحكمون والخبراء ووكلاء الديانة والمصفون والحراس القضائيون . 4 - الغيت ( [1] ) الغيت بالقانون رقم 112 لسنة 1957. 5 - كل شخص مكلف بخدمة عمومية . 6 - أعضاء مجالس إدارة ومديرو ومستخدمو المؤسسات والشركات والجمعيات والمنظمات والمنشآت إذا كانت الدولة أو إحدى الهيئات العامة تساهم فى مالها بنصيب ما بأية صفة كانت. كما يٌقصد بالموظف العمومى الأجنبى فى تطبيق أحكام هذا الباب كل من يشغل منصباً تشريعياً أو تنفيذياً أو إدارياً أو قضائياً لدى بلد أجنبى، سواء أكان معيناً أم منتخباً، وأى شخص يٌمارس وظيفة عمومية لصالح بلد أجنبى . أما موظف مؤسسة دولية عمومية فهو كل مستخدم مدنى دولى أو أى شخص تأذن له مؤسسه من هذا القبيل بأن يتصرف نيابة عنها. ( [1] ) المادة معدلة بإضافة الفقرة الثانية بالقانون رقم 5 لسنة 2018."}, {"number": "112", "chapter": "الباب الرابع", "text": "كل موظف عام اختلس أموالا أو أوراقا أو غيرها وجدت فى حيازته بسبب وظيفته يعاقب بالسجن المشدد: وتكون العقوبة السجن المؤبد فى الأحوال الآتية : أ - إذا كان الجانى من مأمورى التحصيل أو المندوبين له أو الأمناء على الودائع أو الصيارفة وسلم إليه المال بهذه الصفة. ب - إذا ارتبطت جريمة الاختلاس بجريمة تزوير أو استعمال محرر مزور ارتباطا لا يقبل التجزئة. جـ - إذا ارتكبت الجريمة فى زمن حرب وترتب عليها إضرار بمركز البلاد الاقتصادى أو بمصلحة قومية لها . ( [1] ) مستبدلة بالقانون 63 لسنة 1975 وعدلت بالقانون 95 لسنة 2003"}, {"number": "113", "chapter": "الباب الرابع", "text": "كل موظف عام استولى بغير حق على مال أو أوراق أو غيرها لإحدى الجهات المبينة فى المادة 119 ، أو سهل ذلك لغيره بأية طريقة كانت يعاقب بالسجن المشدد أو السجن . تكون العقوبة السجن المؤبد أو المشدد إذا ارتبطت الجريمة بجريمة تزوير أو استعمال محرر مزور ارتباطا لا يقبل التجزئة أو إذا ارتكبت الجريمة فى زمن حرب وترتب عليها إضرار بمركز البلاد الاقتصادى أو بمصلحة قومية لها . وتكون العقوبة الحبس والغرامة التى لا تزيد على خمسمائة جنيه أو إحدى هاتين العقوبتين إذا وقع الفعل غير مصحوب بنية التملك. ويعاقب بالعقوبات المنصوص عليها فى الفقرات السابقة حسب الأحوال كل موظف عام استولى بغير حق على مال خاص أو أوراق أو غيرها تحت يد إحدى الجهات المنصوص عليها فى المادة 119 أو سهل ذلك لغيره بأية طريقة كانت ."}, {"number": "113 مكرر", "chapter": "الباب الرابع", "text": "كل رئيس أو عضو مجلس إدارة إحدى شركات المساهمة أو مدير أو عامل بها اختلس أموالا أو أوراقا أو غيرها وجدت فى حيازته بسبب وظيفته أو استولى بغير حق عليها أو سهل ذلك لغيره أو بأية طريقة كانت يعاقب بالسجن مدة لا تزيد على خمس سنين . وتكون العقوبة الحبس مدة لا تزيد على سنتين والغرامة التى لا تزيد على مائتى جنيه أو إحدى هاتين العقوبتين إذا وقع فعل الاستيلاء غير مصحوب بنية التملك."}, {"number": "114", "chapter": "الباب الرابع", "text": "كل موظف عام له شأن فى تحصيل الضرائب أو الرسوم أو العوائد أو الغرامات أو نحوها ، طلب أو أخذ ما ليس مستحقا أو يزيد على المستحق مع علمه بذلك يعاقب بالسجن المشدد أو السجن . ( [1] ) مستبدلة بالقانون 63 لسنة 1975 وعدلت بالقانون 95 لسنة 2003"}, {"number": "115", "chapter": "الباب الرابع", "text": "كل موظف عام حصل أو حاول أن يحصل لنفسه أو حصل أو حاول أن يحصل لغيره ، بدون حق على ربح أو منفعة من عمل من أعمال وظيفته يعاقب بالسجن المشدد . ( [1] ) مستبدلة بالقانون 63 لسنة 1975 وعدلت بالقانون 95 لسنة 2003"}, {"number": "115 مكرر", "chapter": "الباب الرابع", "text": "كل كل موظف عام تعدى على أرض زراعية أو أرض فضاء أو مبان مملوكة أو فى حيازة وقف خيرى أو أحدى الجهات المبينة فى المادة (&#1633;&#1633;&#1641;) من هذا القانون، وذلك بزراعتها أو غرسها أو إقامة إنشاءات بها أو شغلها أو الانتفاع بها بأى صورة أو سهل ذلك لغيره بأى طريقة، يعاقب بالسجن مدة لا تقل عن خمس سنوات وغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مليون جنيه متى كان ذلك العقار يتبع الجهة التى يعمل بها أو جهة يتصل بها بحكم عمله. وتكون العقوبة السجن المؤبد أو المشدد وغرامة لا تقل عن مليون جنيه ولا تزيد على مليونى جنيه إذا ارتبطت الجريمة بجريمة تزوير أو استعمال محرر مزور ارتباطًا لا يقبل التجزئة. ويحكم على الجانى فى جميع الأحوال بالعزل من وظيفته أو زوال صفته وبرد العقار المغتصب بما يكون عليه ن مبان أو غراس أو برده مع إزالة ما عليه من تلك الأشياء على نفقته فضلاً عن دفع قيمة ما عاد عليه من منفعة. ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "116", "chapter": "الباب الرابع", "text": "كل موظف عام كان مسئولاً عن توزيع سلعة عهد إليه بتوزيعها وفقا لنظام معين فأخل عمدا بنظام توزيعها يعاقب بالحبس . وتكون العقوبة السجن إذا كانت السلعة متعلقة بقوت الشعب أو احتياجاته أو إذا وقعت الجريمة فى زمن الحرب ."}, {"number": "116مكرر", "chapter": "الباب الرابع", "text": "كل موظف عام أضر عمداً بأموال أو مصالح الجهة التى يعمل بها أو يتصل بها بحكم عمله أو بأموال الغير أو مصالحهم المعهود بها إلى تلك الجهة يعاقب بالسجن المشدد . فإذا كان الضرر الذى ترتب على فعله غير جسيم جاز الحكم عليه بالسجن . ( [1] ) مستبدلة بالقانون 63 لسنة 1975 وعدلت بالقانون 95 لسنة 2003"}, {"number": "116 مكرر", "chapter": "الباب الرابع", "text": "أ): كل موظف عام تسبب بخطئه فى إلحاق ضرر جسيم بأموال أو مصالح الجهة التى يعمل بها أو يتصل بها بحكم وظيفته أو بأموال الغير أو مصالحهم المعهود بها إلى تلك الجهة بأن كان ذلك ناشئاً عن إهمال فى أداء وظيفته أو عن إخلال بواجباتها أو إساءة استعمال السلطة، يعاقب بالحبس وبغرامة لا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين . وتكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على ست سنوات وغرامة لا تجاوز ألف جنيه إذا ترتب على الجريمة إضرار بمركز البلاد الاقتصادى أو بمصلحة قومية لها ."}, {"number": "116 مكرر", "chapter": "الباب الرابع", "text": "ب): كل من أهمل فى صيانة أو استخدام أى مال من الأموال العامة معهود به إليه أو تدخل فى صيانته أو استخدامه فى اختصاصه وذلك على نحو يعطل الانتفاع به أو يعرض سلامته أو سلامة الأشخاص للخطر يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين . وتكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على ست سنوات إذا ترتب على الإهمال وقوع حريق أو حادث آخر نشأت عنه وفاة شخص أو أكثر أو إصابة أكثر من ثلاثة أشخاص. وتكون العقوبة السجن ، إذا وقعت الجريمة المبينة فى الفقرة السابقة فى زمن حرب على وسيلة من وسائل الإنتاج المخصصة للمجهود الحربى ."}, {"number": "116 مكرر", "chapter": "الباب الرابع", "text": "ج): كل من أخل عمدا بتنفيذ كل أو بعض الالتزامات التى يفرضها عليه عقد مقاولة أو نقل أو توريد أو التزام أو أشغال عامة ارتبط به مع إحدى الجهات المبينة فى المادة 119 أو مع إحدى شركات المساهمة وترتب على ذلك ضرر جسيم ، أو إذا ارتكب أى غش فى تنفيذ هذا العقد يعاقب بالسجن . وتكون العقوبة السجن المؤبد أو المشدد إذا ارتكبت الجريمة فى زمن حرب وترتب عليها إضرار بمركز البلاد الاقتصادى أو بمصلحة قومية لها. وكل من استعمل أو ورد بضاعة أو مواد مغشوشة أو فاسدة تنفيذا لأى من العقود سالفة الذكر ، ولم يثبت غشه لها أو علمه بغشها أو إفسادها يعاقب بالحبس والغرامة التى لا تجاوز ألف جنيه أو إحدى هاتين العقوبتين وذلك ما لم يثبت أنه لم يكن فى مقدوره العلم بالغش أو الفساد . ويحكم على الجانى بغرامة تساوى قيمة الضرر المترتب على الجريمة . ويعاقب بالعقوبات سالفة الذكر على حسب الأحوال ، المتعاقدون من الباطن والوكلاء والوسطاء إذا كان الإخلال بتنفيذ الالتزام أو الغش راجعاً إلى فعلهم ."}, {"number": "17", "chapter": "الباب الرابع", "text": "كل موظف عام استخدم سخرة عمالا فى عمل لإحدى الجهات المبينة فى المادة 119 أو احتجز بغير مبرر أجورهم كلها أو بعضها يعاقب بالسجن المشدد. وتكون العقوبة الحبس إذا لم يكن الجانى موظفاً عاماً . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003."}, {"number": "117 مكرر", "chapter": "الباب الرابع", "text": "كل موظف عام خرب أو اتلف أو وضع النار عمداً فى أموال ثابتة أو منقولة أو أوراق أو غيرها للجهة التى يعمل بها أو يتصل بها بحكم عمله أو للغير متى كان معهودا بها إلى تلك الجهة يعاقب بالسجن المؤبد أو المشدد . وتكون العقوبة السجن المؤبد إذا ارتكبت إحدى هذه الجرائم بقصد تسهيل ارتكاب جريمة من الجرائم المنصوص عليها فى المواد 112، 113، 113 مكررا أو لإخفاء أداتها . ويحكم على الجانى فى جميع الأحوال بدفع قيمة الأموال التى خربها أو أتلفها أو أحرقها ."}, {"number": "118", "chapter": "الباب الرابع", "text": "فضلاً عن العقوبات المقررة للجرائم المذكورة فى المواد 112، 113 فقرة أولى وثانية ورابعة ، 113 مكرراً فقرة أولى ، 114، 115، 116، 116 مكرراً ، 117 فقرة أولى يعزل الجانى من وظيفته أو تزول صفته كما يحكم عليه فى الجرائم المذكورة فى المواد 112، 113 فقرة أولى وثانية ورابعة 113 مكررا فقرة أولى 114، 115 بالرد وبغرامة مساوية لقيمة ما اختلسه أو استولى عليه أو حصله أو طلبه من مال أو منفعة على ألا تقل عن خمسمائة جنيه ."}, {"number": "118 مكرر", "chapter": "الباب الرابع", "text": "مع عدم الإخلال بأحكام المادة السابقة يجوز فضلا عن العقوبات المقررة للجرائم المنصوص عليها فى هذا الباب ، الحكم بكل أو بعض التدابير الآتية : 1 - الحرمان من مزاولة المهنة مدة لا تزيد على ثلاث سنين. 2 - حظر مزاولة النشاط الاقتصادى الذى وقعت الجريمة بمناسبته مدة لا تزيد على ثلاث سنين . 3 - وقف الموظف عن عمله بغير مرتب أو بمرتب مخفض لمدة لا تزيد على ستة أشهر . 4 - العزل مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات تبدأ من نهاية تنفيذ العقوبة أو انقضائها لأى سبب آخر . 5 - نشر منطوق الحكم الصادر بالإدانة بالوسيلة المناسبة وعلى نفقة المحكوم عليه."}, {"number": "118 مكرر", "chapter": "الباب الرابع", "text": "أ): يجوز للمحكمة فى الجرائم المنصوص عليها فى هذا الباب وفقا لما تراه من ظروف الجريمة وملابساتها إذا كان المال موضوع الجريمة أو الضرر الناجم عنها لا تجاوز قيمته خمسمائة جنيه أن تقضى فيها - بدلا من العقوبات المقررة لها - بعقوبة الحبس أو بواحد أو أكثر من التدابير المنصوص عليها فى المادة السابقة. ويجب على المحكمة أن تقضى فضلا عن ذلك بالمصادرة والرد إن كان لهما محل ، وبغرامة مساوية لقيمة ما تم اختلاسه أو الاستيلاء عليه من مال أو ما تم تحقيقه من منفعة أو ربح ."}, {"number": "118مكرر", "chapter": "الباب الرابع", "text": "ب): يعفى من العقوبات المقررة للجرائم المنصوص عليها فى هذا الباب كل من بادر من الشركاء فى الجريمة من غير المحرضين على ارتكابها بإبلاغ السلطات القضائية أو الإدارية بالجريمة بعد تمامها وقبل اكتشافها . ويجوز الإعفاء من العقوبات المذكورة إذا حصل الإبلاغ بعد اكتشاف الجريمة وقبل صدور الحكم النهائى فيها . ولا يجوز إعفاء المبلغ بالجريمة من العقوبة طبقا للفقرتين السابقتين فى الجرائم المنصوص عليها فى المواد 112، 113، 113 مكرراً إذا لم يؤد الإبلاغ إلى رد المال موضوع الجريمة . ويجوز أن يعفى من العقاب كل من أخفى مالا متحصلا من إحدى الجرائم المنصوص عليها فى هذا الباب إذا أبلغ عنها وأدى ذلك إلى اكتشافها ورد كل أو بعض المال المتحصل عنها ."}, {"number": "119", "chapter": "الباب الرابع", "text": "يقصد بالأموال العامة فى تطبيق أحكام هذا الباب ما يكون كله أو بعضه مملوكاً لإحدى الجهات الآتية أو خاضعا لإشرافها أو لإدارتها : أ - الدولة ووحدات الإدارة المحلية . ب - الهيئات العامة والمؤسسات العامة ووحدات القطاع العام. جـ - الاتحاد الاشتراكى والمؤسسات التابعة له . د - النقابات والاتحادات . هـ - المؤسسات والجمعيات الخاصة ذات النفع العام . و - الجمعيات التعاونية . ز - الشركات والجمعيات والوحدات الاقتصادية والمنشآت التى تساهم فيها إحدى الجهات المنصوص عليها فى الفقرات السابقة . حـ - أية جهة أخرى ينص القانون على اعتبار أموالها من الأموال العامة . ( [1] ) مستبدلة بالقانون رقم 63 لسنة 1975."}, {"number": "119 مكرر", "chapter": "الباب الرابع", "text": "يقصد بالموظف العام فى حكم هذا الباب : أ - القائمون بأعباء السلطة العامة والعاملون فى الدولة ووحدات الإدارة المحلية . ب - رؤساء وأعضاء المجالس والوحدات والتنظيمات الشعبية وغيرها ممن لهم صفة نيابية عامة سواء كانوا منتخبين أو معينين. ج - أفراد القوات المسلحة . د - كل من فوضته إحدى السلطات العامة فى القيام بعمل معين وذلك فى حدود العمل المفوض فيه . هـ - رؤساء وأعضاء مجالس الإدارة والمديرون وسائر العاملين فى الجهات التى اعتبرت أموالها أموالاً عامة طبقاً للمادة السابقة . و - كل من يقوم بأداء عمل يتصل بالخدمة العامة بناء على تكليف صادر إليه بمقتضى القوانين أو من موظف عام فى حكم الفقرات السابقة متى كان يملك هذا التكليف بمقتضى القوانين أو النظم المقررة وذلك بالنسبة للعمل الذى يتم التكليف به. ويستوى أن تكون الوظيفة أو الخدمة دائمة أو مؤقتة بأجر أو بغير أجر طواعية أو جبراً . ولا يحول انتهاء الخدمة أو زوال الصفة دون تطبيق أحكام هذا الباب متى وقع العمل أثناء الخدمة أو توافر الصفة ."}, {"number": "120", "chapter": "الباب الخامس", "text": "كل موظف توسط لدى قاض أو محكمة لصالح أحد الخصوم أو إضراراً به سواء بطريق الأمر أو الطلب أو الرجاء أو التوصية يعاقب بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تتجاوز خمسمائة جنيه ."}, {"number": "121", "chapter": "الباب الخامس", "text": "كل قاض امتنع عن الحكم أو صدر منه حكم ثبت أنه غير حق وكان ذلك بناء على سبب من الأسباب المذكورة فى المادة السابقة يعاقب بالعقوبة المنصوص عليها فى المادة 105 مكرراً وبالعزل."}, {"number": "122", "chapter": "الباب الخامس", "text": "إذا امتنع أحد القضاة فى غير الأحوال المذكورة عن الحكم يعاقب بالعزل وبغرامة لا تزيد على مائتى جنيه . ويعد ممتنعاً عن الحكم كل قاض أبى أو توقف عن إصدار حكم بعد تقديم طلب إليه فى هذا الشأن بالشروط المبينة فى قانون المرافعات فى المواد المدنية والتجارية ولو احتج بعدم وجود نص فى القانون أو بأن النص غير صريح أو بأى وجه آخر ."}, {"number": "123", "chapter": "الباب الخامس", "text": "يعاقب بالحبس والعزل كل موظف عمومى استعمل سلطة وظيفته فى وقف تنفيذ الأوامر الصادرة من الحكومة أو أحكام القوانين واللوائح أو تأخير تحصيل الأموال والرسوم أو وقف تنفيذ حكم أو أمر صادر من المحكمة أو من أية جهة مختصة . كذلك يعاقب بالحبس والعزل كل موظف عمومى امتنع عمداً عن تنفيذ حكم أو أمر مما ذكر بعد مضى ثـمانية أيام من إنذاره على يد محضر إذا كان تنفيذ الحكم أو الأمر داخلا فى اختصاص الموظف ."}, {"number": "124", "chapter": "الباب الخامس", "text": "إذا ترك ثلاثة على الأقل من الموظفين أو المستخدمين العموميين عملهم ولو فى صورة الاستقالة أو امتنعوا عمداً عن تأدية واجب من واجبات وظيفتهم متفقين على ذلك أو مبتغين منه تحقيق غرض مشترك عوقب كل منهم بالحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة وبغرامة لا تزيد على مائة جنيه. ويضاعف الحد الأقصى لهذه العقوبة إذا كان الترك أو الامتناع من شأنه أن يجعل حياة الناس أو صحتهم أو أمنهم فى خطر أو كان من شأنه أن يحدث اضطرابا أو فتنة بين الناس أو إذا أضر بمصلحة عامة. وكل موظف أو مستخدم عمومى ترك عمله أو امتنع عن عمل من أعمال وظيفته بقصد عرقلة سير العمل أو الإخلال بانتظامه يعاقب بالحبس مدة لا تجاوز ستة أشهر أو بغرامة لا تجاوز خمسمائة جنيه. ويضاعف الحد الأقصى لهذه العقوبة إذا كان الترك أو الامتناع من شأنه أن يجعل حياة الناس أو صحتهم أو أمنهم فى خطر أو كان من شأنه أن يحدث اضطراباً أو فتنة بين الناس أو إذا أضر بمصلحة عامة."}, {"number": "124", "chapter": "الباب الخامس", "text": "أ) : يعاقب بضعف العقوبات المقررة بالمادة 124 كل من اشترك بطريق التحريض فى ارتكاب جريمة من الجرائم المبينة بها . ويعاقب بالعقوبات المقررة بالفقرة الأولى من المادة المذكورة كل من حرض أو شجع موظفاً أو مستخدماً عمومياً أو موظفين أو مستخدمين عموميين بأية طريقة كانت على ترك العمل أو الامتناع عن تأدية واجب من واجبات الوظيفة إذا لم يترتب على تحريضه أو تشجيعه أية نتيجة . وفضلا عن العقوبات المتقدم ذكرها يحكم بالعزل إذا كان مرتكب الجريمة من الموظفين أو المستخدمين العموميين . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "124", "chapter": "الباب الخامس", "text": "ب): يعاقب بالعقوبات المبينة فى الفقرة الثانية من المادة 124 كل من اعتدى أو شرع فى الاعتداء على حق الموظفين أو المستخدمين العموميين فى العمل باستعمال القوة أو العنف أو الإرهاب أو التهديد أو التدابير غير المشروعة على الوجه المبين فى المادة 375 ."}, {"number": "124", "chapter": "الباب الخامس", "text": "ج): فيما يتعلق بتطبيق المواد الثلاث السابقة يعد كالموظفين والمستخدمين العموميين جميع الأجراء الذين يشتغلون بأية صفة كانت فى خدمة الحكومة أو فى خدمة سلطة من السلطات الإقليمية أو البلدية أو القروية والأشخاص الذين يندبون لتأدية عمل معين من أعمال الحكومة أو السلطات المذكورة ."}, {"number": "125", "chapter": "الباب الخامس", "text": "كل من سعى من أرباب الوظائف العمومية وغيرهم بطريق الغش فى إضرار أو تعطيل سهولة المزايدات المتعلقة بالحكومة يعاقب فضلا عن عزله بالحبس مدة لا تزيد على سنتين مع إلزامه بأن يدفع للحكومة بدل الخسائر التى نشأت عن فعله المذكور ."}, {"number": "126", "chapter": "الباب السادس", "text": "كل موظف أو مستخدم عمومى أمر بتعذيب متهم أو فعل ذلك بنفسه لحمله على الاعتراف يعاقب السجن المشدد أو السجـن من ثلاث سنوات إلى عشر . وإذا مات المجنى عليه يحكم بالعقوبة المقررة للقتل عمداً . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003."}, {"number": "127", "chapter": "الباب السادس", "text": "يعاقب بالسجن كل موظف عام ، وكل شخص مكلف بخدمة عامة أمر بعقاب المحكوم عليه أو عاقبه بنفسه بأشد من العقوبة المحكوم بها عليه قانونا أو بعقوبة لم يحكم بها عليه ."}, {"number": "128", "chapter": "الباب السادس", "text": "إذا دخل أحد الموظفين أو المستخدمين العموميين أو أى شخص مكلف بخدمة عمومية اعتماداً على وظيفته منزل شخص من آحاد الناس بغير رضائه فيما عدا الأحوال المبينة فى القانون أو بدون مراعاة القواعد المقررة فيه يعاقب بالحبس أو بغرامة لا تزيد على مائتى جنيه مصرى."}, {"number": "129", "chapter": "الباب السادس", "text": "كل موظف أو مستخدم عمومى وكل شخص مكلف بخدمة عمومية استعمل القسوة مع الناس اعتماداً على وظيفته بحيث أنه أخل بشرفهم أو أحدث آلاماً بأبدانهم يعاقب بالحبس مدة لا تزيد على سنة أو بغرامة لا تزيد على مائتى جنيه مصرياً ."}, {"number": "130", "chapter": "الباب السادس", "text": "كل موظف عمومى أو مستخدم عمومى وكل إنسان مكلف بخدمة عمومية اشترى بناء على سطوة وظيفته ملكاً عقاراً كان أو منقولاً قهراً عن مالكه أو استولى على ذلك بغير حق أو أكره المالك على بيع ما ذكر لشخص آخر يعاقب بحسب درجة ذنبه بالحبس مدة لا تزيد على سنتين وبالعزل فضلاً عن رد الشىء المغتصب أو قيمته إن لم يوجد عينا ."}, {"number": "131", "chapter": "الباب السادس", "text": "كل موظف عمومى أوجب على الناس عملا فى غير الحالات التى يجيز فيها القانون ذلك أو استخدم أشخاصا فى غير الأعمال التى جمعوا لها بمقتضى القانون يعاقب بالحبس مدة لا تزيد على سنتين وبالعزل فضلا عن الحكم عليه بقيمة الأجور المستحقة لمن استخدمهم بغير حق ."}, {"number": "132", "chapter": "الباب السادس", "text": "كل موظف عمومى أو مستخدم عمومى تعدى فى حالة نزوله عند أحد من الناس الكائنة مساكنهم بطريق مأموريته بأن أخذ منه قهرا بدون ثـمن أو بثمن بخس مأكولاً أو علفاً يحكم عليه بالحبس مدة لا تزيد على ثلاثة شهور أو بغرامة لا تتجاوز مائتى جنيه مصرياً وبالعزل فى الحالتين فضلاً عن الحكم برد ثـمن الأشياء المأخوذة لمستحقيها."}, {"number": "133", "chapter": "الباب السابع", "text": "من أهان بالإشارة أو القول أو التهديد موظفاً عمومياً أو أحد رجال الضبط أو أى إنسان مكلف بخدمة عمومية أثناء تأدية وظيفته أو بسبب تأديتها يعاقب بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تتجاوز مائتى جنيه مصريا . فإذا وقعت الإهانة على محكمة قضائية أو إدارية أو مجلس أو على أحد أعضائه وكان ذلك أثناء انعقاد الجلسة تكون العقوبة الحبس مدة لا تزيد على سنة أو غرامة لا تتجاوز خمسمائة جنيه مصرياً."}, {"number": "134", "chapter": "الباب السابع", "text": "يحكم بالعقوبة المقررة بالفقرة الأولى من المادة السابقة إذا وجهت الإهانة بواسطة التلغراف أو التليفون أو الكتابة أو الرسم ."}, {"number": "135", "chapter": "الباب السابع", "text": "كل من أزعج إحدى السلطات العامة أو الجهات الإدارية أو الأشخاص المكلفين بخدمة عمومية بأن أخبر بأية طريقة كانت عن وقوع كوارث أو حوادث أو أخطار لا وجود لها يعاقب بالحبس مدة لا تتجاوز ثلاثة أشهر وبغرامة لا تزيد على مائتى جنيه أو بإحدى هاتين العقوبتين . وتقضى المحكمة فوق ذلك بالمصاريف التى تسببت عن هذا الإزعاج."}, {"number": "136", "chapter": "الباب السابع", "text": "كل من تعدى على أحد الموظفين العموميين أو رجال الضبط أو أى إنسان مكلف بخدمة عمومية أو قاومه بالقوة أو العنف أثناء تأدية وظيفته أو بسبب تأديتها يعاقب بالحبس مـدة لا تزيد على ستة شهور أو بغرامة لا تتجاوز مائتى جنيه مصرياً."}, {"number": "137", "chapter": "الباب السابع", "text": "وإذا حصل مع التعدى أو المقاومة ضرب أو نشأ عنهما جرح تكون العقوبة الحبس مدة لا تزيد على سنتين أو غرامة لا تتجاوز مائتى جنيه مصريا. فإذا حصل الضرب أو الجرح باستعمال أية أسلحة أو عصى أو آلات أو أدوات أخرى أو بلغ الضرب أو الجرح درجة الجسامة المنصوص عليها فى المادة 241 تكون العقوبة الحبس."}, {"number": "137 مكرر", "chapter": "الباب السابع", "text": "يكون الحد الأدنى للعقوبات فى الجرائم المنصوص عليها فى المواد 133 ، 136 ، 137 خمسة عشر يوماً بالنسبة إلى عقوبة الحبس وعشر جنيهات بالنسبة إلى عقوبة الغرامة إذا كان المجنى عليه فيها موظفاً عمومياً أو مكلفاً بخدمة عامة بالسكك الحديدية أو غيرها من وسائل النقل العام ووقع عليه الاعتداء أثناء سيرها أو توقفها بالمحطات ."}, {"number": "137مكرر", "chapter": "الباب السابع", "text": "أ) : يعاقب بالسجن مدة لا تزيد على خمس سنين كل من استعمل القوة أو العنف أو التهديد مع موظف عام أو شخص مكلف بخدمة عامة ليحمله بغير حق على أداء عمل من أعمال وظيفته أو على الامتناع عنه ولم يبلغ بذلك مقصده فإذا بلغ الجانى مقصده تكون العقوبة السجن مدة لا تزيد على عشر سنين. وتكون العقوبة السجن فى الحالتين إذا كان الجانى يحمل سلاحاً ، وتكون العقوبة السجن المشدد إلى عشر سنين إذا صدر من الجانى ضرب أو جرح نشأ عنه عاهة مستديمة . وتكون العقوبة السجن المشدد إذا أفضى الضرب أو الجرح المشار إليه فى الفقرة السابقة إلى الموت . ( [1] ) مضافة بقانون 120 لسنة 1962 وعدلت بالقانون 95 لسنة 2003"}, {"number": "138", "chapter": "الباب الثامن", "text": "كل إنسان قبض عليه قانونا فهرب يعاقب بالحبس مدة لا تزيد على ستة شهور أو بغرامة لا تتجاوز مائتى جنيه مصرياً. فإذا كان صادراً على المتهم أمراً بالقبض عليه وإيداعه فى السجن وكان محكوما عليه بالحبس أو بعقوبة أشد يعاقب بالحبس مدة لا تزيد على سنتين أو بغرامة لا تتجاوز خمسمائة جنيه مصرياً. وتتعدد العقوبات إذا كان الهرب فى إحدى الحالتين السابقتين مصحوبا بالقوة أو بجريمة أخرى ."}, {"number": "139", "chapter": "الباب الثامن", "text": "كل من كان مكلفاً بحراسة مقبوض عليه أو بمرافقته أو بنقله وهرب بإهمال منه يعاقب بالحبس مدة لا تزيد على سنتين أو بغرامة لا تجاوز خمسمائة جنيه مصرى إذا كان المقبوض عليه الذى هرب محكوماً عليه بعقوبة جناية أو متهما بجناية ، وأما فى الأحوال الأخرى فتكون العقوبة الحبس مدة لا تزيد على ستة أشهر أو غرامة لا تجاوز مائتى جنيه مصرى."}, {"number": "140", "chapter": "الباب الثامن", "text": "كل من كان مكلفاً بحراسة مقبوض عليه أو بمرافقته أو بنقله وساعده على هربه أو سهله له أو تغافل عنه يعاقب طبقاً للأحكام الآتية : - إذا كان المقبوض عليه محكوما عليه بالإعدام تكون العقوبة السجن المشدد . - وإذا كان محكوماً عليه بالسجن المؤبد أو المشدد أو كان متهما بجريمة عقوبتها الإعدام تكون العقوبة السجن . - وفى الأحوال الأخرى تكون العقوبة الحبس ."}, {"number": "141", "chapter": "الباب الثامن", "text": "كل موظف أو مستخدم عمومى مكلف بالقبض على إنسان ويهمل فى الإجراءات اللازمة لذلك بقصد معاونته على الفرار من وجه القضاء يجازى بالعقوبات المدونة فى المادة السابقة بحسب الأحوال المبينة فيها ."}, {"number": "142", "chapter": "الباب الثامن", "text": "كل من مكن مقبوضاً عليه من الهرب أو ساعده عليه أو سهله له فى غير الأحوال السالفة يعاقب طبقاً للأحكام الآتية : إذا كان المقبوض عليه محكوماً عليه بالإعدام تكون العقوبة السجن المشدد أو السجن من ثلاث سنين إلى سبع ، فإذا كان محكوماً عليه بالسجن المؤبد أو المشدد أو كان متهماً بجريمة عقوبتها الإعدام تكون العقوبة السجن من ثلاث سنين إلى سبع. وأما فى الأحوال الأخرى فتكون العقوبة الحبس ."}, {"number": "143", "chapter": "الباب الثامن", "text": "كل من أعطى أسلحة لمقبوض عليه لمساعدته على الهرب يعاقب بالسجن المشدد من ثلاث سنين إلى سبع. ( [1] ) معدلة بالقانون رقم 95 لسنة 2003."}, {"number": "144", "chapter": "الباب الثامن", "text": "كل من أخفى بنفسه أو بواسطة غيره شخصا فر بعد القبض عليه أو متهماً بجناية أو جنحة أو صادراً فى حقه أمر بالقبض عليه ، وكذا كل من أعانه بأى طريقة كانت على الفرار من وجه القضاء مع علمه بذلك يعاقب طبقا للأحكام الآتية: إذا كان من أخفى أو سوعد على الاختفاء أو الفرار من وجه القضاء قد حكم عليه بالإعدام تكون العقوبة السجن من ثلاث سنين إلى سبع . وإذا كان محكوماً عليه بالسجن المؤبد أو المشدد أو كان متهماً بجريمة عقوبتها الإعدام تكون العقوبة الحبس . وأما فى الأحوال الأخرى فتكون العقوبة الحبس مدة لا تزيد على سنتين . ولا تسرى هذه الأحكام على زوج أو زوجة من أخفى أو سوعد على الاختفاء أو الفرار من وجه القضاء ولا على أبويه أو أجداده أو أولاده أو أحفاده ."}, {"number": "145", "chapter": "الباب الثامن", "text": "كل من علم بوقوع جناية أو جنحة أو كان لديه ما يحمله على الاعتقاد بوقوعها وأعان الجانى بأى طريقة كانت على الفرار من وجه القضاء إما بإيواء الجانى المذكور وإما بإخفاء أدلة الجريمة وإما بتقديم معلومات تتعلق بالجريمة وهو يعلم بعدم صحتها أو كان لديه ما يحمله على الاعتقاد بذلك يعاقب طبقاً للأحكام الآتية : إذا كانت الجريمة التى وقعت يعاقب عليها بالإعدام تكون العقوبة بالحبس مدة لا تتجاوز سنتين . وإذا كانت الجريمة التى وقعت يعاقب عليها بالسجن المشدد أو السجن تكون العقوبة بالحبس مدة لا تتجاوز سنة . أما فى الأحوال الأخرى فتكون العقوبة الحبس مدة لا تتجاوز ستة شهور ، وعلى كل حال لا يجوز أن تتعدى العقوبة الحد الأقصى المقرر للجريمة نفسها . ولا تنطبق أحكام هذه المادة على الزوج أو الزوجة أو أصول أو فروع الجانى."}, {"number": "146", "chapter": "الباب الثامن", "text": "كل من أخفى بنفسه أو بواسطة غيره أحد الفارين من الخدمة العسكرية أو ساعده مع علمه بذلك على الفرار من وجه القضاء يعاقب بالحبس مدة لا تزيد على سنتين. ولا تسرى هذه الأحكام على زوجة الفار من الخدمة العسكرية."}, {"number": "147", "chapter": "الباب التاسع", "text": "إذا صار فك ختم من الأختام الموضوعة لحفظ محل أو أوراق أو أمتعة بناء على أمر صادر من إحدى جهات الحكومة أو إحدى المحاكم فى مادة من المواد يحكم على الحراس لإهمالهم بدفع غرامة لا تتجاوز خمسمائة جنيه مصريا إن كان هناك حراس ."}, {"number": "148", "chapter": "الباب التاسع", "text": "إذا كانت الأختام موضوعة على أوراق أو أمتعة لمتهم فى جناية أو محكوم عليه فى جناية يعاقب الحارس الذى وقع منه الإهمال بالحبس مدة لا تزيد على سنة أو بغرامة لا تتجاوز خمسمائة جنيه مصريا ."}, {"number": "149", "chapter": "الباب التاسع", "text": "كل من فك ختما من الأختام الموضوعة لحفظ أوراق أو أمتعة من قبيل ما ذكر فى المادة السابقة يعاقب بالحبس مدة لا تزيد على سنة ، فإن كان الفاعل لذلك هو الحارس نفسه يعاقب بالسجن من ثلاث سنين إلى سبع ."}, {"number": "150", "chapter": "الباب التاسع", "text": "إذا كانت الأختام التى صار فكها موضوعة لأمر غير ما ذكر يعاقب من فكها بالحبس مدة لا تزيد على ستة شهور أو بغرامة لا تتجاوز مائتى جنيه مصريا . وإن كان الفاعل لذلك هو الحارس نفسه فيعاقب ، بالحبس مدة لا تتجاوز سنة ."}, {"number": "151", "chapter": "الباب التاسع", "text": "إذا سرقت أوراق أو سندات أو سجلات أو دفاتر متعلقة بالحكومة أو أوراق مرافعة قضائية أو اختلست أو أتلفت وكانت محفوظة فى المخازن العمومية المعدة لها أو مسلمة إلى شخص مأمور بحفظها يعاقب من كانت فى عهدته بسبب إهماله فى حفظها بالحبس مدة لا تتجاوز ثلاثة شهور أو بغرامة لا تزيد على ثلاثـمائة جنيه مصريا."}, {"number": "152", "chapter": "الباب التاسع", "text": "وأما من سرق أو اختلس أو أتلف شيئاً مما ذكر فى المادة السابقة فيعاقب بالحبس ."}, {"number": "153", "chapter": "الباب التاسع", "text": "إذا حصل فك الأختام أو سرقة الأوراق أو اختلاسها أو إتلافها مع إكراه الحافظين لها يعاقب فاعل ذلك بالسجن المشدد."}, {"number": "154", "chapter": "الباب التاسع", "text": "كل من أخفى من موظفى الحكومة أو البوستة أو مأموريهما أو فتح مكتوبا من المكاتيب المسلمة للبوستة أو سهل ذلك لغيره يعاقب بالحبس أو بغرامة لا تزيد على مائتى جنيه وبالعزل فى الحالتين . وكذلك كل من أخفى من موظفى الحكومة أو مصلحة التلغرافات أو مأموريهما تلغرافا من التلغرافات المسلمة إلى المصلحة المذكورة أو أفشاه أو سهل ذلك لغيره يعاقب بالعقوبتين المذكورتين ."}, {"number": "155", "chapter": "الباب العاشر", "text": "كل من تداخل فى وظيفة من الوظائف العمومية ملكية كانت أو عسكرية من غير أن تكون له صفة رسمية من الحكومة أو إذن منها بذلك أو أجرى عملاً من مقتضيات إحدى هذه الوظائف يعاقب بالحبس ."}, {"number": "156", "chapter": "الباب العاشر", "text": "كل من لبس علانية كسوة رسمية بغير أن يكون حائزاً للرتبة التى تخوله ذلك أو حمل علانية العلامة المميـزة لعمل أو لوظيفة من غير حق يعاقب بالحبس مدة لا تزيد على سنة ."}, {"number": "157", "chapter": "الباب العاشر", "text": "يعاقب بغرامة لا تتجاوز مائتى جنيه كل من تقلد علانية نيشاناً لم يمنحه أو لقب نفسه كذلك بلقب من ألقاب الشرف أو برتبة أو بوظيفة أو بصفة نيابية عامة من غير حق."}, {"number": "158", "chapter": "الباب العاشر", "text": "يعاقب بغرامة لا تتجاوز مائتى جنيه كل مصرى تقلد علانية بغير حق أو بغير إذن رئيس الجمهورية نيشاناً أجنبياً أو لقب نفسه كذلك بلقب شرف أجنبى أو برتبة أجنبية ."}, {"number": "159", "chapter": "الباب العاشر", "text": "فى الأحوال المنصوص عليها فى المادتين السابقتين يجوز للمحكمة أن تأمر بنشر الحكم بأكمله أو بنشر ملخصه فى الجرائد التى تختارها ويكون النشر على نفقة المحكوم عليه ."}, {"number": "160", "chapter": "الباب الحادى عشر", "text": "يعاقب بالحبس وبغرامة لا تقل عن مائة جنيه ولا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين: أولا : كل من شوش على إقامة شعائر ملة أو احتفال دينى خاص بها أو عطلها بالعنف أو التهديد . ثانياً : كل من خرب أو كسر أو أتلف أو دنس مبانى معدة لإقامة شعائر دين أو رموزا أو أشياء أخرى لها حرمة عند أبناء ملة أو فريق من الناس . ثالثاً : كل من انتهك حرمة القبور أو الجبانات أو دنسها . وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى من الجرائم المنصوص عليها فى المادة 160 تنفيذا لغرض إرهابى."}, {"number": "161", "chapter": "الباب الحادى عشر", "text": "يعاقب بتلك العقوبات على كل تعد يقع بإحدى الطرق المبينة بالمادة 171 على أحد الأديان التى تؤدى شعائرها علناً ، ويقع تحت أحكام هذه المادة : أولاً : طبع أو نشر كتاب مقدس فى نظر أهل دين من الأديان التى تؤدى شعائرها علناً إذا حرف عمداً نص هذا الكتاب تحريفا يغير من معناه . ثانياً : تقليد احتفال دينى فى مكان عمومى أو مجتمع عمومى بقصد السخرية به أو ليتفرج عليه الحضور ."}, {"number": "161 مكرر", "chapter": "الباب الحادى عشر", "text": "يعاقب بالحبس وبغرامة لاتقل عن ثلاثين الف جنيه ولاتتجاوز خمسين الف جنيه أو بإحدى هاتين العقوبتين كل من قام بعمل أو بالامتناع عن عمل يكون من شأنه أحداث التمييز بين الافراد أو ضد طائفة من طوائف الناس بسبب الجنس أو الأصل أو اللغة أو الدين أو العقيدة وترتب على هذا التمييز اهدار لمبدأ تكافؤ الفرص أو العدالة الاجتماعية أو تكدير للسلم العام. وتكون العقوبة الحبس مدة لا تقل عن ثلاثة أشهر والغرامة التى لا تقل عن خمسين ألف جنيه ولا تتجاوز مائة ألف جنيه أو بإحدى هاتين العقوبتين اذا أرتكبت الجريمة المشار إليها فى الفقرة الأولى من هذه المادة من موظف عام أو مستخدم عمومى أو أى إنسان مكلف بخدمة عمومية. ( [1] ) مضافة بالمرسوم بقانون رقم 126 لسنة 2011."}, {"number": "162", "chapter": "الباب الثانى عشر", "text": "كل من هدم أو أتلف عمداً شيئا من المبانى أو الأملاك أو المنشآت المعدة للنفع العام أو الأعمال المعدة للزينة ذات القيمة التذكارية أو الفنية ، وكل من قطع أو أتلف أشجاراً مغروسة فى الأماكن المعدة للعبادة أو فى الشوارع أو فى المتنزهات أو فى الأسواق أو فى الميادين العامة يعاقب بالحبس وبغرامة لا تقل عن مائة جنيه ولا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين فضلاً عن الحكم عليه بدفع قيمة الأشياء التى هدمها أو أتلفها أو قطعها . ويضاعف الحد الأقصى للعقوبة المقررة فى المادة 162 إذا ارتكبت الجريمة تنفيذا لغرض إرهابى"}, {"number": "162 مكرر", "chapter": "الباب الثانى عشر", "text": "يعاقب بالسجن كل من تسبب عمداً فى إتلاف خط من خطوط الكهرباء التى تملكها الحكومة أو الهيئات أو المؤسسات العامة أو الوحدات التابعة لها ، أو ترخص فى إنشائها لمنفعة عامة وذلك بقطعه الأسلاك الموصلة للتيار الكهربائى أو الكابلات أو كسر شىء من العدد أو الآلات أو عازلات الأسلاك أو إتلاف الأبراج أو المحطات أو الشبكات المتصلة بالخطوط الكهربائية المذكورة أو جعلها كلها أو بعضها غير صالحة للاستعمال بأى كيفية كانت ، بحيث ترتب على ذلك انقطاع التيار الكهربائى ولو مؤقتاً . وإذا حدث فعل من الأفعال المشار إليها فى الفقرة السابقة نتيجة إهمال أو عدم احتراس ، فتكون العقوبة الحبس الذى لا يجاوز ستة أشهر أو الغرامة التى لا تجاوز خمسمائة جنيه. وفى جميع الأحوال يجب الحكم بدفع قيمة الأشياء التى أتلفها المحكوم عليه أو قطعها أو كسرها ."}, {"number": "162مكرر", "chapter": "الباب الثانى عشر", "text": "أولاً) : كل من ارتكب فى زمن هياج أو فتنة فعلاً من الأفعال المشار إليها فى الفقرة الأولى من المادة السابقة ، أو قام بالاستيلاء على أحد مرافق توليد أو توصيل التيار الكهربائى المذكور فى الفقرة المشار إليها بالقوة الجبرية أو بأية طريقة كانت ، بحيث ترتب على ذلك انقطاع التيار الكهربائى وكذا كل من منع قهراً إصلاح شىء مما ذكر، يعاقب بالسجن المشدد فضلا عن الحكم عليه بدفع قيمة الأشياء التى أتلفها أو قطعها أو كسرها . ( [1] ) مضافة بالقانون 14 لسنة 1973 ومعدلة بالقانون 95 لسنة 2003."}, {"number": "163", "chapter": "الباب الثالث عشر", "text": "كل من عطل المخابرات التلغرافية أو أتلف شيئاً من آلاتها سواء بإهماله أو عدم اكتراسه بحيث ترتب على ذلك انقطاع المخابرات يعاقب بدفع غرامة لا تتجاوز خمسمائة جنيه مصريا. وفى حالة حصول ذلك بسوء قصد ثابت تكون العقوبة السجن مع عدم الإخلال فى كلتا الحالتين بالحكم بالتعويض ."}, {"number": "164", "chapter": "الباب الثالث عشر", "text": "كل من تسبب عمداً فى انقطاع المراسلات التلغرافية بقطعه الأسلاك الموصلة أو كسر شيئا من العدد أو عوازل الأسلاك أو القوائم الرافعة لها أو بأى كيفية كانت يعاقب بالسجن مع عدم الإخلال بإلزامه بالتعويض عن الخسارة ."}, {"number": "165", "chapter": "الباب الثالث عشر", "text": "كل من أتلف فى زمن هياج أو فتنة خطا من الخطوط التلغرافية أو أكثر أو جعلها ولو مؤقتاً غير صالحة للاستعمال بأى كيفية كانت أو استولى عليها بالقوة الإجبارية أو بطريقة أخرى بحيث ترتب على ذلك انقطاع المخابرات بين ذوى السلطة العمومية أو منع توصيل مخابرات آحاد الناس وكذا من منع قهرا تصليح خط تلغرافى يعاقب بالسجن المشدد فضلاً عن إلزامه بجبر الخسارة المترتبة على فعله المذكور ."}, {"number": "166", "chapter": "الباب الثالث عشر", "text": "تسرى أحكام المواد الثلاث السابقة على الخطوط التليفونية التى تنشئها الحكومة أو ترخص بإنشائها لمنفعة عمومية."}, {"number": "166 مكرر", "chapter": "الباب الثالث عشر", "text": "كل من تسبب عمداً فى إزعاج غيره بإساءة استعمال أجهزة المواصلات التليفونية يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تزيد على مائة جنيه أو بإحدى هاتين العقوبتين ."}, {"number": "167", "chapter": "الباب الثالث عشر", "text": "كل من عرض للخطر عمداً سلامة وسائل النقل العامة البرية أو المائية أو الجوية أو عطل سيرها يعاقب بالسجن المشدد أو بالسجن ."}, {"number": "168", "chapter": "الباب الثالث عشر", "text": "إذا نشأ عن الفعل المذكور فى المادة السابقة جروح من المنصوص عليها فى المادة 240 أو 241 تكون العقوبة السجن المشدد أما إذا نشأ عنه موت شخص فيعاقب مرتكبه بالإعدام أو بالسجن المؤبد ."}, {"number": "169", "chapter": "الباب الثالث عشر", "text": "كل من تسبب بغير عمد فى حصول حادث لإحدى وسائل النقل العامة البرية أو المائية أو الجوية من شأنه تعريض الأشخاص الذين بها للخطر يعاقب بالحبس مدة لا تتجاوز ستة شهور أو بغرامة لا تتجاوز مائتى جنيه مصريا ، أما إذا نشأ عنه موت شخص أو إصابات بدنية فتكون العقوبة الحبس."}, {"number": "170", "chapter": "الباب الثالث عشر", "text": "كل من نقل أو شرع فى نقل مفرقعات أو مواد قابلة للالتهاب فى قطارات السكك الحديدية أو فى مركبات أخرى معدة لنقل الجماعات مخالفاً فى ذلك لوائح البوليس الخاصة بالقطارات أو المركبات المذكورة يعاقب بالحبس مدة لا تتجاوز شهراً وبغرامة لا تزيد على مائتى جنيه أو بإحدى هاتين العقوبتين فقط، يعاقب بنفس العقوبة المنصوص عليها فى الفقرة السابقة كل من نقل أو شرع فى نقل مفرقعات أو مواد قابلة للالتهاب فى الرسائل البريدية فى غير الحالات المصرح فيها بنقل مثل هذه الأشياء."}, {"number": "170 مكرر", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مدة لا تجاوز ستة أشهر وبغرامة لا تقل عن عشرة جنيهات ولا تزيد على مائتى جنيه أو بإحدى هاتين العقوبتين : أولاً : كل من ركب فى عربات السكك الحديدية أو غيرها من وسائل النقل العام وامتنع عن دفع الأجرة أو الغرامة أو ركب فى درجة أعلى من درجة التذكرة التى يحملها وامتنع عن دفع الفرق. ثانياً : كل من ركب فى غير الأماكن المعدة للركوب بإحدى وسائل النقل العام ."}, {"number": "171", "chapter": "الباب الرابع عشر", "text": "كل من حرض واحداً أو أكثر بإرتكاب جناية أو جنحة بقول أو صياح جهر به علناً أو بفعل أو إيماء صدر منه علناً أو بكتابة أو رسوم أو صور أو صور شمسية أو رموز أو أية طريقة أخرى من طرق التمثيل جعلها علنية أو بأية وسيلة أخرى من وسائل العلانية يعد شريكا فى فعلها ويعاقب بالعقاب المقرر لها إذا ترتب على هذا التحريض وقوع تلك الجناية أو الجنحة بالفعل. أما إذا ترتب على التحريض مجرد الشروع فى الجريمة فيطبق القاضى الأحكام القانونية فى العقاب على الشروع. ويعتبر القول أو الصياح علنياً إذا حصل الجهر به أو ترديده بإحدى الوسائل الميكانيكية فى محفل عام أو طريق عام أو أى مكان آخر مطروق أو إذا حصل الجهر به أو ترديده بحيث يستطيع سماعه من كان فى مثل ذلك الطريق أو المكان أو إذا أذيع بطريق اللاسلكى أو بأية طريقة أخرى. ويكون الفعل أو الإيماء علنيا إذا وقع فى محفل عام أو طريق عام أو فى أى مكان آخر مطروق أو إذا وقع بحيث يستطيع رؤيته من كان فى مثل ذلك الطريق أو المكان. وتعتبر الكتابة والرسوم والصور والصور الشمسية والرموز وغيرها من طرق التمثيل علنية إذا وزعت بغير تمييز على عدد من الناس أو إذا عرضت بحيث يستطيع أن يراها من يكون فى الطريق العام أو أى مكان مطروق أو إذا بيعت أو عرضت للبيع فى أى مكان. ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "172", "chapter": "الباب الرابع عشر", "text": "كل من حرض مباشرة على ارتكاب جنايات القتل أو النهب أو الحرق بواسطة إحدى الطرق المنصوص عليها فى المادة السابقة ولم تترتب على تحريضه أية نتيجة يعاقب بالحبس . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006. ( [1] ) الغى الحبس فى الجرائم التى تقع بواسطة الصحف بالقرار بقانون رقم 85 لسنة 2012 ."}, {"number": "173", "chapter": "الباب الرابع عشر", "text": "ملغاة . ( [1] ) ملغاة بالقانون رقم 112 لسنة 1957."}, {"number": "174", "chapter": "الباب الرابع عشر", "text": "يعاقب بالسجن مدة لا تتجاوز خمس سنوات وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه كل من ارتكب بإحدى الطرق المتقدم ذكرها فعلا من الأفعال الآتية : أولاً : التحريض على قلب نظام الحكم المقرر فى القطر المصرى. ثانياً : ترويج المذاهب التى ترمى إلى تغيير مبادئ الدستور الأساسية أو النظم الأساسية للهيئة الاجتماعية بالقوة أو بالإرهاب. ويعاقب بنفس العقوبات كل من شجع بطريق المساعدة المادية أو المالية على ارتكاب جريمة من الجرائم المنصوص عنها فى الفقرتين السابقتين دون أن يكون قاصدا الاشتراك مباشرة فى ارتكابها . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "175", "chapter": "الباب الرابع عشر", "text": "يعاقب بنفس العقوبات كل من حرض الجند بإحدى الطرق المتقدم ذكرها على الخروج عن الطاعة أو على التحول عن أداء واجباتهم العسكرية ."}, {"number": "176", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس كل من حرض بإحدى الطرق المتقدم ذكرها على التمييز ضد طائفة من طوائف الناس بسبب الجنس أو الأصل أو اللغة أو الدين أو العقيدة إذا كان من شأن هذا التحريض تكدير السلم العام . ( [1] ) مستبدلة بالقانون رقم 147 لسنة 2006."}, {"number": "177", "chapter": "الباب الرابع عشر", "text": "يعاقب بنفس العقوبات كل من حرض غيره بإحدى الطرق المتقدم ذكرها على عدم الانقياد للقوانين . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "178", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تزيد على سنتين وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من نشر أو صنع أو حاز بقصد الاتجار أو التوزيع أو الإيجار أو اللصق أو العرض مطبوعات أو مخطوطات أو رسومات أو إعلانات أو صوراً محفورة أو منقوشة أو رسوماً يدوية أو فوتوغرافية أو إشارات رمزية أو غير ذلك من الأشياء أو الصور عامة إذا كانت خادشة للحياء العام . ( [1] ) مستبدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "178 مكرر", "chapter": "الباب الرابع عشر", "text": "ملغاه ( [1] ) ملغاة بالقانون رقم 147 لسنة 2006 ."}, {"number": "178 مكرر", "chapter": "الباب الرابع عشر", "text": "ثانى) : يعاقب بغرامة لا تقل عن عشرة الآف جنيه ولا تزيد على ثلاثين ألف جنيه كل من نشر أو صنع أو حاز بقصد الاتجار أو التوزيع أو الإيجار أو اللصق أو العرض صورا غير حقيقية من شأنها الإساءة إلى سمعة البلاد. ويعاقب بهذه العقوبة كل من استورد أو صدر أو نقل عمداً بنفسه أو بغيره شـيئا ممـا تقدم للغرض المذكور ، وكل مـن أعلـن عـنه أو عـرضه علـى أنظار الجمهور أو باعه أو أجره أو عرضه للبيع أو الايجار ولو فى غير علانية وكل من قدمه علانية بطريقة مباشرة أو غير مباشرة ولو بالمجان وفى أى صورة من الصور وكل من وزعه أو سلمه للتوزيع بأية وسيلة . ( [1] ) معدلة بالقانون 93 لسنة 1995 وعدلت بالقانون 147 لسنة 2006."}, {"number": "179", "chapter": "الباب الرابع عشر", "text": "يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على ثلاثين ألف جنيه كل من أهان رئيس الجمهورية بإحدى الطرق المتقدم ذكرها. ( [1] ) مستبدلة بالقانون رقم 77 لسنة 2013 ."}, {"number": "180", "chapter": "الباب الرابع عشر", "text": "ملغاة ( [1] ) ملغاة بالقانون رقم 112 لسنة 1957."}, {"number": "181", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس أو بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على عشرين ألف جنيه كل من عاب بإحدى الطرق المتقدم ذكرها فى حق ملك أو رئيس دولة أجنبية . ( [1] ) مستبدلة بالقانون رقم 147 لسنة 2006."}, {"number": "182", "chapter": "الباب الرابع عشر", "text": "يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على عشرين ألف جنيه كل من عاب بإحدى الطرق المتقدم ذكرها فى حق ممثل لدولة أجنبية معتمد فى مصر بسبب أمور تتعلق بأداء وظيفته. ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "183", "chapter": "الباب الرابع عشر", "text": "ملغاة بالقانون رقم 112 لسنة 1957"}, {"number": "184", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من أهان أو سب بإحدى الطرق المتقدم ذكرها مجلس الشعب أو مجلس الشورى أو غيره من الهيئات النظامية أو الجيش أو المحاكم أو السلطات أو المصالح العامة."}, {"number": "185", "chapter": "الباب الرابع عشر", "text": "يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على عشرين ألف جنيه كل من سب موظفاً عاماً أو شخصاً ذا صفة نيابية عامة أو مكلفاً بخدمة عامة بسبب أداء الوظيفة أو النيابة أو الخدمة العامة ، وذلك مع عدم الإخلال بتطبيق الفقرة الثانية من المادة 302 إذا وجد ارتباط بين السب وجريمة قذف ارتكبها ذات المتهم ضد نفس من وقعت عليه جريمة السب. ( [1] ) معدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "186", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تجاوز ستة أشهر وبغرامة لا تقل عن خمسة آلاف جنية ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من أخل بطريقة من الطرق المتقدم ذكرها بمقام قاض أو هيبته أو سلطته فى صدد دعوى ."}, {"number": "187", "chapter": "الباب الرابع عشر", "text": "يعاقب بنفس العقوبات كل من نشر بإحدى الطرق المتقدم ذكرها أموراً من شأنها التأثير فى القضاة الذين يناط بهم الفصل فى دعوى مطروحة أمام أية جهة من جهات القضاء فى البلاد أو رجال القضاء أو النيابة أو غيرهم من الموظفين المكلفين بالتحقيق أو التأثير فى الشهود الذين قد يطلبون لأداء الشهادة فى تلك الدعوى أو فى ذلك التحقيق أو أمورا من شأنها منع شخص من الإفضاء بمعلومات لأولى الأمر أو التأثير فى الرأى العام لمصلحة طرف فى الدعوى أو التحقيق أو ضده ."}, {"number": "188", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرين ألف جنيه أو بإحدى هاتين العقوبتين كل من نشر بسوء قصد بإحدى الطرق المتقدم ذكرها أخباراً أو بيانات أو إشاعات كاذبة أو مغرضة أو دعايات مثيرة أو أوراقاً مصطنعة أو مزورة أو منسوبة كذبا إلى الغير ، إذا كان من شأن ذلك تكدير السلم العام أو إثارة الفـزع بين الناس أو إلحاق الضرر بالمصلحة العامة ."}, {"number": "188 مكرر", "chapter": "الباب الرابع عشر", "text": "ملغاة . ( [1] ) ملغاة بالقانون رقم 40 لسنة 1940"}, {"number": "189", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من نشر بإحدى الطرق المتقدم ذكرها ما جرى فى الدعاوى المدنية أو الجنائية التى قررت المحاكم سماعها فى جلسة سرية . ولا عقاب على مجرد نشر موضوع الشكوى أو على مجرد نشر الحكم ومع ذلك ففى الدعاوى التى لا يجوز فيها إقامة الدليل على الأمور المدعى بها يعاقب على إعلان الشكوى أو على نشر الحكم بالعقوبات المنصوص عليها فى الفقرة الأولى من هذه المادة ما لم يكن نشر الحكم أو الشكوى قد حصل بناء على طلب الشاكى أو بإذنه. ( [1] ) معدلة بالقانون رقم 147 لسنة 2006"}, {"number": "190", "chapter": "الباب الرابع عشر", "text": "فى غير الدعاوى التى تقع فى حكم المادة السابقة يجوز للمحاكم نظرا لنوع وقائع الدعوى أن تحظر فى سبيل المحافظة على النظام العام أو الآداب نشر المرافعات القضائية أو الأحكام كلها أو بعضها بإحدى الطرق المبينة فى المادة 171 ومن يخالف ذلك يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين ."}, {"number": "191", "chapter": "الباب الرابع عشر", "text": "يعاقب بنفس العقوبات كل من نشر بإحدى الطرق المتقدم ذكرها ما جرى فى المداولات السرية بالمحاكم أو نشر بغير أمانة وبسوء قصد ما جرى فى الجلسات العلنية بالمحاكم ."}, {"number": "192", "chapter": "الباب الرابع عشر", "text": "يعاقب بنفس العقوبات كل من نشر بإحدى الطرق المتقدم ذكرها ما جرى من المناقشات فى الجلسات السرية لمجلس الشعب أو نشر بغير أمانة وبسوء قصد ما جرى فى الجلسات العلنية للمجلس المذكور ."}, {"number": "193", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تزيد على ستة شهور وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد عن عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من نشر بإحدى الطرق المتقدم ذكرها : أ - أخباراً بشأن تحقيق جنائى قائم إذا كانت سلطة التحقيق قد قررت إجراءه فى غيبة الخصوم أو كانت قد حظرت إذاعة شىء منه مراعاة للنظام العام أو للآداب أو لظهور الحقيقة . ب - أو أخباراً بشأن التحقيقات أو المرافعات فى دعاوى الطلاق أو التفريق أو الزنا."}, {"number": "194", "chapter": "الباب الرابع عشر", "text": "يعاقب بالحبس مدة لا تجاوز سنة وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين كل من فتح اكتتاباً أو أعلن بإحدى الطرق المتقدم ذكرها بقصد التعويض عن الغرامات أو المصاريف أو التضمينات المحكوم بها قضائيا فى جناية أو جنحة . وكذلك كل من أعلن بإحدى تلك الطرق قيامه أو قيام آخر بالتعويض المشار إليه بعضه أو كله أو عزمه على ذلك ."}, {"number": "195", "chapter": "الباب الرابع عشر", "text": "ملغاة بالقانون رقم 147 لسنة 2006"}, {"number": "196", "chapter": "الباب الرابع عشر", "text": "فى الأحوال التى تكون فيها الكتابة أو الرسم أو الصور أو الصور الشمسية أو الرموز أو طرق التمثيل الأخرى التى استعملت فى ارتكاب الجريمة قد نشرت فى الخارج وفى جميع الأحوال التى لا يمكن فيها معرفة مرتكب الجريمة يعاقب ، بصفتهم فاعلين أصليين ، المستوردين والطابعون فإن تعذر ذلك فالبائعون والموزعون والملصقون وذلك ما لم يظهر من ظروف الدعوى أنه لم يكن فى وسعهم معرفة مشتملات الكتابة أو الرسم أو الصور أو الصور الشمسية أو الرموز أو طرق التمثيل الأخرى ."}, {"number": "197", "chapter": "الباب الرابع عشر", "text": "لا يقبل من أحد للإفلات من المسئولية الجنائية مما نص عليه فى المواد السابقة ، أن يتخذ لنفسه مبرراً أو أن يقيم لها عذرا من أن الكتابات أو الرسوم أو الصور أو الصور الشمسية أو الرموز أو طرق التمثيل الأخرى إنما نقلت أو ترجمت عن نشرات صدرت فى مصر أو فى الخارج أو أنها لم تزد على ترديد إشاعات أو روايات عن الغير ."}, {"number": "198", "chapter": "الباب الرابع عشر", "text": "إذا ارتكبت جريمة بإحدى الطرق المتقدم ذكرها جاز لرجال الضبطية القضائية ضبط كل الكتابات والرسوم والصور والصور الشمسية والرموز وغيرها من طرق التمثيل مما يكون قد أعد للبيع أو التوزيع أو العرض أو يكون قد بيع أو وزع أو عرض فعلاً وكذلك الأصول (الأكليشيهات) والألواح والأحجار وغيرها من أدوات الطبع والنقل . ويجب على من يباشر الضبط أن يبلغ النيابة العمومية فوراً ، فإذا أقرته فعليها أن ترفع الأمر إلى رئيس المحكمة الابتدائية آو من يقوم مقامه فى ظرف ساعتين من وقت الضبط إذا كان المضبوط صحيفة يومية أو أسبوعية. وإذا كانت الصحيفة صباحية وحصل الضبط قبل الساعة السادسة صباحا فيعرض الأمر على رئيس المحكمة فى الساعة الثامنة . وفى باقى الأحوال يكون العرض فى ظرف ثلاثة أيام ويصدر رئيس المحكمة قراره فى الحال بتأييد أمر الضبط أو بإلغائه والإفراج عن الأشياء المضبوطة وذلك بعد سماع أقوال المتهم الذى يجب إعلانه بالحضور ، ولصاحب الشأن أن يرفع الأمر لرئيس المحكمة بعريضة فى نفس هذه المواعيد . ويؤمر فى الحكم الصادر بالعقوبة إذا اقتضى الحال بإزالة الأشياء التى ضبطت أو التى قد تضبط فيما بعد أو إعدامها كلها أو بعضها . وللمحكمة أن تأمر أيضا بنشر الحكم الصادر بالعقوبة فى صحيفة واحدة أو أكثر أو بإلصاقه على الجدران أو بالأمرين معا على نفقة المحكوم عليه . فإذا ارتكبت الجريمة بواسطة جريدة وجب على رئيس تحريرها أو على أى شخص مسئول عن النشر أن ينشر فى صدر صحيفته الحكم الصادر بالعقوبة فى تلك الجريمة فى خلال الشهر التالى لصدور الحكم ما لم تحدد المحكمة ميعادا أقصر من ذلك وإلا حكم عليه بغرامة لا تتجاوز مائة جنيه وبإلغاء الجريدة ."}, {"number": "199", "chapter": "الباب الرابع عشر", "text": "ملغاة. ( [1] ) المواد 199 و 200 ملغاة بالقانون رقم 147 لسنة 2006 ."}, {"number": "200", "chapter": "الباب الرابع عشر", "text": "ملغاه ."}, {"number": "200 مكرر", "chapter": "الباب الرابع عشر", "text": "يعاقب على إصدار الصحف بالمخالفة للأحكام المقررة قانونا بالحبس مدة لا تقل عن ستة أشهر ، وبغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز ثلاثين ألف جنيه أو بإحدى هاتين العقوبتين ، فضلاً عن الحكم بمصادرة ما يصدر من أعداد . ( [1] ) مضافة بالقانون رقم 147 لسنة 2006."}, {"number": "200 مكرر", "chapter": "الباب الرابع عشر", "text": "أ) : يكون الشخص الاعتبارى مسئولاً بالتضامن مع المحكوم عليه من العاملين لديه ، عن الوفاء بما يحكم به من التعويضات فى الجرائم التى ترتكب بواسطة الشخص الاعتبارى من الصحف أو غيرها من طرق النشر ، ويكون مسئولاً بالتضامن عن الوفاء بما يحكم به من عقوبات مالية إذا وقعت الجريمة من رئيس التحرير أو المحرر المسئول . وتكون مسئولية رئيس التحرير أو من يقوم مقامه فى الإشراف على النشر مسئولية شخصية . ويعاقب على أى من الجرائم المشار إليها فى الفقرة السابقة بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرة آلاف جنيه ، وذلك إذا ثبت أن النشر كان نتيجة إخلاله بواجب الإشراف . ( [1] ) مضافة بالقانون رقم 147 لسنة 2006."}, {"number": "201", "chapter": "الباب الرابع عشر", "text": "كل شخص ولو كان من رجال الدين أثناء تأدية وظيفته ألقى فى أحد أماكن العبادة أو فى محفل دينى مقالة تضمنت قدحاً أو ذماً فى الحكومة أو فى قانون أو فى مرسوم أو قرار جمهورى أو فى عمل من أعمال جهات الإدارة العمومية ، أو أذاع أو نشر بصفة نصائح أو تعليمات دينية رسالة مشتملة على شىء من ذلك يعاقب بالحبس وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين . فإذا استعملت القوة أو العنف أو التهديد تكون العقوبة السجن ."}, {"number": "201 مكرر", "chapter": "الباب الرابع عشر", "text": "ملغاة ( [1] ) ملغاة بالقانون رقم 142 لسنة 1952."}, {"number": "202", "chapter": "الباب الخامس عشر", "text": "يعاقب بالسجن المشدد كل من قلد أو زيف أو زور بأية كيفية عملة ورقية أو معدنية متداولة قانونا فى مصر أو فى الخارج . ويعتبر تزييفاً انتقاص شىء من معدن العملة أو طلاؤها بطلاء يجعلها شبيهة بعملة أخرى أكثر منها قيمة ، ويعتبر فى حكم العملة الورقية أوراق البنكنوت المأذون بإصدارها قانوناً . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003."}, {"number": "202 مكرر", "chapter": "الباب الخامس عشر", "text": "يعاقب بالعقوبة المذكورة فى المادة السابقة كل من قلد أو زيف أو زور بأية كيفية عملة وطنية تذكارية ذهبية أو فضية مأذون بإصدارها قانوناً . ويعاقب بذات العقوبة كل من قلد أو زيف أو زور عملة تذكارية أجنبية متى كانت الدولة صاحبة العملة المزيفة تعاقب على تزييف العملة التذكارية المصرية ."}, {"number": "203", "chapter": "الباب الخامس عشر", "text": "يعاقب بالعقوبة المذكورة فى المادة السابقة كل من أدخل بنفسه أو بواسطة غيره فى مصر أو أخرج منها عملة مقلدة أو مزيفة أو مزورة ، وكذلك كل من روجها أو حازها بقصد الترويج أو التعامل بها ."}, {"number": "203 مكرر", "chapter": "الباب الخامس عشر", "text": "إذا ترتب على الجرائم المنصوص عليها فى المادتين السابقتين هبوط سعر العملة المصرية أو سندات الحكومة أو زعزعة الائتمان فى الأسواق الداخلية أو الخارجية جاز الحكم بالسجن المؤبد . ( [1] ) مضافة بالقانون 68 لسنة 1956 ثم عدلت بالقانون 95 لسنة 2003"}, {"number": "204", "chapter": "الباب الخامس عشر", "text": "كل من قبل بحسن نية عملة مقلدة أو مزيفة أو مزورة ثم تعامل بها بعد علمه بعيبها يعاقب بالحبس مدة لا تزيد على ثلاثة أشهر أو بغرامة لا تتجاوز مائتى جنيه."}, {"number": "204 مكرر", "chapter": "الباب الخامس عشر", "text": "أ) : يعاقب بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تتجاوز خمسمائة جنيه كل من صنع أو باع أو وزع أو حاز بقصد البيع أو التوزيع لأغراض ثقافية أو علمية أو صناعية أو تجارية قطعاً معدنية أو أوراقاً مشابهة فى مظهرها للعملة المتداولة فى مصر أو لأوراق البنكنوت المالية التى أذن بإصدارها قانوناً إذا كان من شأن هذه المشابهة إيقاع الجمهور فى الغلط . ويعاقب بنفس العقوبة كل من حاز أو صنع أو صور أو نشر أو استعمل للأغراض المذكورة أو للأغراض الفنية أو لمجرد الهواية صورا تمثل وجها أو جزءا من وجه لعملة ورقية متداولة فى مصر ما لم يصدر له بذلك ترخيص خاص من وزير الداخلية وبالقيود التى يفرضها . ويعتبر من قبيل العملة الورقية فى تطبيق أحكام الفقرتين السابقتين أوراق البنكنوت الأجنبية ."}, {"number": "204 مكرر", "chapter": "الباب الخامس عشر", "text": "ب): يعاقب بالحبس كل من صنع أو حاز بغير مسوغ أدوات أو آلات أو معدات مما يستعمل فى تقليد العملة أو تزييفها أو تزويرها ."}, {"number": "204 مكرر", "chapter": "الباب الخامس عشر", "text": "ج): كل من حبس عن التداول أى عملة من العملات المعدنية المتداولة قانوناً أو صهرها أو باعها أو عرضها للبيع بسعر أعلى من قيمتها الاسمية أو أجرى أى عمل فيها ينزع صفة النقد المقررة يعاقب بالحبس مع الشغل وبغرامة تساوى عشرة أمثال قيمة العملة محل الجريمة وبمصادرة العملة أو المعادن المضبوطة"}, {"number": "205", "chapter": "الباب الخامس عشر", "text": "يعفى من العقوبات المقررة فى المواد 202 ، 202 مكررا ، 203 كل من بادر من الجناة بإخبار الحكومة بتلك الجنايات قبل استعمال العملة المقلدة أو المزيفة أو المزورة وقبل الشروع فى التحقيق . ويجوز للمحكمة إعفاء الجانى من العقوبة إذا حصل الإخبار بعد الشروع فى التحقيق متى مكن السلطات من القبض على غيره من مرتكبى الجريمة أو على مرتكبى جريمة أخرى مماثلة لها فى النوع والخطورة ."}, {"number": "206", "chapter": "الباب السادس عشر", "text": "يعاقب بالسجن المشدد أو السجن كل من قلد أو زور شيئاً من الأشياء الآتية سواء بنفسه أو بواسطة غيره وكذا كل من استعمل هذه الأشياء أو أدخلها فى البلاد المصرية مع علمه بتقليدها أو تزويرها وهذه الأشياء هى : - أمر جمهورى أو قانون أو مرسوم أو قرار صادر من الحكومة . - خاتم الدولة أو إمضاء رئيس الجمهورية أو ختمه . - أختام أو تمغات أو علامات إحدى المصالح أو إحدى جهات الحكومة - ختم أو إمضاء أو علامة أحد موظفى الحكومة . - أوراق مرتبات أو بونات أو سراكى أو سندات أخرى صادرة من خزينة الحكومة أو فروعها . - تمغات الذهب أو الفضة ."}, {"number": "206 مكرر", "chapter": "الباب السادس عشر", "text": "يعاقب بالسجن مدة لا تزيد على خمس سنين على الجرائم الواردة فى المادة السابقة إذا كان محلها أختاما أو دمغات أو علامات لإحدى الشركات المساهمة أو إحدى الجمعيات التعاونية أو النقابات المنشأة طبقاً للأوضاع المقررة قانونا أو إحدى المؤسسات أو الجمعيات المعتبرة قانوناً ذات نفع عام . وتكون العقوبة السجن مدة لا تزيد على سبع سنين إذا كانت الأختام أو التمغات أو العلامات التى وقعت بشأنها الجرائم المبينة فى الفقرة السابقة خاصة بمؤسسة أو شركة أو جمعية أو منظمة أو منشأة إذا كانت الدولة أو إحدى الهيئات العامة تساهم فى مالها بنصيب ما بأية صفة كانت ."}, {"number": "207", "chapter": "الباب السادس عشر", "text": "يعاقب بالحبس كل من استحصل بغير حق على أختام أو تمغات أو علامات حقيقية لإحدى المصالح الحكومية أو إحدى جهات الإدارة العمومية أو إحدى الهيئات المبينة فى المادة السابقة واستعملها استعمالا ضارا بمصلحة عامة أو خاصة ."}, {"number": "208", "chapter": "الباب السادس عشر", "text": "يعاقب بالحبس كل من قلد ختماً أو تمغة أو علامة لإحدى الجهات أيا كانت أو الشركات المأذونة من قبل الحكومة أو أحد البيوت التجارية وكذا من استعمل شيئا من الأشياء المذكورة مع علمه بتقليدها ."}, {"number": "209", "chapter": "الباب السادس عشر", "text": "كل من استحصل بغير حق على الأختام أو التمغات أو النياشين الحقيقية المعدة لأحد الأنواع السالف ذكرها واستعملها استعمالا مضرا بأى مصلحة عمومية أو شركة تجارية أو أى إدارة من إدارات الأهالى يعاقب بالحبس مدة لا تزيد على سنتين."}, {"number": "210", "chapter": "الباب السادس عشر", "text": "الأشخاص المرتكبون لجنايات التزوير المذكورة بالمواد السابقة يعفون من العقوبة إذا أخبروا الحكومة بهذه الجنايات قبل تمامها وقبل الشروع فى البحث عنهم وعرفوها بفاعليها الآخرين أو سهلوا القبض عليهم ولو بعد الشروع فى البحث المذكور."}, {"number": "211", "chapter": "الباب السادس عشر", "text": "كل صاحب وظيفة عمومية ارتكب فى أثناء تأدية وظيفته تزويراً فى أحكام صادرة أو تقارير أو محاضر أو وثائق أو سجلات أو دفاتر أو غيرها من السندات والأوراق الأميرية سواء كان ذلك بوضع إمضاءات أو أختام مزورة أو بتغيير المحررات أو الأختام أو الإمضاءات أو بزيادة كلمات أو بوضع أسماء أو صور أشخاص آخرين مزورة يعاقب بالسجن المشدد أو السجن."}, {"number": "212", "chapter": "الباب السادس عشر", "text": "كل شخص ليس من أرباب الوظائف العمومية ارتكب تزويراً مما هو مبين فى المادة السابقة يعاقب بالسجن المشدد أو بالسجن مدة أكثرها عشر سنين ."}, {"number": "213", "chapter": "الباب السادس عشر", "text": "يعاقب أيضا بالسجن المشدد أو بالسجن كل موظف فى مصلحة عمومية أو محكمة غير بقصد التزوير موضوع السندات أو أحوالها فى حال تحريرها المختص بوظيفته سواء كان ذلك بتغيير إقرار أولى الشأن الذى كان الغرض من تحرير تلك السندات إدراجه بها أو بجعله واقعة مزورة فى صورة واقعة صحيحة مع علمه بتزويرها أو بجعله واقعة غير معترف بها فى صورة واقعة معترف بها ."}, {"number": "214", "chapter": "الباب السادس عشر", "text": "من استعمل الأوراق المزورة المذكورة فى المواد الثلاث السابقة وهو يعلم بتزويرها يعاقب بالسجن المشدد أو بالسجن من ثلاث سنين إلى عشر ."}, {"number": "214 مكرر", "chapter": "الباب السادس عشر", "text": "كل تزوير أو استعمال يقع فى محرر لإحدى الشركات المساهمة أو إحدى الجمعيات التعاونية أو النقابات المنشأة طبقاً للأوضاع المقررة قانوناً أو إحدى المؤسسات أو الجمعيات المعتبرة قانوناً ذات نفع عام تكون عقوبته السجن مدة لا تزيد على خمس سنين . وتكون العقوبة السجن مدة لا تزيد على عشر سنين إذا وقع التزوير أو الاستعمال فى محرر لإحدى الشركات أو الجمعيات المنصوص عليها فى الفقرة السابقة أو لأية مؤسسة أو منظمة أو منشأة أخرى إذا كان للدولة أو لإحدى الهيئات العامة نصيب فى مالها بأية صفة كانت."}, {"number": "215", "chapter": "الباب السادس عشر", "text": "كل شخص ارتكب تزويراً فى محررات أحد الناس بواسطة إحدى الطرق السابق بيانها أو استعمل ورقة مزورة وهو عالم بتزويرها يعاقب بالحبس مع الشغل ."}, {"number": "216", "chapter": "الباب السادس عشر", "text": "كل من تسمى فى تذكرة سفر أو فى تذكرة مرور باسم غير اسمه الحقيقى أو كفل أحداً فى استحصاله على الورقة المشتملة على الاسم المذكور وهو يعلم ذلك يعاقب بالحبس مدة لا تزيد على سنتين. وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى من الجرائم المنصوص عليها فى المادة 216 تنفيذا لغرض إرهابى ."}, {"number": "217", "chapter": "الباب السادس عشر", "text": "كل من صنع تذكرة مرور أو تذكرة سفر مزورة أو زور فى ورقة من هذا القبيل كانت صحيحة فى الأصل أو استعمل إحدى الأوراق المذكورة مع علمه بتزويرها يعاقب بالحبس . وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذاً لغرض إرهابى ."}, {"number": "218", "chapter": "الباب السادس عشر", "text": "كل من استعمل تذكرة مرور أو تذكرة سفر ليست له يعاقب بالحبس مدة لا تتجاوز ستة شهور أو بغرامة لا تزيد على مائتى جنيه مصريا. وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذا لغرض إرهابى ."}, {"number": "219", "chapter": "الباب السادس عشر", "text": "كل صاحب لوكاندة أو قهوة أو دار أو محلات مفروشة معدة للإيجار وكذلك كل صاحب خان أو غيره ممن يسكنون الناس بالأجرة يوميا قيد فى دفاتره الأشخاص الساكنين عنده بأسماء مزورة وهو يعلم ذلك يعاقب بالحبس مدة لا تزيد على ثلاثة شهور أو بغرامة لا تتجاوز مائتى جنيه مصريا . وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذا لغرض إرهابى."}, {"number": "220", "chapter": "الباب السادس عشر", "text": "كل موظف عمومى أعطى تذكرة سفر أو تذكرة مرور باسم مزور مع علمه بالتزوير يعاقب بالحبس مدة لا تزيد على سنتين أو بغرامة لا تتجاوز خمسمائة جنيه فضلاً عن عزله. وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذا لغرض إرهابى ."}, {"number": "221", "chapter": "الباب السادس عشر", "text": "كل شخص صنع بنفسه أو بواسطة شخص آخر شهادة مزورة على ثبوت عاهة لنفسه أو لغيره باسم طبيب أو جراح بقصد أن يخلص نفسه أو غيره من أى خدمة عمومية يعاقب بالحبس ."}, {"number": "222", "chapter": "الباب السادس عشر", "text": "كل طبيب أو جراح أو قابلة أعطى بطريق المجاملة شهادة أو بيانا مزورا بشأن حمل أو مرض أو عاهة أو وفاة مع علمه بتزوير ذلك يعاقب بالحبس أو بغرامة لا تتجاوز خمسمائة جنيه مصرى فإذا طلب لنفسه أو لغيره أو قبل أو أخذ وعداً أو عطية للقيام بشىء من ذلك أو وقع منه الفعل نتيجة لرجاء أو توصية أو وساطة يعاقب بالعقوبات المقررة فى باب الرشوة . ويعاقب الراشى والوسيط بالعقوبة المقررة للمرتشى أيضاً."}, {"number": "223", "chapter": "الباب السادس عشر", "text": "العقوبات المبينة بالمادتين السابقتين يحكم بها أيضا إذا كانت تلك الشهادة معدة لأن تقدم إلى المحاكم ."}, {"number": "224", "chapter": "الباب السادس عشر", "text": "لا تسرى أحكام المواد 211 ، 212 ، 213 ، 214، 215 على أحوال التزوير المنصوص عليها فى المواد 216 ، 217، 218 ، 219 ، 220 ، 221 ، 222 ولا على أحوال التزوير المنصوص عليها فى قوانين عقوبات خاصة."}, {"number": "225", "chapter": "الباب السادس عشر", "text": "تعتبر بصمة الإصبع كالإمضاء فى تطبيق أحكام هذا الباب ."}, {"number": "226", "chapter": "الباب السادس عشر", "text": "يعاقب بالحبس مدة لا تتجاوز سنتين أو بغرامة لا تزيد على خمسمائة جنيه كل من قرر فى إجراءات تتعلق بتحقيق الوفاة والوراثة والوصية الواجبة أمام السلطة المختصة بأخذ الإعلام أقوالا غير صحيحة عن الوقائع المرغوب إثباتها وهو يجهل حقيقتها أو يعلم أنها غير صحيحة وذلك متى ضبط الإعلام على أساس هذه الأقوال . ويعاقب بالحبس مدة لا تتجاوز سنتين أو بغرامة لا تزيد على خمسمائة جنيه كل من استعمل إعلاما بتحقيق الوفاة والوراثة والوصية الواجبة ضبط على الوجه المبين فى الفقرة الأولى من هذه المادة وهو عالم بذلك ."}, {"number": "227", "chapter": "الباب السادس عشر", "text": "يعاقب بالحبس مدة لا تتجاوز سنتين أو بغرامة لا تزيد على ثلاثـمائة جنيه كل من أبدى أمام السلطة المختصة بقصد إثبات بلوغ أحد الزوجين السن المحددة قانوناً لضبط عقد الزواج أقوالا يعلم أنها غير صحيحة أو حرر أو قدم لها أوراقاً كذلك متى ضبط عقد الزواج على أساس هذه الأقوال أو الأوراق . ويعاقب بالحبس أو بغرامة لا تزيد على خمسمائة جنيه كل شخص خوله القانون سلطة ضبط عقد الزواج وهو يعلم أن أحد طرفيه لم يبلغ السن المحددة فى القانون."}, {"number": "228", "chapter": "الباب السابع عشر", "text": "يعاقب بالحبس مدة لا تتجاوز ستة أشهر وبغرامة لا تزيد على خمسمائة جنيه أو بإحدى هاتين العقوبتين فقط : كل من أدخل فى بلاد مصر بضائع ممنوع دخولها فيها أو نقل هذه البضائع أو حملها فى الطرق لبيعها أو عرضها للبيع أو أخفاها أو شرع فى ذلك ما لم ينص قانوناً على عقوبة أخرى."}, {"number": "229", "chapter": "الباب السابع عشر", "text": "يعاقب بالعقوبات المدونة فى المادة السابقة من صنع أو حمل فى الطريق للبيع أو وزع أو عرض للبيع مطبوعات أو نموذجات مهما كانت طريقة صنعها تشابه بهيئتها الظاهرة علامات وطوابع مصلحتى البوستة والتلغرافات المصرية أو مصالح البوستة والتلغرافات فى البلاد الداخلة فى اتحاد البريد مشابهة يسهل قبولها بدلا من الأوراق المقلدة . ويعتبر فى حكم علامات وطوابع مصلحة البريد قسائم المجاوبة الدولية البريدية . ويعاقب بنفس العقوبة من استعمل طوابع البريد المقلدة ولو كانت غير متداولة أو التى سبق استعمالها مع علمه بذلك ويسرى هذا الحكم على قسائم المجاوبة الدولية المقلدة."}, {"number": "229 مكرر", "chapter": "الباب السابع عشر", "text": "كل من طبع أو نشر أو باع أو عرض للبيع كتاباً أو مصنفاً يحتوى على كل أو بعض المناهج التعليمية المقررة فى المدارس التى تديرها أو تشرف عليها وزارة التعليم أو إحدى هيئات الإدارة المحلية قبل الحصول على ترخيص بذلك من الجهة المختصة يعاقب بغرامة لا تتجاوز خمسمائة جنيه وبمصادرة الكتاب أو المصنف ."}, {"number": "230", "chapter": "الكتاب الثالث", "text": "كل من قتل نفساً عمداً مع سبق الإصرار على ذلك أو الترصد يعاقب بالإعدام ."}, {"number": "231", "chapter": "الكتاب الثالث", "text": "الإصرار السابق هو القصد المصمم عليه قبل الفعل لارتكاب جنحة أو جناية يكون غرض المصر منها إيذاء شخص معين أو أى شخص غير معين وجده أو صادفه سواء كان ذلك القصد معلقاً على حدوث أمر أو موقوفاً على شرط ."}, {"number": "232", "chapter": "الكتاب الثالث", "text": "الترصد هو تربص الإنسان لشخص فى جهة أو جهات كثيرة مدة من الزمن طويلة كانت أو قصيرة ليتوصل إلى قتل ذلك الشخص أو إلى إيذائه بالضرب ونحوه ."}, {"number": "233", "chapter": "الكتاب الثالث", "text": "من قتل أحداً عمداً بجواهر يتسبب عنها الموت عاجلاً أو آجلاً يعد قاتلاً بالسم أيا كانت كيفية استعمال تلك الجواهر ويعاقب بالإعدام."}, {"number": "234", "chapter": "الكتاب الثالث", "text": "من قتل نفساً عمداً من غير سبق إصرار ولا ترصد يعاقب بالسجن المؤبد أو المشدد . ومع ذلك يحكم على فاعل هذه الجناية بالإعدام إذا تقدمتها أو اقترنت بها أو تلتها جناية أخرى . وأما إذا كان القصد منها التأهب لفعل جنحة أو تسهيلها أو ارتكابها بالفعل أو مساعدة مرتكبيها أو شركائهم على الهرب أو التخلص من العقوبة فيحكم بالإعدام أو بالسجن المؤبد . وتكون العقوبة الإعدام إذا ارتكبت الجريمة تنفيذا لغرض إرهابى."}, {"number": "235", "chapter": "الكتاب الثالث", "text": "المشاركون فى القتل الذى يستوجب الحكم على فاعله بالإعدام يعاقبون بالإعدام أو بالسجن المؤبد ."}, {"number": "236", "chapter": "الكتاب الثالث", "text": "كل من جرح أو ضرب أحداً عمداً أو أعطاه مواد ضارة ولم يقصد من ذلك قتلا ولكنه أفضى إلى الموت يعاقب بالسجن المشدد أو السجن من ثلاث سنوات إلى سبع. وأما إذا سبق ذلك إصرار أو ترصد فتكون العقوبة السجن المشدد أو السجن. وتكون العقوبة السجن المشدد أو السجن إذا ارتكبت الجريمة تنفيذا لغرض إرهابى ، فإذا كانت مسبوقة بإصرار أو ترصد تكون العقوبة السجن المؤبد أو المشدد."}, {"number": "237", "chapter": "الكتاب الثالث", "text": "من فاجأ زوجته حال تلبسها بالزنا وقتلها فى الحال هى ومن يزنى بها يعاقب بالحبس بدلا من العقوبات المقررة فى المادتين 234 و 236 ."}, {"number": "238", "chapter": "الكتاب الثالث", "text": "من تسبب خطأ فى موت شخص آخر بأن كان ذلك ناشئ عن إهماله أو رعونته أو عدم احترازه أو عدم مراعاته للقوانين والقرارات واللوائح والأنظمة يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تجاوز مائتى جنيه أو بإحدى هاتين العقوبتين . وتكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على خمس سنين وغرامة لا تقل عن مائة ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين إذا وقعت الجريمة نتيجة إخلال الجانى إخلالاً جسيما بما تفرضه عليه أصول وظيفته أو مهنته أو حرفته أو كان متعاطياً مسكراً أو مخدراً عند ارتكابه الخطأ الذى نـجم عنه الحادث أو نكل وقت الحادث عن مساعدة من وقعت عليه الجريمة أو عن طلب المساعدة له مع تمكنه من ذلك . وتكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على سبع سنين إذا نشأ عن الفعل وفاة أكثر من ثلاثة أشخاص ، فإذا توافر ظرف آخر من الظروف الواردة فى الفقرة السابقة كانت العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على عشر سنين."}, {"number": "239", "chapter": "الكتاب الثالث", "text": "كل من أخفى جثة قتيل أو دفنها بدون إخبار جهات الاقتضاء وقبل الكشف عليها وتحقيق حالة الموت وأسبابه يعاقب بالحبس مدة لا تزيد على سنة ."}, {"number": "240", "chapter": "الكتاب الثالث", "text": "كل من أحدث بغيره جرحاً أو ضرباً نشأ عنه قطع أو انفصال عضو فقد منفعته أو نشأ عنه كف البصر أو فقد إحدى العينين أو نشأت عنه أى عاهة مستديمة يستحيل برؤها يعاقب بالسجن من ثلاث سنين إلى خمس سنين . أما إذا كان الضرب أو الجرح صادراً عن سبق إصرار أو ترصد أو تربص فيحكم بالسجن المشدد من ثلاث سنين إلى عشر سنين ويضاعف الحد الأقصى للعقوبة إذا ارتكبت الجريمة تنفيذا لغرض إرهابى. ( [1] ) معدلة بالقانون رقم 95 لسنة 2003 . ( [1] ) الفقرة الاخيرة ملغاه بالقانون رقم 5 لسنة 2010 ."}, {"number": "241", "chapter": "الكتاب الثالث", "text": "كل من أحدث بغيره جرحاً أو ضرباً نشأ عنه مرض أو عجز عن الأشغال الشخصية مدة تزيد على عشرين يوماً يعاقب بالحبس مدة لا تزيد عن سنتين أو بغرامة لا تقل عن عشرين جنيها مصريا ولا تجاوز ثلاثـمائة جنيه مصرى. أما إذا صدر الضرب أو الجرح عن سبق إصرار أو ترصد أو حصل باستعمال أية أسلحة أو عصى أو آلات أو أدوات أخرى فتكون العقوبة الحبس ، وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذاً لغرض إرهابى."}, {"number": "242", "chapter": "الكتاب الثالث", "text": "إذا لم يبلغ الضرب أو الجرح درجة الجسامة المنصوص عليها فى المادتين السابقتين يعاقب فاعله بالحبس مدة لا تزيد على سنة أو بغرامة لا تقل عن عشرة جنيهات ولا تجاوز مائتى جنيه مصريا. فإن كان صادراً عن سبق إصرار أو ترصد تكون العقوبة الحبس مدة لا تزيد على سنتين أو غرامة لا تقل عن عشرة جنيهات ولا تجاوز ثلاثـمائة جنيه مصرى . وإذا حصل الضرب أو الجرح باستعمال أية أسلحة أو عصى أو آلات أو أدوات أخرى تكون العقوبة الحبس . وتكون العقوبة السجن الذى لا تزيد مدته على خمس سنوات إذا ارتكبت أى منها تنفيذا لغرض إرهابى ."}, {"number": "242 مكرر", "chapter": "الكتاب الثالث", "text": "يُعاقب بالسجن مدة لا تقل عن خمس سنوات كل من أجرى ختانًا لأنثى بإزالة أى جزء من أعضائها التناسلية الخارجية بشكل جزئى أو تام أو ألحق إصابات بتـلك الأعضاء ، فإذا نشأ عن ذلك الفعل عاهة مستديمة تكون العقوبة السجن المشدد مدة لا تقل عن سبع سنوات ، أما إذا أفضى الفعل إلى الموت تكون العقوبة السجن المشدد لمدة لا تقل عن عشر سنوات. وتكون العقوبة السجن المشدد لمدة لا تقل عن خمس سنوات إذا كان من أجرى الختان المشار إليه بالفقرة السابقة طبيبًا أو مزاولاً لمهنة التمريض ، فإذا نشأ عن جريمته عاهة مستديمة تكون العقوبة السجن المشدد لمدة لا تقل عن عشر سنوات ، أما إذا أفضى الفعل إلى الموت تكون العقوبة السجن المشدد لمدة لا تقل عن خمس عشرة سنة ولا تزيد على عشرين سنة . وتقضى المحكمة فضلاً عن العقوبات المتقدمة بحرمان مرتكبها ، من الأطباء ومزاولى مهنة التمريض ، من ممارسة المهنة مدة لا تقل عن ثلاث سنوات ولا تزيد على خمس سنوات تبدأ بعد انتهاء مدة تنفيذ العقوبة ، وغلق المنشأة الخاصة التى أجرى فيها الختان ، وإذا كانت مرخصة تكون مدة الغلق مساوية لمدة المنع من ممارسة المهنة مع نزع لوحاتها ولافتاتها ، سواء أكانت مملوكة للطبيب مرتكب الجريمة ، أم كان مديرها الفعلى عالمًا بارتكابها ، وذلك بما لا يخل بحقوق الغير حسن النية ، ونشر الحكم فى جريدتين يوميتين واسعتى الانتشار وبالمواقع الإلكترونية التى يُعينها الحكم عل نفقة المحكوم عليه . ( [1] ) مضافة بقانون 126 لسنة 2008 واستبدلت بقانون 10 لسنة2021"}, {"number": "242 مكرر", "chapter": "الكتاب الثالث", "text": "أ) : يُعاقب بالسجن كل من طلب ختان أنثى وتم ختانها بناءً على طلبه على النحو المنصوص عليه بالمادة (242) مكررًا من هذا القانون . كما يُعاقب بالحبس كل من روج ، أو شجع ، أو دعا بإحدى الطرق المبينة بالمادة ( 171 ) من هذا القانون لارتكاب جريمة ختان أنثى ولو لم يترتب على فعله أثر . ( [1] ) مضافة بالقانون رقم 78 لسنة 2016 واستبدلت بالقانون رقم 10 لسنة 2021 ."}, {"number": "243", "chapter": "الكتاب الثالث", "text": "إذا حصل الضرب أو الجرح المذكوران في مادتي 241 و242 بواسطة استعمال أسلحة أو عصي أو آلات أخرى من واحد أو أكثر ضمن عصبة أو تجمهر مؤلف من خمسة أشخاص على الأقل توافقوا على التعدي والإيذاء فتكون العقوبة الحبس."}, {"number": "243 مكرر", "chapter": "الكتاب الثالث", "text": "يكون الحد الأدنى للعقوبات فى الجرائم المنصوص عليها فى المواد الثلاث السابقة خمسة عشر يوما بالنسبة إلى عقوبة الحبس وعشرة جنيهات بالنسبة إلى عقوبة الغرامة إذا كان المجنى عليه فيها عاملاً بالسكك الحديدية أو غيرها من وسائل النقل العام ووقع عليه الاعتداء وقت أداء عمله أثناء سيرها أو توقفها بالمحطات ."}, {"number": "244", "chapter": "الكتاب الثالث", "text": "من تسبب خطأ فى جرح شخص أو إيذائه بأن كان ذلك ناشئاً عن إهماله أو رعونته أو عدم احترازه أو عدم مراعاته للقوانين والقرارات واللوائح والأنظمة يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تجاوز مائتى جنيه أو بإحدى هاتين العقوبتين . وتكون العقوبة الحبس مدة لا تزيد على سنتين وغرامة لا تجاوز ثلاثـمائة جنيه أو إحدى هاتين العقوبتين إذا نشأ عن الإصابة عاهة مستديمة أو إذا وقعت الجريمة نتيجة إخلال الجانى إخلالا جسيما بما تفرضه عليه أصول وظيفته أو مهنته أو حرفته أو كان متعاطياً مسكراً أو مخدراً عند ارتكابه الخطأ الذى نـجم عنه الحادث أو نكل وقت الحادث عن مساعدة من وقعت عليه الجريمة أو عن طلب المساعدة له مع تمكنه من ذلك . وتكون العقوبة الحبس إذا نشأ عن الجريمة إصابة أكثر من ثلاثة أشخاص ، فإذا توافر ظرف آخر من الظروف الواردة فى الفقرة السابقة تكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على خمس سنين ."}, {"number": "245", "chapter": "الكتاب الثالث", "text": "لا عقوبة مطلقاً على من قتل غيره أو أصابه بجراح أو ضربه أثناء استعماله حق الدفاع الشرعى عن نفسه أو ماله أو عن نفس غيره أو ماله وقد بينت فى المواد الآتية الظروف التى ينشأ عنها هذا الحق والقيود التى يرتبط بها ."}, {"number": "246", "chapter": "الكتاب الثالث", "text": "حق الدفاع الشرعى عن النفس يبيح للشخص إلا فى الأحوال الاستثنائية المبينة بعد استعمال القوة اللازمة لدفع كل فعل يعتبر جريمة على النفس منصوصاً عليها فى هذا القانون. وحق الدفاع الشرعى عن المال يبيح استعمال القوة لرد أى فعل يعتبر جريمة من الجرائم المنصوص عليها فى الأبواب الثانى والثامن والثالث عشر والرابع عشر من هذا الكتاب وفى الفقرة 4 من المادة 279 ."}, {"number": "247", "chapter": "الكتاب الثالث", "text": "وليس لهذا الحق وجود متى كان من الممكن الركون فى الوقت المناسب إلى الاحتماء برجال السلطة العمومية ."}, {"number": "248", "chapter": "الكتاب الثالث", "text": "لا يبيح حق الدفاع الشرعى مقاومة أحد مأمورى الضبط أثناء قيامه بأمر بناء على واجبات وظيفته مع حسن النية ولو تخطى هذا المأمور حدود وظيفته إلا إذا خِيف أن ينشأ عن أفعاله موت أو جروح بالغة وكان لهذا الخوف سبب معقول ."}, {"number": "249", "chapter": "الكتاب الثالث", "text": "حق الدفاع الشرعى عن النفس لا يجوز أن يبيح القتل العمد إلا إذا كان مقصوداً به دفع أحد الأمور الآتية : أولاً : فعل يتخوف أن يحدث منه الموت أو جراح بالغة إذا كان لهذا التخوف أسباب معقولة . ثانياً : إتيان امرأة كرها أو هتك عرض إنسان بالقوة . ثالثاً : اختطاف إنسان ."}, {"number": "250", "chapter": "الكتاب الثالث", "text": "حق الدفاع الشرعى عن المال لا يجوز أن يبيح القتل العمد إلا إذا كان مقصودا به دفع أحد الأمور الآتية : أولاً : فعل من الأفعال المبينة فى الباب الثانى من هذا الكتاب. ثانياً : سرقة من السرقات المعدودة من الجنايات . ثالثاً : الدخول ليلاً فى منزل مسكون أو فى أحد ملحقاته . رابعاً : فعل يتخوف أن يحدث منه الموت أو جراح بالغة إذا كان لهذا التخوف أسباب معقولة ."}, {"number": "251", "chapter": "الكتاب الثالث", "text": "لا يعفى من العقاب بالكلية من تعدى بنية سليمة حدود حق الدفاع الشرعى أثناء استعماله إياه دون أن يكون قاصداً إحداث ضرر أشد مما يستلزمه هذا الدفاع . ومع ذلك يجوز للقاضى إذا كان الفعل جناية أن يعده معذوراً إذا رأى لذلك محلاً وأن يحكم عليه بالحبس بدلا من العقوبة المقررة فى القانون ."}, {"number": "251 مكرر", "chapter": "الكتاب الثالث", "text": "إذا ارتكبت الجرائم المنصوص عليها فى هذا الفصل أثناء الحرب على الجرحى حتى من الأعداء فيعاقب مرتكبها بنفس العقوبات المقررة لما يرتكب من هذه الجرائم بسبق الإصرار والترصد ."}, {"number": "252", "chapter": "الباب الثانى", "text": "كل من وضع عمداً نارا فى مبان كائنة فى المدن أو الضواحى أو القرى أو فى عمارات كائنة خارج سور ما ذكر أو فى سفن أو مراكب أو معامل أو مخازن وعلى وجه العموم فى أى محل مسكون أو معد للسكنى سواء كان ذلك مملوكا لفاعل الجناية أم لا يعاقب بالسجن المؤبد أو المشدد. ويحكم أيضا بهذه العقوبة على من وضع عمداً نارا فى عربات السكك الحديدية سواء كانت محتوية على أشخاص أو من ضمن قطار محتوى على ذلك ."}, {"number": "252 مكرر", "chapter": "الباب الثانى", "text": "كل من وضع النار عمدا فى إحدى وسائل الإنتاج أو فى أموال ثابتة أو منقولة لإحدى الجهات المنصوص عليها فى المادة 119 بقصد الإضرار بالاقتصاد القومى يعاقب بالسجن المؤبد أو المشدد . وتكون العقوبة السجن المؤبد إذا ترتب على الجريمة إلحاق ضرر جسيم بمركز البلاد الاقتصادى أو بمصلحة قومية لها أو إذا ارتكبت فى زمن حرب . ويحكم على الجانى فى جميع الأحوال بدفع قيمة الأشياء التى أحرقها. ويجوز أن يعفى من العقوبة كل من بادر من الشركاء من غير المحرضين على ارتكاب الجريمة بإبلاغ السلطات القضائية أو الإدارية بالجريمة بعد تمامها وقبل صدور الحكم النهائى فيها."}, {"number": "253", "chapter": "الباب الثانى", "text": "كل من وضع ناراً عمداً فى مبان أو سفن أو مراكب أو معامل أو مخازن ليست مسكونة ولا معدة للسكنى أو فى معاصر أو سواق أو آلات رى أو فى غابات أو أجمات أو فى مزارع غير محصودة يعاقب بالسجن المشدد إذا كانت تلك الأشياء ليست مملوكة له ."}, {"number": "254", "chapter": "الباب الثانى", "text": "من أحدث حال وضع النار فى إحدى الأشياء المذكورة فى المادة السابقة ضرراً لغيره يعاقب بالسجن المشدد أو السجن إذا كانت تلك الأشياء مملوكة له أو فعل بها ذلك بأمر مالكها ."}, {"number": "255", "chapter": "الباب الثانى", "text": "من وضع ناراً عمداً فى أخشاب معدة للبناء أو للوقود أو فى زرع محصود أو فى أكوام من قش أو تبن أو فى مواد أخرى قابلة للاحتراق سواء كانت لا تزال بالغيط أو نقلت إلى الجرن أو فى عربات السكك الحديدية سواء كانت مشحونة بالبضائع أو لا ولم تكن من ضمن قطار محتوى على أشخاص يعاقب بالسجن المشدد إذا لم تكن هذه الأشياء ملكاً له . أما إذا أحدث عمداً حال وضعه النار فى إحدى الأشياء المذكورة أى ضرر لغيره وكانت تلك الأشياء مملوكة له أو فعل ذلك بأمر مالكها يعاقب بالسجن المشدد أو السجن ."}, {"number": "256", "chapter": "الباب الثانى", "text": "وكذلك يعاقب بهذه العقوبة بحسب الأحوال المتنوعة المبينة فى المواد السابقة كل من وضع النار فى أشياء لتوصيلها للشىء المراد إحراقه بدلا من وضعها مباشرة فى ذلك ."}, {"number": "257", "chapter": "الباب الثانى", "text": "وفى جميع الأحوال المذكورة إذا نشأ عن الحريق السالف ذكره موت شخص أو أكثر كان موجوداً فى الأماكن المحرقة وقت اشتعال النار يعاقب فاعل هذا الحريق عمدا بالإعدام ."}, {"number": "258", "chapter": "الباب الثانى", "text": "ملغاة بالقانون رقم 50 لسنة 1949"}, {"number": "259", "chapter": "الباب الثانى", "text": "فى الأحوال المنصوص عليها فى الفقرة الأولى من المادة 255 إذا لم تستعمل مفرقعات ولم تتجاوز قيمة الأشياء المحرقة خمسة جنيهات مصرية ولم يكن هناك خطر على الأشخاص أو خطر من إلحاق ضرر بأشياء أخرى تكون العقوبة الحبس ."}, {"number": "260", "chapter": "الباب الثالث", "text": "كل من أسقط عمدا امرأة حبلى بضرب أو نحوه من أنواع الإيذاء يعاقب بالسجن المشدد . ( [1] ) معدلة بالقانون رقم 95 لسنة 2003 ."}, {"number": "261", "chapter": "الباب الثالث", "text": "كل من أسقط عمدا امرأة حبلى بإعطائها أدوية أو باستعمال وسائل مؤدية إلى ذلك أو بدلالتها عليها سواء كان برضائها أم لا يعاقب بالحبس."}, {"number": "262", "chapter": "الباب الثالث", "text": "المرأة التى رضيت بتعاطى الأدوية مع علمها بها أو رضيت باستعمال الوسائل السالف ذكرها أو مكنت غيرها من استعمال تلك الوسائل لها وتسبب الإسقاط عن ذلك حقيقة تعاقب بالعقوبة السابق ذكرها ."}, {"number": "263", "chapter": "الباب الثالث", "text": "إذا كان المسقط طبيباً أو جراحاً أو صيدلياً أو قابلة يحكم عليه بالسجن المشدد ."}, {"number": "264", "chapter": "الباب الثالث", "text": "لا عقاب على الشروع فى الإسقاط ."}, {"number": "265", "chapter": "الباب الثالث", "text": "كل من أعطى عمداً لشخص جواهر غير قاتلة فنشأ عنها مرض أو عجز وقتى عن العمل يعاقب طبقاً لأحكام المواد 240 و 241 و 242 على حسب جسامة ما نشأ عن الجريمة ووجود سبق الإصرار على ارتكابها أو عدم وجوده ."}, {"number": "266", "chapter": "الباب الثالث", "text": "ملغاة بالقانون رقم 48 لسنة 1941"}, {"number": "267", "chapter": "الباب الرابع", "text": "من واقع أنثى بغير رضاها يعاقب بالإعدام أو السجن المؤبد . ويعاقب الفاعل بالإعدام إذا كانت المجنى عليها لم يبلغ سنها ثـمانى عشرة سنة ميلادية كاملة أو كان الفاعل من أصول المجنى عليها أو من المتولين تربيتها أو ملاحظتها أو ممن لهم سلطة عليها أو كان خادماً بالأجر عندها أو عند من تقدم ذكرهم ، أو تعدد الفاعلون للجريمة . ( [1] ) مستبدلة بالمرسوم بقانون رقم 11 لسنة 2011 ."}, {"number": "268", "chapter": "الباب الرابع", "text": "كل من هتك عرض إنسان بالقوة أو بالتهديد أو شرع فى ذلك يعاقب بالسجن المشدد . وإذا كان عمر من وقعت عليه الجريمة المذكورة لم يبلغ ثـمانى عشرة سنة ميلادية كاملة أو كان مرتكبها أو أحد مرتكبيها ممن نص عليهم فى الفقرة الثانية من المادة ( 267 ) تكون العقوبة السجن المشدد مدة لا تقل عن سبع سنوات ، وإذا اجتمع هذان الظرفان معاً يحكم بالسجن المؤبد . ( [1] ) مستبدلة بالمرسوم بقانون رقم 11 لسنة 2011 ."}, {"number": "269", "chapter": "الباب الرابع", "text": "كل من هتك عرض صبى أو صبية لم يبلغ سن كل منهما ثـمانى عشرة ميلادية كاملة بغير قوة أو تهديد يعاقب بالسجن ، وإذا كان سنه لم يجاوز إثنتى عشرة سنة ميلادية كاملة أو كان من وقعت منه الجريمة ممن نص عليهم فى الفقرة الثانية من المادة ( 267 ) تكون العقوبة السجن المشدد مدة لا تقل عن سبع سنوات . ( [1] ) مستبدلة بالمرسوم بقانون رقم 11 لسنة 2011 ."}, {"number": "269 مكرر", "chapter": "الباب الرابع", "text": "يعاقب بالحبس مدة لا تقل عن ثلاثة أشهر كل من وُجد فى طريق عام أو مكان مطروق يحرض المارة على الفسق بإشارات أو أقوال . فإذا عاد الجانى إلى ارتكاب هذه الجريمة خلال سنة من تاريخ الحكم عليه نهائياً فى الجريمة الأولى تكون العقوبة الحبس مدة لا تقل عن سنة وغرامة لا تقل عن خمسمائة جنيه ولا تزيد على ثلاثة آلاف جنيه ، ويستتبع الحكم بالإدانة وضع المحكوم عليه تحت مراقبة الشرطة مدة مساوية لمدة العقوبة . ( [1] ) مستبدلة بالمرسوم بقانون رقم 11 لسنة 2011 ."}, {"number": "270", "chapter": "الباب الرابع", "text": "ملغاة بالقانون رقم 68 لسنة 1951"}, {"number": "271", "chapter": "الباب الرابع", "text": "ملغاة بالقانون رقم 68 لسنة 1951"}, {"number": "272", "chapter": "الباب الرابع", "text": "ملغاة بالقانون رقم 68 لسنة 1951"}, {"number": "273", "chapter": "الباب الرابع", "text": "لا تجوز محاكمة الزانية إلا بناء على دعوى زوجها إلا أنه إذا زنى الزوج فى المسكن المقيم فيه مع زوجته كالمبين فى المادة 277 لا تسمع دعواه عليها ."}, {"number": "274", "chapter": "الباب الرابع", "text": "المرأة المتزوجة التى ثبت زناها يحكم عليها بالحبس مدة لا تزيد على سنتين لكن لزوجها أن يوقف تنفيذ هذا الحكم برضائه معاشرتها له كما كانت ."}, {"number": "275", "chapter": "الباب الرابع", "text": "ويعاقب أيضا الزانى بتلك المرأة بنفس العقوبة."}, {"number": "276", "chapter": "الباب الرابع", "text": "الأدلة التى تقبل وتكون حجة على المتهم بالزنا هى القبض عليه حين تلبسه بالفعل أو اعترافه أو وجود مكاتيب أو أوراق أخرى مكتوبة منه أو وجوده فى منزل مسلم فى المحل المخصص للحريم"}, {"number": "277", "chapter": "الباب الرابع", "text": "كل زوج زنى فى منزل الزوجية وثبت عليه هذا الأمر بدعوى الزوجة يجازى بالحبس مدة لا تزيد على ستة شهور ."}, {"number": "278", "chapter": "الباب الرابع", "text": "كل من فعل علانية فعلاً فاضحاً مخلاً بالحياء يعاقب بالحبس مدة لا تزيد على سنة أو بغرامة لا تتجـاوز ثلاثـمائة جنيه مصريا ."}, {"number": "279", "chapter": "الباب الرابع", "text": "يعاقب بالعقوبة السابقة كل من ارتكب مع امرأة أمراً مخلاً بالحياء ولو فى غير علانية . البـاب الخامـس القبض على الناس وحبسهم بدون وجه حق وسرقة الأطفال وخطف البنات"}, {"number": "280", "chapter": "الباب الرابع", "text": "كل من قبض على أى شخص أو حبسه أو حجزه بدون أمر أحد الحكام المختصين بذلك وفى غير الأحوال التى تصرح فيها القوانين واللوائح بالقبض على ذوى الشبهة يعاقب بالحبس أو بغرامة لا تتجاوز مائتى جنيه مصريا."}, {"number": "281", "chapter": "الباب الرابع", "text": "يعاقب أيضا بالحبس مدة لا تزيد على سنتين كل شخص أعار محلاً للحبس أو الحجز غير الجائزين مع علمه بذلك."}, {"number": "282", "chapter": "الباب الرابع", "text": "إذا حصل القبض فى الحالة المبينة بالمادة 280 من شخص تزيا بدون وجه حق بزى مستخدمى الحكومة أو اتصف بصفة كاذبة أو أبرز أمراً مزوراً مدعياً صدوره من طرف الحكومة يعاقب بالسجن ، ويحكم فى جميع الأحوال بالسجن المشدد على من قبض على شخص بدون وجه حق وهدده بالقتل أو عذبه بالتعذيبات البدنية ."}, {"number": "283", "chapter": "الباب الرابع", "text": "يٌعاقب بالسجن مدة لا تقل عن سبع سنوات كل من خطف طفلا ً حديث العهد بالولادة أو أخفاه أو أبدله بآخر أو عزاه زوراً إلى غير أي من والديه. ( [1] ) المادة مستبدلة بالقانون رقم 5 لسنة 2018."}, {"number": "284", "chapter": "الباب الرابع", "text": "يعاقب بالحبس أو بغرامة لا تزيد على خمسمائة جنيه كل من كان متكفلا بطفل وطلبه منه من له حق فى طلبه ولم يسلمه إليه ."}, {"number": "285", "chapter": "الباب الرابع", "text": "كل من عرض للخطر طفلا لم يبلغ سنه سبع سنين كاملة وتركه فى محل خال من الآدميين أو حمل غيره على ذلك يعاقب بالحبس مدة لا تزيد على سنتين ."}, {"number": "286", "chapter": "الباب الرابع", "text": "إذا نشأ عن تعريض الطفل للخطر وتركه فى المحل الخالى كالمبين فى المادة السابقة انفصال عضو من أعضائه أو فقد منفعته فيعاقب الفاعل بالعقوبات المقررة للجرح عمداً فإن تسبب عن ذلك موت الطفل يحكم بالعقوبة المقررة للقتل عمداً ."}, {"number": "287", "chapter": "الباب الرابع", "text": "كل من عرض للخطر طفلاً لم يبلغ سنه سبع سنين كاملة وتركه فى محل معمور بالآدميين سواء كان ذلك بنفسه أو بواسطة غيره يعاقب بالحبس مدة لا تزيد على ستة شهور أو بغرامة لا تتجاوز مائتى جنيه مصريا."}, {"number": "288", "chapter": "الباب الرابع", "text": "المادة ملغاة ملغاة بالقانون رقم 5 لسنة 2018"}, {"number": "289", "chapter": "الباب الرابع", "text": "كل من خطف من غير تحيل ولا إكراه طفلاً يعاقب بالسجن المشدد مدة لا تقل عن عشر سنوات. فإذا كان الخطف مصحوباً بطلب فدية فتكون العقوبة السجن المشدد لمدة لا تقل عن خمس عشرة سنة ولا تزيد على عشرين سنة . ويُحكم على فاعل جناية الخطف بالإعدام أو السجن المؤبد إذا اقترنت بها جريمة مواقعة المخطوف أو هتك عرضة. ( [1] ) مستبدلة بالقانون رقم 5 لسنة 2018."}, {"number": "290", "chapter": "الباب الرابع", "text": "كل من خطف بالتحيل أو الإكراه شخصاً يعاقب بالسجن المشدد مدة لا تقل عن عشر سنين. فإذا كان الخطف مصحوباً بطلب فدية تكون العقوبة السجن المشدد لمدة لا تقل عن خمس عشرة سنة ولا تزيد على عشرين سنة. أما إذا كان المخطوف طفلاً أو أنثى فتكون العقوبة السجن المؤبد. ويٌحكم على فاعل جناية الخطف بالإعدام إذا اقترنت بها جناية مواقعة المخطوف أو هتك عرضه. ( [1] ) مستبدلة بالقانون رقم 5 لسنة 2018."}, {"number": "291", "chapter": "الباب الرابع", "text": "يحظر كل مساس بحق الطفل فى الحماية من الاتجار به أو الاستغلال الجنسى أو التجارى أو الاقتصادى ، أو استخدامه فى الأبحاث والتجارب العلمية ويكون للطفل الحق فى توعيته وتمكينه من مجابهة هذه المخاطر . ومع عدم الإخلال بأية عقوبة أشد ينص عليها فى قانون آخر ، يعاقب بالسجن المشدد مدة لا تقل عن خمس سنوات وبغرامة لا تقل عن خمسين ألف جنيه ولا تجاوز مائتى ألف جنيه كل من باع طفلاً أو اشتراه أو عرضه للبيع ، وكذلك من سلمه أو تسلمه أو نقله باعتباره رقيقا ، أو استغله جنسياً أو تجاريا ، أو استخدمه فى العمل القسرى ، أو فى غير ذلك من الأغراض غير المشروعة ، ولو وقعت الجريمة فى الخارج . ويعاقب بذات العقوبة من سهل فعلا من الأفعال المذكورة فى الفقرة السابقة أو حرض عليه ولو لم تقع الجريمة بناء على ذلك . ومع عدم الإخلال بأحكام المادة ( 116 مكرراً) من قانون الطفل ، تضاعف العقوبة إذا ارتكبت من قبل جماعة إجرامية منظمة عبر الحدود الوطنية. ومع مراعاة حكم المادة ( 116 مكرراً) من القانون المشار إليه، يعاقب بالسجن المشدد كل من نقل من طفل عضوا من أعضاء جسده أو جزءا منه ، ولا يعتد بموافقة الطفل أو المسئول عنه . ( [1] ) معدلة بالقانون رقم 126 لسنة 2008 ."}, {"number": "292", "chapter": "الباب الرابع", "text": "يعاقب بالحبس مدة لا تتجاوز سنة أو بغرامة لا تزيد على خمسمائة جنيه مصرياً أى الوالدين أو الجدين لم يسلم ولده الصغير أو ولد ولده إلى من له الحق فى طلبه بناء على قرار من جهة القضاء صادر بشأن حضانته أو حفظه . وكذلك أى الوالدين أو الجدين خطفه بنفسه أو بواسطة غيره ممن لهم بمقتضى قرار من جهة القضاء حق حضانته أو حفظه ولو كان ذلك بغير تحايل أو إكراه ."}, {"number": "293", "chapter": "الباب الرابع", "text": "كل من صدر عليه حكم قضائى واجب النفاذ بدفع نفقة لزوجه أو أقاربه أو أصهاره أو أجرة حضانة أو رضاعة أو مسكن وامتنع عن الدفع من قدرته عليه لمدة ثلاثة أشهر بعد التنبيه عليه بالدفع، يعاقب بالحبس مدة لا تزيد على سنة وبغرامة لا تتجاوز خمسة آلاف جنيه أو بإحدى هاتين العقوبتين. ولا ترفع الدعوى عليه إلا بناءً على شكوى أو طلب من صاحب الشأن. وإذا رفعت بعد الحكم عليه دعوى ثانية عن هذه الجريمة فتكون عقوبته الحبس مدة لا تزيد على سنة. ويترتب على الحكم الصادر بالإدانة تعليق استفادة المحكوم عليه من الخدمات المطلوب الحصول عليها بمناسبة ممارسته نشاط المهنى والتى تقدمها الجهات الحكومية، والهيئات العامة، ووحدات القطاع العام وقطاع الأعمال العام، والجهات التى تؤدى خدمات مرافق عامة، حتى أدائه ما تجمد فى ذمته لصالح المحكوم له وبنك ناصر الاجتماعى حسب الأحوال. وللمجنى عليه أو وكيلة الخاص ولورثته أو وكيلهم الخاص وكذا بنك ناصر الاجتماعى أن يطلب من النيابة العامة أو المحكمة المختصة، بحسب الأحوال وفى أى حالة كانت عليها الدعوى، إثبات تصالحه مع المتهم. ويترتب على التصالح انقضاء الدعوى الجنائية وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا تم التصالح أثناء تنفيذها ولو بعد صيرورة الحكم باتًا، ولا يرتب الصلح أثره إذا تبين أن المحكوم لصالحه قد تقاضى من بنك ناصر الاجتماعى كل أو بعض ما حكم به لصالحه، ما لم يقدم المتهم أو المحكوم عليه شهادة بتصالحه مع البنك عما قام بأدائه من نفقات وأجور وما فى حكمها وجميع ما تكبده من مصاريف فعلية أنفقها بسبب امتناع المحكوم عليه عن أدائها. وفى جميع الأحوال، إذا أدى المحكوم عليه ما تجمد فى ذمته أو قدم كفيلاً يقبله صاحب الشأن فلا تنفذ العقوبة. ويصدر بتحديد تلك الخدمات وقواعد وإجراءات تعليقها وإنهائها قرار من وزير العدل بالاتفاق مع الوزراء المختصين. ( [1] ) مستبدلة بالقانون 6 لسنة 2020"}, {"number": "294", "chapter": "الباب السادس", "text": "كل من شهد زورا لمتهم فى جناية أو عليه يعاقب بالحبس ."}, {"number": "295", "chapter": "الباب السادس", "text": "ومع ذلك إذا ترتب على هذه الشهادة الحكم على المتهم يعاقب من شهد عليه زورا بالسجن المشدد أو السجن، أما إذا كانت العقوبة المحكوم بها على المتهم هى الإعدام ونفذت عليه يحكم بالإعدام أيضا على من شهد عليه زوراً ."}, {"number": "296", "chapter": "الباب السادس", "text": "كل من شهد زوراً على متهم بجنحة أو مخالفة أو شهد له زوراً يعاقب بالحبس مدة لا تزيد على سنتين ."}, {"number": "297", "chapter": "الباب السادس", "text": "كل من شهد زورا فى دعوى مدنية يعاقب بالحبس مدة لا تزيد على سنتين ."}, {"number": "298", "chapter": "الباب السادس", "text": "إذا قبل من شهد زورا فى دعوى جنائية أو مدنية عطية أو وعدا بشىء مما يحكم عليه هو والمعطى أو من وعده بالعقوبات المقررة للرشوة أو للشهادة الزور إن كانت هذه أشد من عقوبات الرشوة . وإذا كان الشاهد طبيباً أو جراحاً أو قابله وطلب لنفسه أو لغيره أو قبل أو أخذ وعداً أو عطية لأداء الشهادة زوراً بشأن حمل أو مرض أو عاهة أو وفاة أو وقعت منه الشهادة بذلك نتيجة لرجاء أو توصية أو وساطة يعاقب بالعقوبات المقررة فى باب الرشوة أو فى باب شهادة الزور أيهما أشد ، ويعاقب الراشى والوسيط بالعقوبة المقررة للمرتشى أيضا."}, {"number": "299", "chapter": "الباب السادس", "text": "يعاقب بالعقوبات المقررة لشهادة الزور كل شخص كلف من سلطة قضائية بعمل الخبرة أو الترجمة فى دعوى مدنية أو تجارية أو جنائية فغير الحقيقة عمدا بأى طريقة كانت ."}, {"number": "300", "chapter": "الباب السادس", "text": "من أكره شاهداً على عدم أداء الشهادة أو على الشهادة زوراً يعاقب بمثل عقوبة شاهد الزور مع مراعاة الأحوال المقررة فى المواد السابقة."}, {"number": "301", "chapter": "الباب السادس", "text": "من ألزم باليمين أو ردت عليه فى مواد مدنية وحلف كاذباً يحكم عليه بالحبس ، ويجوز أن تزاد عليه غرامة لا تتجاوز مائة جنيه مصرى ."}, {"number": "302", "chapter": "الباب السابع", "text": "يعد قاذفا كل من أسند لغيره بواسطة إحدى الطرق المبينة بالمادة 171 من هذا القانون أموراً لو كانت صادقة لأوجبت عقاب من أسندت إليه بالعقوبات المقررة لذلك قانونا أو أوجبت احتقاره عند أهل وطنه . ومع ذلك فالطعن فى أعمال موظف عام أو شخص ذى صفة نيابية عامة أو مكلف بخدمة عامة لا يدخل تحت حكم الفقرة السابقة إذا حصل بسلامة نية وكان لا يتعدى أعمال الوظيفة أو النيابة أو الخدمة العامة ، وبشرط أن يثبت المتهم حقيقة كل فعل أسنده إلى المجنى عليه ، ولسلطة التحقيق أو المحكمة ، بحسب الأحوال ، أن تأمر بإلزام الجهات الإدارية بتقديم ما لديها من أوراق أو مستندات معززة لما يقدمه المتهم من أدلة لإثبات حقيقة تلك الأفعال . ولا يقبل من القاذف إقامة الدليل لإثبات ما قذف به إلا فى الحالة المبينة بالفقرة السابقة . ( [1] ) مستبدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "303", "chapter": "الباب السابع", "text": "يعاقب على القذف بغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على خمسة عشرة ألف جنيه . فإذا وقع القذف فى حق موظف عام أو شخص ذى صفة نيابة عامة أو مكلف بخدمة عامة ، وكان ذلك بسبب أداء الوظيفة أو النيابة أو الخدمة العامة ، كانت العقوبة غرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على عشرين ألف جنيه. ( [1] ) معدلة بالقانون رقم 147 لسنة 2006 ."}, {"number": "304", "chapter": "الباب السابع", "text": "لا يحكم بهذا العقاب على من أخبر بالصدق وعدم سوء القصد الحكام القضائيين أو الإداريين بأمر مستوجب لعقوبة فاعله ."}, {"number": "305", "chapter": "الباب السابع", "text": "وأما من أخبر بأمر كاذب مع سوء القصد فيستحق العقوبة ولو لم يحصل منه إشاعة غير الأخبار المذكورة ولم تقم دعوى بما أخبر به ."}, {"number": "306", "chapter": "الباب السابع", "text": "كل سب لا يشتمل على إسناد واقعة معينة بل يتضمن بأى وجه من الوجوه خدشا للشرف أو الاعتبار يعاقب عليه فى الأحوال المبينة بالمادة 171 بغرامة لا تقل عن ألفى جنيه ولا تزيد عن عشرة آلاف جنيه . ( [1] ) معدلة بالقانون رقم 147 لسنة 2006."}, {"number": "306 مكرر", "chapter": "الباب السابع", "text": "أ) : يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن ثلاثة آلاف جنيه ولا تزيد على خمسة آلاف جنيه أو بإحدى هاتين العقوبتين كل من تعرض للغير في مكان عام أو خاص أو مطروق بإتيان أمور أو إيحاءات أو تلميحات جنسية أو إباحية سواء بالإشارة أو بالقول أو بالفعل بأية وسيلة بما في ذلك وسائل الاتصالات السلكية أو اللاسلكية. وتكون العقوبة الحبس مدة لا تقل عن سنة وبغرامة لا تقل عن خمسة آلاف جنيه ولا تزيد على عشرة آلاف جنيه أو بإحدى هاتين العقوبتين إذا تكرر الفعل من الجاني من خلال الملاحقة والتتبع للمجني عليه. وفي حالة العود تضاعف عقوبتا الحبس والغرامة في حديهما الأدنى والأقصى. ( ( [1] مستبدلة بقانون رقم 50 لسنة 2014"}, {"number": "306 مكرر", "chapter": "الباب السابع", "text": "ب) : يُعد تحرشا جنسيا إذا ارتكبت الجريمة المنصوص عليها في المادة 306 مكرراً (أ) من هذا القانون بقصد حصول الجاني من المجني عليه على منفعة ذات طبيعة جنسية ، ويعاقب الجاني بالحبس مدة لا تقل عن سنة وبغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على عشرين ألف جنيه أو بإحدى هاتين العقوبتين. فإذا كان الجاني ممن نص عليهم في الفقرة الثانية من المادة ( 267 ) من هذا القانون أو كانت له سلطة وظيفية أو أسرية أو دراسية على المجني عليه أو مارس عليه أي ضغط تسمح له الظروف بممارسته عليه أو ارتكبت الجريمة من شخصين فأكثر أو كان أحدهم على الأقل يحمل سلاحاً تكون العقوبة الحبس مدة لا تقل عن سنتين ولا تجاوز خمس سنين والغرامة التي لا تقل عن عشرين ألف جنيه ولا تزيد على خمسين ألف جنيه. ( ( [1] مستبدلة بقانون رقم 50 لسنة 2014"}, {"number": "307", "chapter": "الباب السابع", "text": "إذا ارتكبت جريمة من الجرائم المنصوص عليها فى المواد من 182 إلى 185 و 303 و 306 بطريق النشر فى إحدى الجرائد أو المطبوعات رفعت الحدود الدنيا والقصوى لعقوبة الغرامة المبينة فى المواد المذكورة إلى ضعفيها ."}, {"number": "308", "chapter": "الباب السابع", "text": "إذا تضمن العيب أو الإهانة أو القذف أو السب الذى ارتكب بإحدى الطرق المبينة فى المادة 171 طعنا فى عرض الأفراد أو خدشا لسمعة العائلات ، تكون العقوبة الحبس والغرامة معا فى الحدود المبينة فى المواد 179 و181 و182 و303 و306 و307 على ألا تقل الغرامة فى حالة النشر فى إحدى الجرائد أو المطبوعات عن نصف الحد الأقصى وألا يقل الحبس عن ستة شهور ."}, {"number": "308 مكرر", "chapter": "الباب السابع", "text": "كل من قذف غيره بطريق التليفون يعاقب بالعقوبات المنصوص عليها فى المادة 302 . وكل من وجه إلى غيره بالطريق المشار إليه بالفقرة السابقة سبا لا يشتمل على إسناد واقعة معينة بل يتضمن بأى وجه من الوجوه خدشا للشرف أو الاعتبار يعاقب بالعقوبة المنصوص عليها فى المادة 306 . وإذا تضمن العيب أو القذف أو السب الذى ارتكب بالطريق المبين بالفقرتين السابقتين طعنا فى عرض الإفراد أو خدشا لسمعة العائلات يعاقب بالعقوبة المنصوص عليها فى المادة 308 ."}, {"number": "309", "chapter": "الباب السابع", "text": "لا تسرى أحكام المواد 302 و303 و305 و306 و 308 على ما يسنده أحد الأخصام لخصمه فى الدفاع الشفوى أو الكتابى أمام المحاكم فإن ذلك لا يترتب عليه إلا المقاضاة المدنية أو المحاكمة التأديـبيـة ."}, {"number": "309 مكرر", "chapter": "الباب السابع", "text": "يعاقب بالحبس مدة لا تزيد على سنة كل من اعتدى على حرمة الحياة الخاصة للمواطن ، وذلك بأن ارتكب أحد الأفعال الآتية فى غير الأحوال المصرح بها قانوناً أو بغير رضاء المجنى عليه : أ - استرق السمع أو سجل أو نقل عن طريق جهاز من الأجهزة أيا كان نوعه محادثات جرت فى مكان خاص أو عن طريق التليفون . ب - التقط أو نقل بجهاز من الأجهزة أيا كان نوعه صورة شخص فى مكان خاص. فإذا صدرت الأفعال المشار إليها فى الفقرتين السابقتين أثناء اجتماع على مسمع أو مرأى من الحاضرين فى ذلك الاجتماع فإن رضاء هؤلاء يكون مفترضا . ويعاقب بالحبس الموظف العام الذى يرتكب أحد الأفعال المبينة بهذه المادة اعتمادا على سلطة وظيفته . ويحكم فى جميع الأحوال بمصادرة الأجهزة وغيرها مما يكون قد استخدم فى الجريمة ، كما يحكم بمحو التسجيلات المتحصلة عنها أو إعدامها ."}, {"number": "309 مكرر", "chapter": "الباب السابع", "text": "أ) : يعاقب بالحبس كل من أذاع أو سهل إذاعة أو استعمل ولو فى غير علانية تسجيلاً أو مستنداً متحصلاً عليه بإحدى الطرق المبينة بالمادة السابقة أو كان ذلك بغير رضاء صاحب الشأن . ويعاقب بالسجن مدة لا تزيد على خمس سنوات كل من هدد بإفشاء أمر من الأمور التى تم التحصل عليها بإحدى الطرق المشار إليها لحمل شخص على القيام بعمل أو الامتناع عنه . ويعاقب بالسجن الموظف العام الذى يرتكب أحد الأفعال المبينة بهذه المادة اعتماداً على سلطة وظيفته . ويحكم فى جميع الأحوال بمصادرة الأجهزة وغيرها مما يكون قد استخدم فى الجريمة أو تحصل عنها كما يحكم بمحو التسجيلات المتحصلة عن الجريمة أو إعدامها ."}, {"number": "309 مكرر", "chapter": "الباب السابع", "text": "ب) : يعد تنمراً كل قول أو استعراض قوة أو سيطرة للجاني أو استغلال ضعف للمجني عليه أو لحالة يعتقد الجاني أنها تسئ للمجني عليه كالجنس أو العرق أو الدين أو الأوصاف البدنية أو الحالة الصحية أو العقلية أو المستوى الاجتماعي بقصد تخويفه أو وضعه موضع السخرية أو الحط من شأنه أو إقصائه من محيطه الإجتماعي. ومع عدم الإخلال بأي عقوبة أشد منصوص عليها في أي قانون آخر يعاقب المتنمر بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن عشرة آلاف جنيه ولا تزيد على ثلاثين ألف جنيه أو بإحدى هاتين العقوبتين. وتكون العقوبة الحبس مدة لا تقل عن سنة وبغرامة لا تقل عن عشرين ألف جنيه ولا تزيد على مائة ألف جنيه أو بإحدى هاتين العقوبتين إذا وقعت الجريمة من شخصين أو أكثر أو كان الجاني من أصول المجني عليه أو من المتولين تربيته أو ملاحظته أو ممن لهم سلطة عليه أو كان مسلماً إليه بمقتضى القانون أو بموجب حكم قضائي أو كان خادماً لدى الجاني أما إذا اجتمع الظرفان يُضاعف الحد الأدنى للعقوبة. وفي حالة العود تُضاعف العقوبة في حديها الأدنى والأقصى. ( [1] ) مضافة بالقانون 189 لسنة 2020"}, {"number": "310", "chapter": "الباب السابع", "text": "كل من كان من الأطباء أو الجراحين أو الصيادلة أو القوابل أو غيرهم مودعا إليه بمقتضى صناعته أو وظيفته سر خصوصى أؤتمن عليه فأفشاه فى غير الأحوال التى يلزمه القانون فيها بتبليغ ذلك يعاقب بالحبس مدة لا تزيد على ستة شهور أو بغرامة لا تتجاوز خمسمائة جنيه مصريا . ولا تسرى أحكام هذه المادة إلا فى الأحوال التى لم يرخص فيها قانون بإفشاء أمور معينة كالمقرر فى المواد 202 و 203 و 204 و 205 من قانون المرافعات فى المواد المدنية والتجارية."}, {"number": "311", "chapter": "الباب الثامن", "text": "كل من اختلس منقولا مملوكا لغيره فهو سارق ."}, {"number": "312", "chapter": "الباب الثامن", "text": "لا تجوز محاكمة من يرتكب سرقة إضرارا بزوجه أو زوجته أو أصوله أو فروعه إلا بناء على طلب المجنى عليه ، وللمجنى عليه أن يتنازل عن دعواه بذلك فى أية حالة كانت عليها ، كما له أن يقف تنفيذ الحكم النهائى على الجانى فى أى وقت شاء ."}, {"number": "313", "chapter": "الباب الثامن", "text": "يعاقب بالسجن المؤبد من وقعت منه سرقة مع اجتماع الخمسة شروط الآتية : الأول : أن تكون هذه السرقة حصلت ليلا . الثانى : أن تكون السرقة واقعة من شخصين فأكثر . الثالث : أن يوجد مع السارقين أو مع واحد منهم أسلحة ظاهرة أو مخبأة . الرابع : أن يكون السارقون قد دخلوا داراً أو منزلا أو أودة أو ملحقاتها مسكونة أو معدة للسكنى بواسطة تسور جدار أو كسر باب ونحوه أو استعمال مفاتيح مصطنعة أو بواسطة التزيى بزى أحد الضباط أو موظف عمومى أو بإبراز أمر مزور مدعى صدوره من طرف الحكومة . الخامس : أن يفعلوا الجناية المذكورة بطريقة الإكراه أو التهديد باستعمال أسلحتهم ."}, {"number": "314", "chapter": "الباب الثامن", "text": "يعاقب بالسجن المشدد من ارتكب سرقة بإكراه فإذا ترك الإكراه أثر جروح تكون العقوبة السجن المؤبد أو المشدد ."}, {"number": "315", "chapter": "الباب الثامن", "text": "يعاقب بالسجن المؤبد أو المشدد على السرقات التى ترتكب فى الطرق العامة سواء كانت داخل المدن أو القرى أو خارجها أو فى إحدى وسائل النقل البرية أو المائية أو الجوية فى الأحوال الآتية : أولاً : إذا وقعت السرقة من شخصين فأكثر وكان أحدهم على الأقل حاملاً سلاحاً ظاهراً أو مخبأ . ثانياً : إذا وقعت السرقة من شخصين فأكثر بطريق الإكراه . ثالثاً : إذا وقعت السرقة ولو من شخص واحد يحمل سلاحا وكان ذلك ليلاً أو بطريق الإكراه أو التهديد باستعمال السلاح."}, {"number": "316", "chapter": "الباب الثامن", "text": "يعاقب بالسجن المشدد على السرقات التى تحصل ليلاً من شخصين فأكثر يكون أحدهم على الأقل حاملا سلاحا ظاهرا أو مخبأ ."}, {"number": "316 مكرر", "chapter": "الباب الثامن", "text": "يعاقب بالسجن المشدد على السرقات التى تقع على أسلحة الجيش أو ذخيرته وتكون العقوبة السجن المؤبد إذا ارتكبت الجريمة بطريق الإكراه أو التهديد باستعمال السلاح أو إذا توافر فيها ظرف من الظروف المشددة المنصوص عليها فى المادة 317 . ( [1] ) مضافة بالقانون 424 لسنة 1954 وعدلت بالقانون 95 لسنة 2003"}, {"number": "316 مكرر", "chapter": "الباب الثامن", "text": "ثانياً) (أ) : يعاقب بالسجن على السرقات التى تقع على المهمات أو الأدوات المستعملة أو المعدة للاستعمال فى مرافق توليد أو توصيل التيار الكهربائى أو المياه أو الصرف الصحى التى تنشئها الحكومة أو الهيئات أو المؤسسات العامة أو وحدات القطاع العام ، أو المرخص فى إنشائها لمنفعة عامة وذلك إذا لم يتوافر فى الجريمة ظرف من الظروف المشددة المنصوص عليها فى المواد من 313 إلى 316 . ( [1] ) مستبدلة بالقانون رقم 124 لسنة 2009 ."}, {"number": "316 مكرر", "chapter": "الباب الثامن", "text": "ثانياً) (ب) : يعاقب بالسجن المشدد وبغرامة لا تقل عن مائة ألف جنية ولا تجاوز مليون جنية كل من سرق شيئاً من المهمات أو المكونات أو الكابلات أو الأجهزة أو المعدات المستعملة أو المعدة للاستعمال فى شبكات الاتصالات المرخص بها أو فى بنيتها الأساسية أو فى خط من خطوط الاتصالات . ويعاقب بالسجن وبغرامة لا تقل عن خمسين ألف جنية ولا تجاوز خمسمائة ألف جنية كل من أخفى أو تعامل فى الأشياء المتحصلة من السرقة المنصوص عليها فى الفقرة الأولى من هذه المادة . ( [1] ) مضافة بالقانون رقم 124 لسنة 2009 ."}, {"number": "316 مكرر", "chapter": "الباب الثامن", "text": "ثالثاً) : يعاقب بالحبس مدة لا تقل عن ستة أشهر ولا تجاوز سبع سنوات : أولا : على السرقات التى ترتكب فى إحدى وسائل النقل البرية أو المائية أو الجوية. ثانيا : على السرقات التى تحصل فى مكان مسكون أو معد للسكنى أو أحد ملحقاته إذا تم دخول المكان بواسطة التسور أو الكسر أو استعمال مفاتيح مصطنعة أو انتحال صفة كاذبة أو ادعاء القيام أو التكليف بخدمة عامة أو غير ذلك من الوسائل غير المشروعة . ثالثا : على السرقات التى تقع ولو من شخص واحد يحمل سلاحا ظاهرا أو مخبأ ."}, {"number": "316 مكرر", "chapter": "الباب الثامن", "text": "رابعاً) : يعاقب بالسجن على السرقات التى تقع أثناء الغارات الجوية . وتكون العقوبة السجن المشدد إذا توافر فى الجريمة ظرف من الظروف المشددة المنصوص عليها فى المادة 317 فإذا ارتكبت الجريمة بطريق الإكراه أو التهديد باستعمال سلاح تكون العقوبة السجن المؤبد ."}, {"number": "317", "chapter": "الباب الثامن", "text": "يعاقب بالحبس مع الشغل : أولاً : على السرقات التى تحصل فى مكان مسكون أو معد للسكنى أو فى ملحقاته أو فى أحد المحلات المعدة للعبادة . ثانياً : على السرقات التى تحصل فى مكان مسور بحائط أو بسياج من شجر أخضر أو حطب يابس أو بخنادق ، ويكون ذلك بواسطة كسر من الخارج أو تسور أو باستعمال مفاتيح مصطنعة. ثالثاً : على السرقات التى تحصل بكسر الأختام المنصوص عليها فى الباب التاسع من الكتاب الثانى . رابعاً : على السرقات التى تحصل ليلا. خامساً : على السرقات التى تحصل من شخصين فأكثر . سادساً : ملغاة بالقانون رقم 59 لسنة 1970 سابعاً : على السرقات التى تحصل من الخدم بالأجرة إضرارا بمخدوميهم أو من المستخدمين أو الصناع أو الصبيان فى معامل أو حوانيت من استخدموهم أو فى المحلات التى يشتغلون فيها عادة . ثامنا : على السرقات التى تحصل من المحترفين بنقل الأشياء فى العربات أو المراكب أو على دواب الحمل أو أى إنسان آخر مكلف بنقل أشياء أو أحد أتباعهم إذا سلمت إليهم الأشياء المذكورة بصفتهم السابقة . تاسعا: على السرقات التى ترتكب أثناء الحرب على الجرحى حتى من الأعداء ."}, {"number": "318", "chapter": "الباب الثامن", "text": "يعاقب بالحبس مع الشغل مدة لا تتجاوز سنتين على السرقات التى لم يتوافر فيها شىء من الظروف المشددة السابق ذكرها ."}, {"number": "319", "chapter": "الباب الثامن", "text": "ملغاة بالقانون رقم 29 لسنة 1982"}, {"number": "320", "chapter": "الباب الثامن", "text": "المحكوم عليهم بالحبس لسرقة يجوز فى حالة العود أن يجعلوا تحت مراقبة البوليس مدة سنة على الأقل أو سنتين على الأكثر ."}, {"number": "321", "chapter": "الباب الثامن", "text": "يعاقب على الشروع فى السرقات المعدودة من الجنح بالحبس مع الشغل مدة لا تتجاوز نصف الحد الأقصى المقرر فى القانون للجريمة لو تمت فعلا."}, {"number": "321 مكرر", "chapter": "الباب الثامن", "text": "كل من عثر على شىء أو حيوان فاقد ولم يرده إلى صاحبه متى تيسر ذلك أو لم يسلمه إلى مقر الشرطة أو جهة الإدارة خلال ثلاثة أيام يعاقب بالحبس مع الشغل مدة لا تجاوز سنتين إذا احتبسه بنية تملكه . أما إذا احتبسه بعد انقضاء تلك الفترة بغير نية التملك فتكون العقوبة الغرامة التى لا تجاوز مائة جنيه ."}, {"number": "322", "chapter": "الباب الثامن", "text": "ملغاة . ( [1] ) ملغاة بالقانون رقم 63 لسنة 1947 ."}, {"number": "323", "chapter": "الباب الثامن", "text": "اختلاس الأشياء المحجوز عليها قضائيا أو إداريا يعتبر فى حكم السرقة ولو كان حاصلا من مالكها . ولا تسرى فى هذه الحالة أحكام المادة 312 من هذا القانون المتعلقة بالإعفاء من العقوبة ."}, {"number": "323 مكرر", "chapter": "الباب الثامن", "text": "ويعتبر فى حكم السرقة كذلك اختلاس الأشياء المنقولة الواقع ممن رهنها ضمانا لدين عليه أو على آخر. ولا تسرى فى هذه الحالة أحكام المادة 312 من هذا القانون إذا وقع الاختلاس إضرارا بغير من ذكروا بالمادة المذكورة ."}, {"number": "323 مكرر", "chapter": "الباب الثامن", "text": "أولاً) : يعاقب كل من استولى بغير حق وبدون نية التملك على سيارة مملوكة لغيره بالحبس مدة لا تزيد على سنة ، وبغرامة لا تقل عن مائة جنيه ولا تتجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين ."}, {"number": "324", "chapter": "الباب الثامن", "text": "كل من قلد مفاتيح أو غير فيها أو صنع آلة ما مع توقع استعمال ذلك فى ارتكاب جريمة يعاقب بالحبس مع الشغل مدة لا تزيد على سنتين . أما إذا كان الجانى محترفا بصناعة عمل المفاتيح والأقفال فيعاقب بالحبس مع الشغل ."}, {"number": "324 مكرر", "chapter": "الباب الثامن", "text": "يعاقب بالحبس مدة لا تتجاوز ستة أشهر وبغرامة لا تتجاوز مائتى جنيه أو بإحدى هاتين العقوبتين كل من يتناول طعاما أو شرابا فى محل معد لذلك ولو كان مقيما فيه أو شغل غرفة أو أكثر فى فندق أو نحوه أو استأجر سيارة معدة للإيجار مع علمه أنه يستحيل عليه دفع الثمن أو الأجرة أو امتنع بغير مبرر عن دفع ما استحق من ذلك أو فر دون الوفاء به ."}, {"number": "325", "chapter": "الباب الثامن", "text": "كل من اغتصب بالقوة أو التهديد سندا مثبتا أو موجدا لدين أو تصرف أو براءة أو سندا ذا قيمة أدبية أو اعتبارية أو أوراقا تثبت وجود حالة قانونية أو اجتماعية أو أكره أحدا بالقوة أو التهديد على إمضاء ورقة مما تقدم أو ختمها يعاقب بالسجن المشدد ."}, {"number": "326", "chapter": "الباب الثامن", "text": "كل من حصل بالتهديد على إعطائه مبلغا من النقود أو أى شىء آخر يعاقب بالحبس . ويعاقب الشروع فى ذلك بالحبس مدة لا تتجاوز سنتين ."}, {"number": "327", "chapter": "الباب الثامن", "text": "كل من هدد غيره كتابة بارتكاب جريمة ضد النفس أو المال معاقب عليها بالقتل أو السجن المؤبد أو المشدد أو بإفشاء أمور أو نسبة أمور مخدشة بالشرف وكان التهديد مصحوبا بطلب أو بتكليف بأمر يعاقب بالسجن. ويعاقب بالحبس إذا لم يكن التهديد مصحوبا بطلب أو بتكليف بأمر. وكل من هدد غيره شفهيا بواسطة شخص آخر بمثل ما ذكر يعاقب بالحبس مدة لا تزيد على سنتين أو بغرامة لا تزيد على خمسمائة جنيه سواء أكان التهديد مصحوبا بتكليف بأمر أم لا. وكل تهديد سواء أكان بالكتابة أم شفهيا بواسطة شخص آخر بارتكاب جريمة لا تبلغ الجسامة المتقدمة يعاقب عليه بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تزيد على مائتى جنيه ."}, {"number": "328", "chapter": "الباب التاسع", "text": "كل تاجر وقف عن دفع ديونه يعتبر فى حالة تفالس بالتدليس فى الأحوال الآتية : أولا : إذا أخفى دفاتره أو أعدمها أو غيرها . ثانيا : إذا اختلس أو خبأ جزء من ماله إضرارا بدائنيه . ثالثا: إذا اعترف أو جعل نفسه مدينا بطريق التدليس بمبالغ ليست فى ذمته حقيقة سواء كان ذلك ناشئا عن مكتوباته أو ميزانيته أو غيرهما من الأوراق أو عن إقراره الشفاهى أو عن امتناعه عن تقديم أوراق أو إيضاحات مع علمه بما يترتب على ذلك الامتناع."}, {"number": "329", "chapter": "الباب التاسع", "text": "يعاقب المتفالس بالتدليس ومن شاركه فى ذلك بالسجن من ثلاث سنوات إلى خمس ."}, {"number": "330", "chapter": "الباب التاسع", "text": "يعد متفالسا بالتقصير على وجه العموم كل تاجر أوجب خسارة دائنيه بسبب عدم حزمه أو تقصيره الفاحش وعلى الخصوص التاجر الذى يكون فى إحدى الأحوال الآتية: أولاً : إذا رئى أن مصاريفه الشخصية أو مصاريف منزله باهظة. ثانياً : إذا استهلك مبالغ جسيمة فى القمار أو أعمال النصيب المحض أو فى أعمال البورصة الوهمية أو فى أعمال وهمية على بضائع . ثالثاً : إذا اشترى بضائع ليبيعها بأقل من أسعارها حتى يؤخر إشهار إفلاسه أو اقترض مبالغ أو أصدر أوراقا مالية أو استعمل طرقا أخرى مما يوجب الخسائر الشديدة لحصوله على النقود حتى يؤخر إشهار إفلاسه . رابعاً : إذا حصل على الصلح بطريق التدليس ."}, {"number": "331", "chapter": "الباب التاسع", "text": "يجوز أن يعتبر متفالسا بالتقصير كل تاجر يكون فى إحدى الأحوال الآتية : أولاً : عدم تحريره الدفاتر المنصوص عليها فى المادة 11 من قانون التجارة أو عدم إجراءه الجرد المنصوص عليه فى المادة 13 أو إذا كانت دفاتره غير كاملة أو غير منتظمة بحيث لا تعرف منها حالة الحقيقة فى المطلوب له والمطلوب منه وذلك كله مع عدم وجود التدليس. ثانياً : عدم إعلانه التوقف عن الدفع فى الميعاد المحدد فى المادة 198 من قانون التجارة أو عدم تقديمه الميزانية طبقا للمادة 199 أو ثبوت عدم صحة البيانات الواجب تقديمها بمقتضى المادة 200 . ثالثاً : عدم توجهه بشخصه إلى مأمور التفليسة عند عدم وجود الأعذار الشرعية أو عدم تقديم البيانات التى يطلبها المأمور المذكور أو ظهور عدم صحة تلك البيانات . رابعاً : تأديته عمدا بعد توقف الدفع مطلوب أحد دائنيه أو تمييزه إضرارا بباقى الغرماء أو إذا سمح له بمزية خصوصية بقصد الحصول على قبول الصلح . خامساً : إذا حكم بإفلاسه قبل أن يقوم بالتعهدات المترتبة على صلح سابق ."}, {"number": "332", "chapter": "الباب التاسع", "text": "إذا أفلست شركة مساهمة أو شركة حصص فيحكم على أعضاء مجلس إدارتها ومديريها بالعقوبات المقررة للتفالس بالتدليس إذا ثبت عليهم أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى المادة 328 من هذا القانون أو إذا فعلوا ما يترتب عليه إفلاس الشركة بطريق الغش أو التدليس وعلى الخصوص إذا ساعدوا على توقف الشركة عن الدفع سواء بإعلانهم ما يخالف الحقيقة عن رأس المال المكتتب أو المدفوع أو بتوزيعهم أرباحا وهمية أو بأخذهم لأنفسهم بطريق الغش ما يزيد عن المرخص لهم به فى عقد الشركة."}, {"number": "333", "chapter": "الباب التاسع", "text": "ويحكم فى تلك الحالة على أعضاء مجلس الإدارة والمديرين المذكورين بالعقوبات المقررة للتفالس بالتقصير . أولا : إذا ثبت عليهم أنهم ارتكبوا أمرا من الأمور المنصوص عليها فى الحالتين الثانية والثالثة من المادة 330 وفى الأحوال الأولى والثانية والثالثة والرابعة من المادة 331 من هذا القانون . ثانيا : إذا أهملوا بطريق الغش فى نشر عقد الشركة بالكيفية التى نص عليها القانون . ثالثا : إذا اشتركوا فى أعمال مغايرة لما فى قانون نظام الشركة وصدقوا عليها ."}, {"number": "334", "chapter": "الباب التاسع", "text": "يعاقب المتفالس بالتقصير بالحبس مدة لا تتجاوز سنتين ."}, {"number": "335", "chapter": "الباب التاسع", "text": "يعاقب الأشخاص الآتى بيانهم فيما عدا أحوال الاشتراك المبينة قانونا بالحبس وبغرامة لا تزيد على خمسمائة جنيه مصرى أو بإحدى هاتين العقوبتين فقط : أولا : كل شخص سرق أو أخفى أو خبأ كل أو بعض أموال المفلس من المنقولات أو العقارات ولو كان ذلك الشخص زوج المفلس أو من فروعه أو من أصوله أو انسبائه الذين فى درجة الفروع والأصول . ثانيا : من لا يكونون من الدائنين ويشتركون فى مداولات الصلح بطريق الغش أو يقدمون ويثبتون بطريق الغش فى تفليسة سندات ديون صورية باسمهم أو باسم غيرهم . ثالثا : الدائنون الذين يزيدون قيمة ديونهم بطريق الغش أو يشترطون لأنفسهم مع المفلس أو غيره مزايا خصوصية فى نظير إعطاء صوتهم فى مداولات الصلح أو التفليسة أو الوعد بإعطائه أو يعقدون مشارطة خصوصية لنفعهم وإضرارا بباقى الغرماء . رابعا: وكلاء الدائنين الذين يختلسون شيئا أثناء تأدية وظيفتهم. ويحكم القاضى أيضا ومن تلقاء نفسه فيما يجب رده إلى الغرماء وفى التعويضات التى تطلب باسمهم إذا اقتضى الحال ذلك ولو فى حالة الحكم بالبراءة. البـاب العاشـر النصـب و خيانـة الأمانة"}, {"number": "336", "chapter": "الباب التاسع", "text": "يعاقب بالحبس كل من توصل إلى الاستيلاء على نقود أو عروض أو سندات دين أو سندات مخالصة أو أى متاع منقول وكان ذلك بالاحتيال لسلب كل ثروة الغير أو بعضها إما باستعمال طرق احتيالية من شأنها إيهام الناس بوجود مشروع كاذب أو واقعة مزورة أو إحداث الأمل بحصول ربح وهمى أو تسديد المبلغ الذى أخذ بطريق الاحتيال أو إيهامهم بوجود سند دين غير صحيح أو سند مخالصة مزور وإما بالتصرف فى مال ثابت أو منقول ليس ملكا له ولا له حق التصرف فيه وإما باتخاذ اسم كاذب أو صفة غير صحيحة أما من شرع فى النصب ولم يتممه فيعاقب بالحبس مدة لا تتجاوز سنة . ويجوز جعل الجانى فى حالة العود تحت ملاحظة البوليس مدة سنة على الأقل وسنتين على الأكثر ."}, {"number": "337", "chapter": "الباب التاسع", "text": "يحكم بهذه العقوبات على كل من أعطى بسوء نية شيكا لا يقابله رصيد قائم وقابل للسحب أو كان الرصيد أقل من قيمة الشيك أو سحب بعد إعطاء الشيك كل الرصيد أو بعضه بحيث يصبح الباقى لا يفى بقيمة الشيك أو أمر المسحوب عليه الشيك بعدم الدفع ."}, {"number": "338", "chapter": "الباب التاسع", "text": "كل من انتهز فرصة احتياج أو ضعف أو هوى نفس شخص لم تبلغ سنه الحادية والعشرين سنه كاملة أو حكم بامتداد الوصاية عليه من الجهة ذات الاختصاص وتحصل منه إضرارا به على كتابة أو ختم سندات تمسك أو مخالصة متعلقة بإقراض أو اقتراض مبلغ من النقود أو شىء من المنقولات أو على تنازل عن أوراق تجارية أو غيرها من السندات الملزمة التمسكية يعاقب أيا كانت طريقة الاحتيال التى استعملها بالحبس مدة لا تزيد على سنتين ويجوز أن يزاد عليه غرامة لا تتجاوز مائة جنيه مصرى ، وإذا كان الخائن مأمورا بالولاية أو بالوصاية على الشخص المغدور فتكون العقوبة السجن من ثلاث سنين إلى سبع ."}, {"number": "339", "chapter": "الباب التاسع", "text": "كل من انتهز فرصة ضعف أو هوى نفس شخص وأقرضه نقودا بأية طريقة كانت بفائدة تزيد على الحد الأقصى المقرر للفوائد الممكن الاتفاق عليها قانونا يعاقب بغرامة لا تزيد على مائتى جنيه . فإذا ارتكب المقرض جريمة مماثلة للجريمة الأولى فى الخمس سنوات التالية للحكم الأول تكون العقوبة الحبس لمدة لا تتجاوز سنتين وغرامة لا تتجاوز خمسمائة جنيه أو إحدى العقوبتين فقط. وكل من اعتاد على إقراض نقود بأى طريقة كانت بفائدة تزيد على الحد الأقصى للفائدة الممكن الاتفاق عليها قانونا يعاقب بالعقوبات المقررة بالفقرة السابقة ."}, {"number": "340", "chapter": "الباب التاسع", "text": "كل من إئتمن على ورقة ممضاة أو مختومة على بياض فخان الأمانة وكتب فى البياض الذى فوق الختم أو الإمضاء سند دين أو مخالصة أو غير ذلك من السندات والتمسكات التى يترتب عليها حصول ضرر لنفس صاحب الإمضاء أو الختم أو لماله عوقب بالحبس ويمكن أن يزاد عليه غرامة لا تتجاوز خمسين جنيها مصريا . وفى حالة ما إذا لم تكن الورقة الممضاة أو المختومة على بياض مسلمة إلى الخائن وإنما استحصل عليها بأى طريقة كانت فإنه يعد مزورا ويعاقب بعقوبة التزوير ."}, {"number": "341", "chapter": "الباب التاسع", "text": "كل من اختلس أو استعمل أو بدد مبالغ أو أمتعة أو بضائع أو نقودا أو تذاكر أو كتابات أخرى مشتملة على تمسك أو مخالصة أو غير ذلك إضرارا بمالكيها أو أصحابها أو واضعى اليد عليها وكانت الأشياء المذكورة لم تسلم له إلا على وجه الوديعة أو الإجارة أو على سبيل عارية الاستعمال أو الرهن أو كانت سلمت له بصفة كونه وكيلا بأجرة أو مجانا بقصد عرضها للبيع أو بيعها أو استعمالها فى أمر معين لمنفعة المالك لها أو غيره يحكم عليه بالحبس ويجوز أن يزاد عليه غرامة لا تتجاوز مائة جنيه مصرى ."}, {"number": "342", "chapter": "الباب التاسع", "text": "يحكم بالعقوبات السابقة على المالك المعين حارسا على أشيائه المحجوز عليها قضائيا أو إداريا إذا اختلس شيئا منها."}, {"number": "343", "chapter": "الباب التاسع", "text": "كل من قدم أو سلم للمحكمة فى أثناء تحقيق قضية بها سندا أو ورقة ما ثم سرق ذلك بأى طريقة كانت يعاقب بالحبس مدة لا تتجاوز ستة شهور ."}, {"number": "344", "chapter": "الباب الحادى عشر", "text": "كل من عطل بواسطة تهديد أو إكراه أو تطاول باليد أو نحوه مزادا متعلقا ببيع أو شراء أو تأجير أموال منقولة أو ثابتة أو متعلقا بتعهد بمقاولة أو توريد أو استغلال شىء أو نحو ذلك يعاقب بالحبس مدة لا تزيد على ثلاثة شهور وبغرامة لا تتجاوز خمسمائة جنيه مصرى أو بإحدى هاتين العقوبتين فقط ."}, {"number": "345", "chapter": "الباب الحادى عشر", "text": "الأشخاص الذين تسببوا فى علو أو انحطاط أسعار غلال أو بضائع أو بونات أو سندات مالية معدة للتداول عن القيمة المقررة لها فى المعاملات التجارية بنشرهم عمدا بين الناس أخبارا أو إعلانات مزورة أو مفتراة أو بإعطائهم للبائع ثـمنا أزيد مما طلبه أو بتواطؤهم مع مشاهير التجار الحائزين لصنف واحد من بضاعة أو غلال على عدم بيعه أصلا أو على منع بيعه بثمن أقل من الثمن المتفق عليه فيما بينهم أو بأى طريقة احتيالية أخرى يعاقبون بالحبس مدة لا تزيد على سنة وبغرامة لا تتجاوز خمسمائة جنيه مصرى أو بإحدى هاتين العقوبتين فقط."}, {"number": "346", "chapter": "الباب الحادى عشر", "text": "يضاعف الحد الأقصى المقرر لعقوبة الحبس المنصوص عنها فى المادة السابقة إذا حصلت تلك الحيلة فيما يتعلق بسعر اللحوم أو الخبز أو حطب الوقود والفحم أو نحو ذلك من الحاجات الضرورية ."}, {"number": "347", "chapter": "الباب الحادى عشر", "text": "ملغاة"}, {"number": "348", "chapter": "الباب الحادى عشر", "text": "ملغاة ."}, {"number": "349", "chapter": "الباب الحادى عشر", "text": "ملغاة ."}, {"number": "350", "chapter": "الباب الحادى عشر", "text": "ملغاة ."}, {"number": "351", "chapter": "الباب الحادى عشر", "text": "ملغاة . المواد من 347 الى 351 ملغاة بالقانون رقم 354 لسنة 1954 ."}, {"number": "352", "chapter": "الباب الثانى عشر", "text": "كل من أعد مكانا لألعاب القمار وهيأه لدخول الناس فيه يعاقب هو وصيارف المحل المذكور بالحبس وبغرامة لا تتجاوز ألف جنيه وتضبط جميع النقود والأمتعة فى المحلات الجارى فيها الألعاب المذكورة ويحكم بمصادرتها."}, {"number": "353", "chapter": "الباب الثانى عشر", "text": "ويعاقب بهذه العقوبات أيضا كل من وضع للبيع شيئا فى النمرة المعروفة باللوتيرى بدون إذن الحكومة وتضبط أيضا لجانب الحكومة جميع النقود والأمتعة الموضوعة فى النمرة ."}, {"number": "354", "chapter": "الباب الثالث عشر", "text": "كل من كسر آو خرّب لغيره شيئا من آلات الزراعة أو زرائب المواشى أو عشش الخفراء يعاقب بالحبس مدة لا تزيد على سنة أو بغرامة لا تتجاوز مائتى جنيه مصريا."}, {"number": "355", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مع الشغل : أولاً : كل من قتل عمدا بدون مقتضى حيوانا من دواب الركوب أو الجر أو الحمل أو من أى نوع من أنواع المواشى أو أضر به ضررا كبيرا . ثانياً : كل من سم حيوانا من الحيوانات المذكورة بالفقرة السابقة أو سمكا من الأسماك الموجودة فى نهر أو ترعة أو غدير أو مستنقع أو حوض. ويجوز جعل الجانيين تحت ملاحظة البوليس مدة سنة على الأقل وسنتين على الأكثر . وكل شروع فى الجرائم السالفة الذكر يعاقب عليه بالحبس مع الشغل مدة لا تزيد على سنة أو بغرامة لا تتجاوز مائتى جنيه مصريا."}, {"number": "356", "chapter": "الباب الثالث عشر", "text": "إذا ارتكبت الجرائم المنصوص عليها فى المادة السابقة ليلا تكون العقوبة السجن المشدد أو السجن من ثلاث سنين إلى سبع ."}, {"number": "357", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مدة لا تزيد على ستة أشهر أو بغرامة لا تتجاوز مائتى جنيه كل من قتل عمدا بدون مقتضى أو سم حيوانا من الحيوانات المستأنسة غير المذكورة فى المادة 355 أو أضر به ضررا كبيرا ."}, {"number": "358", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مدة لا تزيد على ثلاثة شهور أو بدفع غرامة لا تتجاوز مائتى جنيه مصريا من أتلف كل أو بعض محيط متخذ من أشجار خضراء أو يابسة أو غير ذلك ومن نقل أو أزال حدا أو علامات مجعولة حدا بين أملاك مختلفة أو جهات مستغلة ومن ردم كل أو بعض خندق من الخنادق المجعولة حدا لأملاك أو جهات مستغلة . وإذا ارتكب شىء من الأفعال المنصوص عليها فى الفقرة السابقة بقصد اغتصاب أرض تكون العقوبة الحبس مدة لا تتجاوز سنتين."}, {"number": "359", "chapter": "الباب الثالث عشر", "text": "كل من تسبب عمدا بقطع جسر من الجسور أو بكيفية أخرى فى حصول غرق يحكم عليه بالسجن المشدد أو بالسجن المؤبد ."}, {"number": "360", "chapter": "الباب الثالث عشر", "text": "الحريق الناشئ من عدم تنظيف أو ترميم الأفران أو المداخن أو المحلات الأخرى التى توقد فيها النار أو من النار الموقدة فى بيوت أو مبان أو غابات أو كروم أو غيطان أو بساتين بالقرب من كيمان تبن أو حشيش يابس وكذا الحريق الناشئ عن إشعال صواريخ فى جهة من جهات البلدة أو بسبب إهمال آخر يعاقب عليه بالحبس مدة لا تزيد على شهر أو بدفع غرامة لا تزيد على مائتى جنيه مصرى . فإذا وقع الحريق من التدخين أو من نار موقدة فى محطات لخدمة وتموين السيارات أو محطات للغاز الطبيعى أو مراكز لبيع اسطوانات البوتاجاز أو مستودعات للمنتجات البترولية أو مخازن مشتملة على مواد الوقود أو أى مواد أخرى قابلة للاشتعال ، تكون العقوبة الحبس والغرامة التى لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه أو إحدى هاتين العقوبتين."}, {"number": "361", "chapter": "الباب الثالث عشر", "text": "كل من خرب أو أتلف عمدا أموالا ثابتة أو منقولة لا يمتلكها أو جعلها غير صالحة للاستعمال أو عطلها بأية طريقة يعاقب بالحبس مدة لا تزيد على ستة أشهر وبغرامة لا تجاوز ثلاثـمائة جنيه أو بإحدى هاتين العقوبتين . فإذا ترتب على الفعل ضرر مالى قيمته خمسون جنيها أو أكثر كانت العقوبة الحبس مدة لا تجاوز سنتين وغرامة لا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين . وتكون العقوبة السجن مدة لا تزيد على خمس سنين وغرامة لا تقل عن مائة جنيه ولا تتجاوز ألف جنيه إذا نشأ عن الفعل تعطيل أو توقيف أعمال مصلحة ذات منفعة عامة أو إذا ترتب عليه جعل حياة الناس أو صحتهم أو أمنهم فى خطر. ويضاعف الحد الأقصى للعقوبات المقررة فى المادة 361 إذا ارتكبت الجريمة تنفيذا لغرض إرهابى."}, {"number": "361 مكرر", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مدة لا تزيد على خمس سنوات كل من خرب المنشآت الثابتة أو الوحدات الصحية المتنقلة للقسم الطبى فى الجيش أو التابعة له أو أدوات هذه المنشآت أو الوحدات أو عطل شيئا من المنشآت أو الوحدات أو الأدوات المذكورة أو جعلها غير صالحة للاستعمال ."}, {"number": "361 مكرر", "chapter": "الباب الثالث عشر", "text": "أ) : كل من عطل عمدا بأية طريقة كانت وسيلة من وسائل خدمات المرافق العامة أو وسيلة من وسائل الإنتاج يعاقب بالسجن . وتكون العقوبة السجن المشدد إذا وقعت الجريمة بقصد الإضرار بالإنتاج أو الإخلال بسير مرفق عام ."}, {"number": "362", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مدة لا تتجاوز سنتين أو بغرامة لا تزيد على ثلاثـمائة جنيه كل من هدم أو أتلف أو نقل علامات جيوديزية أو طبوغرافية أو طودات محادة أو أوتاد حدود أو طودات ميزانية ."}, {"number": "363", "chapter": "الباب الثالث عشر", "text": "ملغاة بالقانون رقم 50 لسنة 1949"}, {"number": "364", "chapter": "الباب الثالث عشر", "text": "كل من تعرض بدون اقتضاء بواسطة ضرب ونحوه لمنع ما أمرت أو صرحت الحكومة بإجرائه من الأشغال العمومية يعاقب بالحبس مدة لا تزيد على سنة أو بغرامة لا تزيد على ثلاثـمائة جنيه مصرى."}, {"number": "365", "chapter": "الباب الثالث عشر", "text": "كل من أحرق أو أتلف عمدا بأى طريقة كانت شيئا من الدفاتر أو المضابط الأصلية أو السجلات أو نحوها من أوراق المصالح الأميرية أو الكمبيالات أو الأوراق التجارية أو الصيرفية أو غير ذلك من السندات التى يتسبب عن إتلافها ضرر للغير يعاقب بالحبس وبغرامة لا تتجاوز خمسمائة جنيه مصريا أو بإحدى هاتين العقوبتين فقط ."}, {"number": "366", "chapter": "الباب الثالث عشر", "text": "كل نهب أو إتلاف شىء من البضائع أو الأمتعة أو المحصولات وقع من جماعة أو عصابة بالقوة الإجبارية يكون عقابه السجن المشدد أو السجن."}, {"number": "367", "chapter": "الباب الثالث عشر", "text": "يعاقب بالحبس مع الشغل : أولا : كل من قطع أو أتلف زرعا غير محصود أو شجرا نابتا خلقه أو مغروسا أو غير ذلك من النبات . ثانيا : كل من أتلف غيطا مبذورا أو بث فى غيط حشيشا أو نباتا مضرا . ثالثا : كل من اقتلع شجرة أو أكثر أو أى نبات آخر أو قطع منها أو قشرها ليميتها وكل من أتلف طعمة فى شجر . ويجوز جعل الجانيين تحت ملاحظة البوليس مدة سنة على الأقل وسنتين على الأكثر ."}, {"number": "368", "chapter": "الباب الثالث عشر", "text": "إذا ارتكبت الجرائم المنصوص عليها فى الفقرتين الأولى والثانية من المادة السابقة ليلا من ثلاثة أشخاص على الأقل أو من شخص أو اثنين وكان واحد منهما على الأقل حاملا لسلاح تكون العقوبة السجن المشدد أو السجن من ثلاث سنين إلى سبع ."}, {"number": "369", "chapter": "الباب الرابع عشر", "text": "كل من دخل عقارًا فى حيازة آخر بقصد منع حيازته أو بقصد ارتكاب جريمة فيه أو كان قد دخله بوجه قانونى وبقى فيه بعد زوال سنده القانونى بقصد ارتكاب شئ مما ذكر، يعاقب بالحبس مدة لا تقل عن سنتين ولا تزيد على خمس سنوات وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على خمسمائة ألف جنيه. فإذا وقعت الجريمة بالتحايل، أو نتيجة تقديم إقرارات أو الإدلاء ببيانات غير صحيحة مع العلم بذلك تكون العقوبة الحبس مدة لا تقل عن سنتين ولا تزيد على سبع سنوات وغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مليون جنيه. وإذا وقعت الجريمة باستخدام القوة، أو من شخصين أو أكثر وكان أحدهم على الأقل حاملاً سلاحًا، تكون العقوبة الحبس مدة لا تقل عن ثلاث سنوات ولا تزيد على سبع سنوات وغرامة لا تقل عن خمسمائة ألف جنيه ولا تزيد على مليون جنيه. ويعاقب بذات العقوبة المبينة فى الفقرة الأولى كل من دخل عقارًا صدر حكم أو أمر قضائى بتمكين آخر من حيازته, وذلك بقصد منع حيازته أو الانتقاص منها. وتطبق العقوبة المبينة بالفقرة الثالثة حال توافر الظروف المبينة بها، فإذا ارتكب الفعل ذاته خلال مدة لا تزيد على سنة من تاريخ ارتكاب الفعل الأول تكون العقوبة الحبس مدة لا تقل عن ثلاث سنوات و لا تزيد على عشر سنوات والغرامة التى لا تقل عن ثلاثـمائة ألف جنيه ولا تزيد على مليونى جنيه. ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "370", "chapter": "الباب الرابع عشر", "text": "كل من دخل بيتًا مسكونًا أو معدًا للسكن أو فى أحد ملحقاته أو سفينة مسكونة أو فى محل معد لحفظ المال وكانت هذه الأشياء فى حيازة آخر قاصدًا من ذلك منع حيازته أو ارتكاب جريمة فيها أو كان قد دخلها بوجه قانونى وبقى فيها بعد زوال سنده القانونى، وذلك بقصد ارتكاب شئ مما ذكر، يعاقب بالحبس مدة لا تقل عن سنتين ولا تزيد على خمس سنوات وبغرامة لا تقل عن مائة ألف جنيه ولا تزيد على خمسمائة ألف جنيه. فإذا وقعت الجريمة بالتحايل، أو نتيجة تقديم إقرارات أو الإدلاء ببيانات غير صحيحة مع العلم بذلك، تكون العقوبة الحبس مدة لا تقل عن سنتين ولا تزيد على سبع سنوات وغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مليون جنيه. وإذا وقعت الجريمة ليلاً أو باستخدام القوة أو بواسطة كسر أو تسلق من شخص حامل لسلاح أو من عشرة أشخاص على الأقل ولو لم يكن معهم سلاح، تكون العقوبة الحبس مدة لا تقل عن ثلاث سنوات ولا تزيد على سبع سنوات وغرامة لا تقل عن خمسمائة ألف جنيه ولا تزيد على مليون جنيه. ويعاقب بذات العقوبة المبينة فى الفقرة الأولى كل نم دخل أحد العقارات المبينة بالفقرة ذاتها وكان قد صدر حكم أو أمر قضائى بتمكين آخر من حيازته، وذلك بقصد منع حيازته أو الانتقاص منها. وتطبق العقوبة المبينة بالفقرة الثالثة حال توافر الظروف المبينة بها، فإذا ارتكب الفعل ذاته خلال مدة لا تزيد على سنة من تاريخ ارتكاب الفعل الأول تكون العقوبة الحبس مدة لا تقل عن ثلاث سنوات ولا تزيد على عشر سنوات والغرامة التى لا تقل عن ثلاثـمائة أ لف جنيه ولا تزيد على مليونى جنيه. ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "371", "chapter": "الباب الرابع عشر", "text": "كل من وجد فى إحدى المحلات المنصوص عليها فى المادة (&#1635;&#1639;&#1632;) من هذا القانون مختفيًا عن أعين من لهم الحق فى إخراجه، يُعاقب بالحبس مدة لا تجاوز سنة أو بالغرامة التى لا تقل عن عشرة آلاف جنيه ولا تزيد على مائة ألف جنيه . ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "372", "chapter": "الباب الرابع عشر", "text": "مع عدم الإخلال بأى عقوبة أشد منصوص عليها فى قانون آخر، إذا ارتكبت الجريمة المنصوص عليها فى المادة (&#1635;&#1639;&#1633;) من هذا القانون ليلاً تكون العقوبة الحبس مدة لا تقل عن سنة ولا تزيد على ثلاث سنوات وغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مائتى ألف جنيه . أما لو ارتكبت الجريمة ليلاً بواسطة كسر أو تسلق أو من شخص حامل لسلاح، تكون العقوبة الحبس مدة لا تقل عن سنتين ولا تزيد على خمس سنوات وغرامة لا تقل عن خمسمائة ألف جنيه ولا تزيد على مليون جنيه. ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "372 مكرر", "chapter": "الباب الرابع عشر", "text": "كل من تعدى على أرض زراعية، أو أرض فضاء، أو مبانٍ مملوكة للدولة أو لأحد الأشخاص الاعتبارية العامة أو لوقف خيرى أو لإحدى شركات القطاع العام أو لأى جهة أخرى ينص القانون على اعتبار أموالها من الأموال العامة أو فى حيازة أى منها، وذلك بزراعتها أو غرسها أو إقامة إنشاءات عليها أو شغلها أو الانتفاع بها بأى صورة، يُعاقب بالحبس مدة لا تقل عن سنتين ولا تزيد على خمس سنوات وبغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مليون جنيه. ويحكم على الجانى برد العقار المغتصب بما عليه من مبان أو غراس أو برده مع إزالة ما عليه من تلك الأشياء على نفقته، فضلاً عن دفع قيمة ما عاد عليه م منفعة. فإذا وقعت الجريمة بالتحايل، أو نتيجة تقديم إقرارات أو الإدلاء ببيانات غير صحيحة مع العلم بذلك، تكون العقوبة الحبس مدة لا تقل عن سنتين ولا تزيد على سبع سنوات وغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مليون جنيه. وتضاعف العقوبة المنصوص عليها فى الفقرتين السابقتين فى حالة العود. ( [1] ) مستبدلة بالقانون 164لسنة 2019"}, {"number": "373", "chapter": "الباب الرابع عشر", "text": "كل من دخل أرضا زراعية أو فضاء أو مبانى أو بيتا مسكونا أو معدا للسكن أو فى أحد ملحقاته أو سفينة مسكونة أو فى محل معد لحفظ المال ولم يخرج منه بناء على تكليفه ممن لهم الحق فى ذلك يعاقب بالحبس مدة لا تجاوز ستة أشهر أو بغرامة لا تجاوز مائتى جنيه ."}, {"number": "373 مكرر", "chapter": "الباب الرابع عشر", "text": "ملغاة المادة ملغاة بالقانون رقم 23 لسنة 1992"}, {"number": "374", "chapter": "الباب الخامس عشر", "text": "يحظر على المستخدمين والأجراء الذين يقومون بخدمة عامة أو بالخدمة فى المرافق العامة أو بعمل يسد حاجة عامة ولو لم يكن موضوعا لها نظام خاص أن يتركوا عملهم أو يمتنعوا عنه عمدا . وتجرى فى شأن ذلك جميع الأحكام المبينة فى المادتين 124و124(أ). وتطبق العقوبات المنصوص عليها فيهما على هؤلاء المستخدمين والأجراء وعلى المحرضين والمشجعين والمحبذين والمذيعين على حسب الأحوال ."}, {"number": "374 مكرر", "chapter": "الباب الخامس عشر", "text": "يحظر على المتعهدين وعلى كل من يدير مرفقا أو عملا من الأعمال العامة المشار إليها فى المادة السابقة أن يوقفوا العمل بكيفية يتعطل معها أداء الخدمة العامة وانتظامها. وتطبق عليهم وعلى المحرضين والمشجعين والمحبذين والمذيعين العقوبات المنصوص عليها فى المادتين 124و124(أ) على حسب الأحوال ."}, {"number": "375", "chapter": "الباب الخامس عشر", "text": "يعاقب بالحبس مدة لا تجاوز سنتين وبغرامة لا تزيد على مائة جنيه كل من استعمل القوة أو العنف أو الإرهاب أو التهديد أو تدابير غير مشروعة فى الاعتداء أو الشروع فى الاعتداء على حق من الحقوق الآتية : أولاً : حق الغير فى العمل . ثانياً : حق الغير فى أن يستخدم أو يمتنع عن استخدام أى شخص. ثالثاً : حق الغير فى أن يشترك فى جمعية من الجمعيات . ويطبق حكم هذه المادة ولو استعملت القوة أو العنف أو الإرهاب أو التدابير غير المشروعة مع زوج الشخص المقصود أو مع أولاده . وتعد من التدابير غير المشروعة الأفعال الآتية على الأخص : أولا ً: تتبع الشخص المقصود بطريقة مستمرة فى غدوه ورواحه أو الوقوف موقف التهديد بالقرب من منزله أو بالقرب من أى مكان آخر يقطنه أو يشتغل فيه . ثانياً : منعه من مزاولة عمله بإخفاء أدواته أو ملابسه أو أى شىء آخر مما يستعمله أو بأية طريقة أخرى . ويعاقب بنفس العقوبات السالف ذكرها كل من يحرض الغير بأية طريقة على ارتكاب جريمة من الجرائم المنصوص عليها فى هذه المادة . البـاب السـادس عشر الترويـع والتخويـف (البلطجــــة) ( [1] ) الباب مضاف بالمرسوم بقانون رقم 10 لسنة 2011."}, {"number": "375 مكرر", "chapter": "الباب الخامس عشر", "text": "مع عدم الإخلال بأية عقوبة أشد واردة فى نص آخر ، يعاقب بالحبس مدة لا تقل عن سنة كل من قام بنفسه أو بواسطة الغير باستعراض القوة أو التلويح بالعنف أو التهديد بأيهما أو استخدامه ضد المجنى عليه أو مع زوجه أو أحد أصوله أو فروعه ، وذلك بقصد ترويعه أو التخويف بإلحاق أى أذى مادى أو معنوى به أو الإضرار بممتلكاته أو سلب ماله أو الحصول على منفعة منه أو التأثير فى إرادته لفرض السطوة عليه أو إرغامه على القيام بعمل أو حمله على الامتناع عنه أو لتعطيل تنفيذ القوانين أو التشريعات أو مقاومة السلطات أو منع تنفيذ الأحكام ، أو الأوامر أو الإجراءات القضائية واجبة التنفيذ أو تكدير الأمن أو السكينه العامة ، متى كان من شأن ذلك الفعل أو التهديد إلقاء الرعب فى نفس المجنى عليه أو تكدير أمنه أو سكينته أو طمأنينته أو تعريض حياته أو سلامته للخطر أو إلحاق الضرر بشئ من ممتلكاته أو مصالحه أو المساس بحريته الشخصية أو شرفه أو اعتباره. وتكون العقوبة الحبس مدة لا تقل عن سنتين ولا تجاوز خمس سنوات إذا وقع الفعل من شخصين فأكثر ، أو باصطحاب حيوان يثير الذعر ، أو بحمل أية أسلحة أو عصى أو آلات أو أدوات أو مواد حارقة أو كاوية أو غازية أو مخدرات أو منومة أو أية مواد أخرى ضارة ، أو إذا وقع الفعل على أنثى، أو على من لم يبلغ ثـمانى عشرة سنة ميلادية كاملة . ويقضى فى جميع الأحوال بوضع المحكوم عليه تحت مراقبة الشرطة مدة مساوية لمدة العقوبة المحكوم بها ."}, {"number": "375 مكرر", "chapter": "الباب الخامس عشر", "text": "أ): : يضاعف كل من الحدين الأدنى والأقصى للعقوبة المقررة لأية جنحة أخرى تقع بناءً على ارتكاب الجريمة المنصوص عليها فى المادة السابقة ، ويرفع الحد الأقصى لعقوبتى السجن والسجن المشدد إلى عشرين سنة لآية جناية أخرى تقع بناءً على ارتكابها . وتكون العقوبة السجن المشدد أو السجن إذا ارتكبت جناية الجرح أو الضرب أو إعطاء المواد الضارة المفضى إلى موت المنصوص عليها فى المادة (236) من قانون العقوبات بناءً على ارتكاب الجريمة المنصوص عليها فى المادة السابقة، فإذا كانت مسبوقة بإصرار أو ترصد تكون العقوبة السجن المؤبد أو المشدد . وتكون العقوبة الإعدام إذا تقدمت الجريمة المنصوص عليها فى المادة 375 مكرراً أو اقترنت أو ارتبطت بها أو تلتها جناية القتل العمد المنصوص عليها فى الفقرة الأولى من المادة (234) من قانون العقوبات . ويقضى فى جميع الأحوال بوضع المحكوم عليه بعقوبة مقيدة للحرية تحت مراقبة الشرطة مدة مساوية لمدة العقوبة المحكوم بها عليه بحيث لا تقل عن سنة و تجاوز خمس سنين . الكتـاب الرابـع الـمخالفـات الـمخالفات المتعلقـة بالطـرق العمـوميـة"}, {"number": "376", "chapter": "الباب الخامس عشر", "text": "تلغى عقوبة الحبس الذى لا يزيد أقصى مدته على أسبوع فى كل نص ورد فى قانون العقوبات أو فى أى قانون آخر وفى هذه الأحوال تضاعف عقوبة الغرامة المقررة بكل من هذه النصوص بحد أدنى مقداره عشرة جنيهات وبحد أقصى مقداره مائة جنيه. الـمخالفات الـمتعلقة بالأمن العام أو الراحة العمومية"}, {"number": "377", "chapter": "الباب الخامس عشر", "text": "يعاقب بغرامة لا تجاوز مائة جنيه كل من ارتكب فعلا من الأفعال الآتية : 1 - من ألقى فى الطريق بغير احتياط أشياء من شأنها جرح المارين أو تلويثهم إذا سقطت عليهم . 2 - من أهمل فى تنظيف أو إصلاح المداخن أو الأفران أو المعامل التى تستعمل فيها النار . 3 - من كان موكلا بالتحفظ على مجنون فى حالة هياج فأطلقه أو كان موكلا بحيوان من الحيوانات المؤذية أو المفترسة فأفلته . 4 - من حرش كلبا واثبا على مار أو مقتفيا أثره أو لم يرده عنه إذا كان الكلب فى حفظه ولو لم يتسبب عن ذلك أذى ولا ضرر . 5 - من ألهب بغير إذن صواريخ أو نحوها فى الجهات التى يمكن أن ينشأ عن إلهابها فيها إتلاف أو أخطار . 6 - من أطلق فى داخل المدن أو القرى سلاحا ناريا أو ألهب فيها أعيرة نارية أو مواد أخرى مفرقعة . 7 - من امتنع أو أهمل فى أداء أعمال مصلحة أو بذل مساعدة وكان قادرا عليها عند طلب ذلك من جهة الاقتضاء فى حالة حصول حادث أو هياج أو غرق أو فيضان أو حريق أو نحو ذلك وكذا فى حالة قطع الطريق أو النهب أو التلبس بجريمة أو حالة تنفيذ أمر أو حكم قضائى . 8 - من امتنع عن قبول عملة البلاد أو مسكوكاتها بالقيمة المتعامل بها ولم تكن مزورة ولا مغشوشة . 9 - من وقعت منه مشاجرة أو تعد أو إيذاء خفيف ولم يحصل ضرب وجرح."}, {"number": "378", "chapter": "الباب الخامس عشر", "text": "يعاقب بغرامة لا تجاوز خمسين جنيها كل من ارتكب فعلا من الأفعال الآتية : 1 - من رمى أحجارا أو أشياء أخرى صلبة أو قاذورات على عربات أو سيارات أو بيوت أو مبان أو محوطات ملك غيره أو على بساتين أو حظائر . 2 - من رمى فى النيل أو الترع أو المصارف أو مجارى المياه الأخرى أدوات أو أشياء أخرى يمكن أن تعوق الملاحة أو تزحم مجارى تلك المياه . 3 - من قطع الخضرة النابتة فى المحلات المخصصة للمنفعة العامة أو نزع الأتربة منها ، أو الأحجار أو مواد أخرى ولم يكن مأذونا بذلك. 4 - من أتلف أو خلع أو نقل الصفائح أو النمر أو الألواح الموضوعة على الشوارع أو الأبنية . 5 - من أطفأ نور الغاز أو المصابيح أو الفوانيس المعدة لإنارة الطرق ، وكذا من أتلف أو خلع أو نقل شيئا منها أو من أدواتها . 6 - من تسبب بإهماله فى إتلاف شىء من منقولات الغير . 7 - من تسبب فى موت أو جرح بهائم أو دواب الغير بعدم تبصره أو بإهماله أو عدم مراعاته للوائح . 8 - من ترك أولاده حديثى السن أو مجانين موكولين لحفظه يهيمون وعرضهم بذلك للأخطار أو الإصابات . 9 - من ابتدر إنسانا بسب غير علنى ."}, {"number": "379", "chapter": "الباب الخامس عشر", "text": "يعاقب بغرامة لا تجاوز خمسة وعشرين جنيها كل من ارتكب فعلا من الأفعال الآتية : 1 - من ركض فى الجهات المسكونة خيلا أو دواب أخرى أو تركها تركض فيها . 2 - من حصل منه فى الليل لغط أو ضجيج مما يكدر راحة السكان. 3 - من وضع فى المدن على سطح أو حيطان مسكنه مواد مركبة من فضلات أو روث البهائم أو غيرها مما يضر بالصحة العمومية . 4 - من دخل فى أرض مهيأة للزرع أو مبذور فيها زرع أو محصول أو مر فيها بمفرده أو ببهائمه أو دوابه المعدة للجر أو الحمل أو الركوب أو ترك هذه البهائم أو الدواب تمر فيها أو ترعى فيها بغير حق ."}, {"number": "380", "chapter": "الباب الخامس عشر", "text": "من خالف أحكام اللوائح العامة أو المحلية الصادرة من جهات الإدارة العامة أو المحلية يجازى بالعقوبات المقررة فى تلك اللوائح بشرط ألا تزيد على خمسين جنيها ، فإن كانت العقوبات المقررة فى اللوائح زائدة عن هذه الحدود وجب حتما إنزالها إليها . فإذا كانت اللائحة لا تنص على عقوبة ما يجازى من يخالف أحكامها بدفع غرامة لا تزيد على خمسة وعشرين جنيهاً . المخالفات الـمتعلقة بالصحة العمومية نص المواد من 381 الى 395 ملغاة بالقانون رقم 169 لسنة 1981"}]};